    USER_LIBRARY = File.join(ENV['APPDATA'] || Dir.home, 'LVNTools', 'PhaoChiV59', 'user_profiles.json')
    EXTERNAL_MODEL_LIBRARY = File.join(ENV['APPDATA'] || Dir.home, 'LVNTools', 'PhaoChiV59', 'external_models')

    # V5.9.9.200: lấy model SKP từ thư viện ngoài và lưu bền vững vào kho của LOFIHOME.
    def self.import_external_model_to_library
      path = UI.openpanel('Chọn mẫu SKP từ thư viện ngoài', '', 'SketchUp Model|*.skp||')
      return unless path
      raise 'Chỉ hỗ trợ file SKP cho kho mẫu model.' unless File.extname(path).downcase == '.skp'
      FileUtils.mkdir_p(EXTERNAL_MODEL_LIBRARY)
      base = File.basename(path, '.skp').gsub(/[\\\/:*?"<>|]/, '_').strip
      base = 'Mau_SKP' if base.empty?
      dest = File.join(EXTERNAL_MODEL_LIBRARY, base + '.skp')
      if File.exist?(dest)
        ans = UI.messagebox("Mẫu '#{base}' đã có trong thư viện.\nGhi đè bằng file mới?", MB_YESNO)
        return unless ans == IDYES
      end
      FileUtils.cp(path, dest)
      UI.messagebox("Đã lưu mẫu vào thư viện LOFIHOME.\n\nTên: #{File.basename(dest)}\nKho: #{EXTERNAL_MODEL_LIBRARY}")
      dest
    rescue => e
      UI.messagebox("Không lưu được mẫu ngoài:\n#{e.class}: #{e.message}")
      nil
    end

    # V5.9.9.200: dùng THƯ VIỆN NGOÀI THEO ĐƯỜNG DẪN.
    # Không copy hàng trăm file SKP vào plugin. Chỉ ghi nhớ thư mục người dùng chọn.
    EXTERNAL_FOLDER_PREF = 'external_skp_folder'

    def self.saved_external_folder
      portable_initialize
      path = Sketchup.read_default('LVN_PhaoChi_V599176', EXTERNAL_FOLDER_PREF, '').to_s
      return path if File.directory?(path) && !scan_external_skp(path).empty?
      FileUtils.mkdir_p(portable_model_folder)
      portable_model_folder
    end

    def self.scan_external_skp(folder)
      return [] unless folder && File.directory?(folder)
      # Quét đệ quy, không phụ thuộc chữ hoa/chữ thường của phần mở rộng.
      files = []
      begin
        Dir.glob(File.join(folder, '**', '*')).each do |f|
          files << f if File.file?(f) && File.extname(f).downcase == '.skp'
        end
      rescue
        # Fallback cho một số ổ đĩa/thư mục Windows có tên Unicode đặc biệt.
        require 'find'
        Find.find(folder) do |f|
          files << f if File.file?(f) && File.extname(f).downcase == '.skp'
        end
      end
      files.uniq.sort_by { |f| File.basename(f).downcase }
    end

    def self.import_external_folder_to_library
      folder = Compat.select_directory(:title => 'Chọn THƯ MỤC THƯ VIỆN SKP (plugin sẽ ghi nhớ đường dẫn)')
      return nil unless folder
      files = scan_external_skp(folder)
      if files.empty?
        UI.messagebox("Không tìm thấy file SKP trong thư mục hoặc các thư mục con.\n\n#{folder}\n\nHãy chọn đúng thư mục cấp trên có chứa file .SKP.")
        return nil
      end
      Sketchup.write_default('LVN_PhaoChi_V599176', EXTERNAL_FOLDER_PREF, folder)
      UI.messagebox("ĐÃ GHI NHỚ THƯ VIỆN NGOÀI.\n\nTìm thấy: #{files.length} file SKP\nThư mục: #{folder}\n\nPlugin KHÔNG copy file, nên thư viện không bị nặng.")
      folder
    rescue => e
      UI.messagebox("Không đọc được thư mục mẫu ngoài:\n#{e.class}: #{e.message}")
      nil
    end

    # Thumbnail được lưu riêng trong AppData, không đụng vào thư viện gốc.
    def self.external_thumbnail_dir
      dir = File.join(ENV['APPDATA'] || Dir.home, 'LVNTools', 'PhaoChiV599200', 'thumbs')
      FileUtils.mkdir_p(dir)
      dir
    end

    # Pre-extracted SKP previews ship with the plugin; no model load is needed.
    def self.v31721_saved_thumbnail(skp_path)
      folder=File.join(File.dirname(__FILE__),'library_thumbs')
      manifest=File.join(folder,'manifest.json')
      return nil unless File.file?(manifest) && File.file?(skp_path)
      stamp=[File.size(manifest),File.mtime(manifest).to_f]
      if !@v31721_thumbnails || @v31721_thumbnails[0]!=stamp
        data=JSON.parse(File.read(manifest,:encoding=>'UTF-8'))
        @v31721_thumbnails=[stamp,data]
      end
      key=File.expand_path(skp_path).tr('\\','/').downcase
      entry=@v31721_thumbnails[1][key]
      return nil unless entry && entry['source_bytes']==File.size(skp_path) && entry['source_mtime']==File.mtime(skp_path).to_i
      png=File.expand_path(entry['file'],folder)
      return nil unless File.dirname(png)==File.expand_path(folder) && File.file?(png)
      png
    rescue
      nil
    end

    def self.external_thumb_path(skp_path)
      sidecar = portable_sidecar(skp_path)
      return sidecar if sidecar
      prepared=v31721_saved_thumbnail(skp_path)
      return prepared if prepared
      require 'digest/md5'
      key = Digest::MD5.hexdigest(File.expand_path(skp_path).downcase)
      safe = File.basename(skp_path, File.extname(skp_path)).gsub(/[^0-9A-Za-z_\-]+/, '_')[0,60]
      File.join(external_thumbnail_dir, "#{safe}_#{key}.png")
    end

    def self.generate_external_thumbnail(skp_path, png_path)
      prepared=v31721_saved_thumbnail(skp_path)
      return prepared if prepared
      return png_path if File.exist?(png_path) && File.mtime(png_path) >= File.mtime(skp_path)
      model = Sketchup.active_model
      view = model.active_view
      old_camera = view.camera
      old_sel = model.selection.to_a
      inst = nil
      model.start_operation('LOFIHOME Thumbnail', true)
      begin
        definition = Compat.load_definition(model.definitions,Compat.model_file(v31720_light_source(skp_path)))
        inst = model.active_entities.add_instance(definition, Geom::Transformation.new)
        model.selection.clear
        model.selection.add(inst)
        view.zoom(inst)
        view.write_image(:filename=>png_path, :width=>360, :height=>260, :antialias=>true, :compression=>0.9, :transparent=>false)
        inst.erase! if inst && inst.valid?
        model.abort_operation
      rescue
        model.abort_operation rescue nil
        raise
      ensure
        view.camera = old_camera rescue nil
        model.selection.clear rescue nil
        old_sel.each { |e| model.selection.add(e) if e && e.valid? } rescue nil
        view.refresh rescue nil
      end
      png_path
    rescue
      nil
    end

    def self.v31722_name_key(path)
      require 'digest/md5'
      Digest::MD5.hexdigest(File.expand_path(path).tr('\\','/').downcase)
    end

    def self.v31722_sample_name(path)
      saved=Sketchup.read_default('LOFIHOME_LibraryNames',v31722_name_key(path),'').to_s.strip
      saved.empty? ? File.basename(path,File.extname(path)) : saved
    end

    def self.v31722_save_sample_name(path,name)
      raise 'Không tìm thấy file mẫu.' unless File.file?(path)
      name=name.to_s.strip
      raise 'Tên mẫu không được để trống.' if name.empty?
      raise 'Tên mẫu tối đa 120 ký tự.' if name.length>120
      raise 'Không lưu được tên mẫu.' unless Sketchup.write_default('LOFIHOME_LibraryNames',v31722_name_key(path),name)
      name
    end

    # V182: Profile ngoài do người dùng GÁN trực tiếp bằng cách click đúng Face mặt cắt.
    def self.external_profile_map_file
      File.join(ENV['APPDATA'] || Dir.home, 'LVNTools', 'PhaoChiV599200', 'external_profiles.json')
    end

    def self.external_profile_key(path)
      File.expand_path(path.to_s).tr('\\','/').downcase
    end

    def self.load_external_profile_map
      f = external_profile_map_file
      return {} unless File.file?(f)
      JSON.parse(File.read(f, :encoding => 'UTF-8')) rescue {}
    end

    def self.save_external_profile_for(path, points)
      data = load_external_profile_map
      xs=points.map{|q|q[0].to_f}; ys=points.map{|q|q[1].to_f}
      minx,maxx=xs.minmax; miny,maxy=ys.minmax
      data[external_profile_key(path)] = {
        'path'=>File.expand_path(path), 'name'=>File.basename(path, File.extname(path)),
        'points'=>points, 'width_in'=>(maxx-minx).abs, 'height_in'=>(maxy-miny).abs, 'saved_at'=>Time.now.to_i
      }
      FileUtils.mkdir_p(File.dirname(external_profile_map_file))
      File.open(external_profile_map_file,'wb'){|f| f.write(JSON.pretty_generate(data))}
    end

    def self.saved_external_profile(path)
      load_external_profile_map[external_profile_key(path)]
    end

    # V208: người dùng chỉ cần click vào PHẦN THANH PHÀO.
    # Tool tự đi sâu Group/Component và tìm Face đầu thanh phù hợp nhất.
    class ExternalProfilePickTool
      def initialize(path, instance)
        @path, @instance = path, instance
      end

      def activate
        Sketchup.set_status_text('V214: Xoay model để nhìn đầu thanh, rồi CLICK TRỰC TIẾP ĐÚNG FACE MẶT CẮT. Plugin sẽ lưu chính Face anh click. ESC để hủy.', SB_PROMPT)
      end

      def collect_faces(entities, tr, out)
        entities.each do |e|
          case e
          when Sketchup::Face
            pts = e.outer_loop.vertices.map{|v| v.position.transform(tr)}
            next if pts.length < 3
            n = e.normal.transform(tr)
            n.normalize! rescue next
            out << [e, tr, pts, n]
          when Sketchup::Group
            collect_faces(e.entities, tr * e.transformation, out)
          when Sketchup::ComponentInstance
            collect_faces(Compat.definition(e).entities, tr * e.transformation, out)
          end
        end
      end

      def deepest_container_from_path(path)
        return nil unless path
        path.reverse_each do |e|
          return e if e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)
        end
        nil
      end

      def world_transform_for_path(path, stop_entity)
        tr = Geom::Transformation.new
        path.each do |e|
          if e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)
            tr = tr * e.transformation
            break if e.equal?(stop_entity)
          end
        end
        tr
      end

      def choose_profile_face(faces)
        return nil if faces.empty?
        all = faces.flat_map{|f| f[2]}
        xs=all.map(&:x); ys=all.map(&:y); zs=all.map(&:z)
        spans=[xs.max-xs.min, ys.max-ys.min, zs.max-zs.min]
        axis_i=spans.each_with_index.max[1]
        axis=[Geom::Vector3d.new(1,0,0),Geom::Vector3d.new(0,1,0),Geom::Vector3d.new(0,0,1)][axis_i]
        # End-face: normal gần song song trục dài. Ưu tiên Face có nhiều đỉnh
        # (biên dạng thật thường nhiều chi tiết hơn mặt chữ nhật nền).
        cand=faces.select{|f| f[3].dot(axis).abs > 0.82}
        cand=faces if cand.empty?
        detailed=cand.select{|f| f[2].length > 4}
        cand=detailed unless detailed.empty?
        cand.max_by do |f|
          face, _tr, pts, n=f
          nv=pts.length
          area=(face.area rescue 0.0).to_f
          align=n.dot(axis).abs
          # Ưu tiên topology chi tiết; area chỉ là tie-break nhỏ.
          (nv * 10_000_000.0) + (align * 100_000.0) - area
        end
      end

      def save_face(face_rec)
        face,tr,_pts3,_n = face_rec

        # V209: TUYỆT ĐỐI giữ thứ tự topology của Face.outer_loop.vertices.
        # Không sort X/Y, không sort theo khoảng cách, không dùng danh sách điểm
        # đã gom từ bước dò Face. Nếu đổi thứ tự vertex, engine nối i->i giữa
        # các ring sẽ tạo các tam giác chéo xuyên qua lòng profile.
        loop_vertices = face.outer_loop.vertices
        raise 'Face mặt cắt có dưới 3 đỉnh.' if loop_vertices.length < 3
        pts3 = loop_vertices.map { |vv| vv.position.transform(tr) }

        # Loại duy nhất điểm trùng LIỀN KỀ (nếu có), vẫn bảo toàn chiều vòng kín.
        ordered = []
        pts3.each do |pp|
          ordered << pp if ordered.empty? || ordered[-1].distance(pp) > 1.0e-8
        end
        ordered.pop if ordered.length > 2 && ordered.first.distance(ordered.last) <= 1.0e-8
        raise 'Biên dạng sau khi làm sạch có dưới 3 đỉnh.' if ordered.length < 3

        origin = ordered[0]
        # Trục U lấy đúng cạnh đầu tiên hợp lệ theo thứ tự outer_loop.
        u = nil
        (1...ordered.length).each do |i|
          vv = ordered[i] - origin
          if vv.length > 1.0e-8
            u = vv
            break
          end
        end
        raise 'Không xác định được cạnh chuẩn của Profile.' unless u
        u.normalize!

        n = face.normal.transform(tr)
        n.normalize!
        v = n.cross(u)
        raise 'Không xác định được mặt phẳng Profile.' if v.length < 1.0e-8
        v.normalize!

        pts2 = ordered.map do |pp|
          d = pp - origin
          [d.dot(u), d.dot(v)]
        end

        # Không đóng vòng bằng cách lặp lại điểm đầu; engine tự nối last -> first.
        LVN::PhaoChiV300AssemblyLite.save_external_profile_for(@path, pts2)
      end

      def onLButtonDown(flags,x,y,view)
        ph=view.pick_helper
        ph.do_pick(x,y)
        picked_path=nil
        picked_face=nil
        ph.count.times do |i|
          pth=ph.path_at(i) rescue nil
          next unless pth && pth.include?(@instance)
          fc=pth.reverse.find{|e| e.is_a?(Sketchup::Face)}
          if fc
            picked_path=pth
            picked_face=fc
            break
          end
        end
        unless picked_path && picked_face
          UI.beep
          Sketchup.set_status_text('V214: Chưa bắt được FACE. Hãy click trực tiếp vào MẶT CẮT ở đầu thanh phào; có thể xoay camera để nhìn rõ mặt đầu.', SB_PROMPT)
          return
        end

        # V214 DIRECT FACE: tuyệt đối KHÔNG tự đoán / đổi sang Face khác.
        # Tính world transform đúng theo instance path tới chính Face người dùng click.
        tr=Geom::Transformation.new
        picked_path.each do |e|
          break if e.equal?(picked_face)
          if e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)
            tr = tr * e.transformation
          end
        end
        pts=picked_face.outer_loop.vertices.map{|vv| vv.position.transform(tr)}
        n=picked_face.normal.transform(tr); n.normalize! rescue nil
        face_rec=[picked_face,tr,pts,n]

        # Highlight/selection để người dùng thấy chính Face vừa chọn trước khi lưu.
        begin
          model=Sketchup.active_model
          model.selection.clear
          model.selection.add(picked_face) if picked_face.parent == model.active_entities
          view.invalidate
        rescue
        end

        save_face(face_rec)
        model=Sketchup.active_model
        model.start_operation('LOFIHOME V214 - Xoa mau gan profile', true)
        @instance.erase! if @instance && @instance.valid?
        model.commit_operation
        model.select_tool(nil)
        UI.messagebox("V214 DIRECT FACE\n\nĐÃ LƯU CHÍNH FACE ANH VỪA CLICK CHO MẪU:\n#{File.basename(@path)}\n\nSố đỉnh mặt cắt: #{pts.length}\n\nBây giờ chọn Edge → đúng mẫu → CHẠY THEO EDGE.")
      rescue => e
        UI.messagebox("Lỗi GÁN PROFILE V214 DIRECT FACE:\n#{e.class}: #{e.message}")
      end

      def onCancel(reason,view)
        @instance.erase! if @instance && @instance.valid?
        Sketchup.active_model.select_tool(nil)
      end
    end

    def self.assign_external_profile(path)
      raise 'Không tìm thấy file SKP.' unless path && File.file?(path)
      model=Sketchup.active_model
      model.start_operation('LOFIHOME - Gan Profile mau ngoai', true)
      definition=v311_load_source(path)
      raise 'Không load được file SKP mẫu.' unless definition

      # V207: đưa tâm bounds của definition về gốc model. Nhiều mẫu thư viện
      # được lưu rất xa origin nên add_instance(identity) có tồn tại nhưng không nhìn thấy.
      bb = v31720_source_bounds(definition)
      c = bb.center
      tr = Geom::Transformation.translation(Geom::Vector3d.new(-c.x, -c.y, -c.z))
      inst=model.active_entities.add_instance(definition, tr)
      inst.hidden = false if inst.respond_to?(:hidden=)
      model.commit_operation

      model.selection.clear
      model.selection.add(inst)
      view=model.active_view
      begin
        view.zoom(inst)
        view.refresh
      rescue
        view.zoom_extents rescue nil
      end

      # Kích hoạt tool ngay sau khi model đã hiện; không dùng place_component.
      tool=ExternalProfilePickTool.new(path, inst)
      model.select_tool(tool)
      Sketchup.set_status_text('V214: CLICK TRỰC TIẾP ĐÚNG FACE MẶT CẮT ở đầu thanh. Không click mặt dài. ESC để hủy.', SB_PROMPT)

      # Gọi zoom selection thêm một nhịp sau khi HtmlDialog đã ẩn hoàn toàn.
      UI.start_timer(0.20,false) do
        begin
          if inst && inst.valid?
            model.selection.clear
            model.selection.add(inst)
            Sketchup.send_action('viewZoomToSelection:')
            view.refresh
          end
        rescue
        end
      end
    rescue => e
      model.abort_operation rescue nil
      UI.messagebox("Không mở được mẫu để GÁN PROFILE:\n#{e.class}: #{e.message}")
    end


    # V204 - CAT NGANG TOAN BO SKP: doc de quy Group/Component, ghep section thanh loop kin.
    # Khong chon 1 Face dau thanh nua vi model phao co the gom nhieu Face nho / group long nhau.
    def self.exact_profile_from_skp_file(path)
      model = Sketchup.active_model
      definition = v311_load_source(path)
      raise 'Không load được file SKP mẫu.' unless definition
      faces=[]
      collect_faces(definition.entities, Geom::Transformation.new, faces)
      raise 'File SKP không có Face.' if faces.empty?

      all_pts=[]
      faces.each{|face,tr| face.vertices.each{|v| all_pts << v.position.transform(tr)}}
      raise 'File SKP không đủ hình học.' if all_pts.length < 3
      mins=[all_pts.map(&:x).min,all_pts.map(&:y).min,all_pts.map(&:z).min]
      maxs=[all_pts.map(&:x).max,all_pts.map(&:y).max,all_pts.map(&:z).max]
      spans=3.times.map{|i| maxs[i]-mins[i]}
      long_i=spans.each_with_index.max[1]
      eps=[spans[long_i]*1.0e-7,0.001.mm].max

      # Cat o nhieu vi tri de tranh dung ngay mat noi/noi bo cua component.
      candidates=[]
      [0.37,0.50,0.63].each do |ratio|
        cut=mins[long_i]+spans[long_i]*ratio
        segs=[]
        faces.each do |face,tr|
          begin
            segs.concat(section_segments_for_face(face,tr,long_i,cut,eps))
          rescue
          end
        end
        uniq={}
        segs.each do |aa,bb|
          ka=point_key(aa,0.01.mm); kb=point_key(bb,0.01.mm)
          next if ka==kb
          uniq[[ka,kb].sort]=[aa,bb]
        end
        stitch_all_boundary_loops(uniq.values).each do |loop3|
          next if loop3.length < 3
          pts2=project_axis_points(loop3,long_i)
          xs=pts2.map{|q|q[0].to_f}; ys=pts2.map{|q|q[1].to_f}
          minx,maxx=xs.minmax; miny,maxy=ys.minmax
          dx=maxx-minx; dy=maxy-miny
          next if dx.abs < 0.01.mm || dy.abs < 0.01.mm
          # Uu tien loop co nhieu dinh/chi tiet; phat manh hinh chu nhat 4 dinh.
          score=pts2.length*1_000_000.0 + (dx*dy).abs.to_f - (pts2.length<=4 ? 100_000_000.0 : 0.0)
          norm=pts2.map{|q|[(q[0].to_f-minx)/dx,(q[1].to_f-miny)/dy]}
          candidates << [score,norm,dx.to_mm.to_f,dy.to_mm.to_f,pts2.length,ratio]
        end
      end

      # Neu section khong ghep duoc loop kin, fallback ve bo nhan dang SKP cu.
      if candidates.empty?
        p = import_skp_profile(path)
        raise 'Không nhận được vòng tiết diện kín từ mẫu SKP.' unless p
        pts=p['points'] || []
        xs=pts.map{|q|q[0].to_f}; ys=pts.map{|q|q[1].to_f}
        minx,maxx=xs.minmax; miny,maxy=ys.minmax
        dx=maxx-minx; dy=maxy-miny
        raise 'Biên dạng fallback không hợp lệ.' if dx.abs<1e-9 || dy.abs<1e-9
        norm=pts.map{|q|[(q[0].to_f-minx)/dx,(q[1].to_f-miny)/dy]}
        return {'id'=>"SKP_SECTION_#{Time.now.to_i}",'name'=>File.basename(path,File.extname(path)),
          'category'=>'Mẫu ngoài','points'=>norm,'user_added'=>true,'preserve_aspect'=>true,
          'actual_width'=>dx.to_mm.to_f,'actual_height'=>dy.to_mm.to_f,
          'source_type'=>'SKP_SECTION_FALLBACK_V204','detected_vertices'=>pts.length}
      end

      best=candidates.max_by{|x|x[0]}
      {'id'=>"SKP_SECTION_#{Time.now.to_i}",'name'=>File.basename(path,File.extname(path)),
       'category'=>'Mẫu ngoài','points'=>best[1],'user_added'=>true,'preserve_aspect'=>true,
       'actual_width'=>best[2],'actual_height'=>best[3],
       'source_type'=>'SKP_RECURSIVE_SECTION_LOOP_V204','detected_vertices'=>best[4],
       'section_ratio'=>best[5]}
    end

    # V177: chọn mẫu SKP trong Gallery và chạy trực tiếp theo Edge đã chọn.
    # V205: CHẠY EDGE ưu tiên tuyệt đối PROFILE mà người dùng đã GÁN bằng nút GÁN PROFILE.
    # Đây là contour 2D của chính Face người dùng click, tránh tự dò nhầm mặt bao chữ nhật trong SKP.
    def self.run_external_skp_on_selected_edges(path)
      model = Sketchup.active_model
      edges = model.selection.grep(Sketchup::Edge)
      if edges.empty?
        UI.messagebox('Hãy chọn Edge cần chạy trước, sau đó bấm mẫu phào.')
        return
      end
      raise 'Không tìm thấy file SKP.' unless path && File.file?(path)

      # V222: BỎ HOÀN TOÀN BƯỚC GÁN PROFILE.
      # Mỗi lần chọn mẫu, plugin tự trích mặt cắt từ chính SKP rồi chạy Native Follow Me.
      # Không đọc profile đã gán/cached từ các bản cũ để tránh yêu cầu người dùng xác nhận thủ công.
      profile = exact_profile_from_skp_file(path)
      pts = profile['points'] || []
      raise 'Không tự đọc được biên dạng kín từ mẫu SKP.' if pts.length < 3
      w = profile['actual_width'].to_f; h = profile['actual_height'].to_f
      w = 80.0 if w <= 0.01; h = 10.0 if h <= 0.01
      opts = {
        'id' => profile['id'], 'width' => w, 'height' => h,
        'orientation' => 'right_up', 'reverse_path' => false,
        'offset_side' => 0, 'offset_vertical' => 0,
        '_profile_override' => profile
      }
      run_profile(opts)
      @external_gallery.close rescue nil
    rescue => e
      UI.messagebox("Lỗi TỰ LẤY MẪU & CHẠY EDGE V222:\n#{e.class}: #{e.message}")
    end

    # V220: Giữ nguyên toàn bộ hình học/hoa văn 3D của file SKP ngoài.
    # Mỗi Edge nhận một instance của model gốc, chỉ scale theo trục dài của mẫu để khớp chiều dài Edge.
    # Không thay đổi 2 trục tiết diện, vì vậy hoa văn nổi/chi tiết 3D được giữ nguyên.
    # Đây là chế độ bổ sung; engine Native Follow Me V220 vẫn giữ nguyên cho thân phào/miter chuẩn.
    # V221: giữ nguyên model 3D gốc nhưng kéo dư hai đầu mỗi cạnh tới vùng miter.
    # Mục tiêu: loại khe chữ V ở góc của V220 mà không thay engine Native Follow Me V219.
    # Các đoạn 3D vẫn là instance model gốc; chỉ scale theo trục dài. Ở vertex, chiều dài
    # được cộng allowance theo góc để hai đoạn phủ kín vùng phân giác. Không scale tiết diện.
    # V277 TWO-LAYER ENGINE - DECO CONTINUOUS TO CORNER:
    # 1) Thân phào + miter góc do Native Follow Me xử lý.
    # 2) Model 3D nguồn chỉ được đặt như lớp deco trên phần thẳng của từng Edge.
    #    Không có module 3D nào đi vào vùng góc, không trim/cắt hoa văn ở vertex.
    # 3) Deco giữ tỉ lệ 1:1 theo trục dài; các module nối sát nhau và cả dải được căn giữa.
    # V277: Sao chép hình học thật của một instance sang group mới và clip theo nửa không gian.
    # Dùng tam giác của Face nên làm việc được cả với model không phải Solid và Group/Component lồng nhau.
    def self.v277_clip_instance_to_plane(inst, plane_point, plane_normal, keep_point, target_entities, name='MITER_CLIPPED', mesh_cache = {})
      return nil unless inst && inst.valid?
      n = plane_normal.clone
      return nil if n.length <= 1.0e-9
      n.normalize!
      keep_sign = ((keep_point - plane_point).dot(n) >= 0.0) ? 1.0 : -1.0
      out = target_entities.add_group
      out.name = name
      # Work near the joint origin at enlarged scale to preserve small relief faces.
      build_scale = 100.0
      out.transformation = Geom::Transformation.translation(plane_point.to_a) * Geom::Transformation.scaling(1.0/build_scale)

      # Same half-space clipping as the SKP repair confirmed by the user.
      # Carry each incoming edge's soft flag through an intersection.
      clip_poly = lambda do |pts,soft|
        result=[]
        previous=pts[-1]
        dp=(previous-plane_point).dot(n)*keep_sign
        pts.each_with_index do |current,i|
          dc=(current-plane_point).dot(n)*keep_sign
          incoming=soft[(i-1)%pts.length]
          if dc >= -1.0e-9
            if dp < -1.0e-9
              t=dp/(dp-dc)
              point=Geom::Point3d.new(previous.x+(current.x-previous.x)*t,
                                     previous.y+(current.y-previous.y)*t,
                                     previous.z+(current.z-previous.z)*t)
              result << [point,false]
            end
            result << [current,incoming]
          elsif dp >= -1.0e-9
            t=dp/(dp-dc)
            point=Geom::Point3d.new(previous.x+(current.x-previous.x)*t,
                                   previous.y+(current.y-previous.y)*t,
                                   previous.z+(current.z-previous.z)*t)
            result << [point,incoming]
          end
          previous=current;dp=dc
        end
        result
      end

      # Build polygon meshes in memory, then create SketchUp geometry in batches.
      # add_face for each triangle triggers expensive topology updates repeatedly.
      buckets = {}
      polygon_count = 0
      walk = nil
      walk = lambda do |entities, tr, inherited_material|
        entities.each do |e|
          # Preserve source visibility: do not turn hidden reference geometry into faces.
          next if e.respond_to?(:hidden?) && e.hidden? && !(@v31714_render_mask && e.is_a?(Sketchup::Face) && e.get_attribute('LOFIHOME','uncut_ornament'))
          next if e.respond_to?(:layer) && e.layer && !e.layer.visible?
          if e.is_a?(Sketchup::Face)
            begin
              cached = mesh_cache[e] ||= begin
                source_mesh = e.mesh(0)
                edge_flags = {}
                source_mesh.polygons.each do |polygon|
                  polygon.each_with_index do |id,i|
                    key = [id.abs,polygon[(i+1)%polygon.length].abs].sort
                    edge_flags[key] = id < 0
                  end
                end
                e.edges.each do |edge|
                  u = source_mesh.point_index(edge.start.position)
                  v = source_mesh.point_index(edge.end.position)
                  next if u == 0 || v == 0
                  edge_flags[[u,v].sort] = edge.hidden? || edge.soft?
                end
                [source_mesh,edge_flags]
              end
              mesh,source_edges = cached
              front = e.material || inherited_material
              back = e.back_material || inherited_material
              role=e.get_attribute('LOFIHOME','geometry_role')
              masked=@v31714_render_mask && role=='ornament'
              key = [front,back,role,masked && e.hidden?]
              bucket = buckets[key] ||= Geom::PolygonMesh.new
              mesh.polygons.each do |poly|
                ids=poly.map{|i| i.abs}
                next if ids.length < 3
                pts=ids.map{|i| mesh.point_at(i).transform(tr)}
                # fan triangulate polygon from mesh, then clip each triangle
                (1...(pts.length-1)).each do |k|
                  source_tri = [pts[0],pts[k],pts[k+1]]
                  source_ids = [ids[0],ids[k],ids[k+1]]
                  source_hidden = 3.times.map { |i| source_edges.fetch([source_ids[i],source_ids[(i+1)%3]].sort,true) }
                  # Keep every original relief triangle; only its visibility changes.
                  clipped=masked ? source_tri.each_with_index.map { |point,i| [point,source_hidden[(i-1)%3]] } : clip_poly.call(source_tri,source_hidden)
                  next if clipped.length < 3
                  clean=[];incoming=[]
                  clipped.each do |point,flag|
                    next if !clean.empty? && clean[-1].distance(point).to_f <= 1.0e-7
                    clean << point;incoming << flag
                  end
                  if clean.length>2 && clean[0].distance(clean[-1]).to_f <= 1.0e-7
                    incoming[0]=incoming[-1];clean.pop;incoming.pop
                  end
                  next if clean.length < 3
                  boundary_hidden = clean.each_index.map { |i| incoming[(i+1)%clean.length] }
                  # A clipped triangle can become a quad. SketchUp may merge its
                  # near-coincident vertices and reject that quad as non-planar.
                  # Emit only non-degenerate triangles in local, enlarged coordinates.
                  local = clean.map do |p|
                    Geom::Point3d.new((p.x-plane_point.x)*build_scale,
                                      (p.y-plane_point.y)*build_scale,
                                      (p.z-plane_point.z)*build_scale)
                  end
                  (1...(local.length-1)).each do |j|
                    tri = [local[0],local[j],local[j+1]]
                    normal = (tri[1]-tri[0]).cross(tri[2]-tri[0])
                    next if normal.length <= 1.0e-10
                    hidden = [j == 1 ? boundary_hidden[0] : true,
                              boundary_hidden[j],
                              j+1 == local.length-1 ? boundary_hidden[j+1] : true]
                    mesh_ids = tri.map { |point| bucket.add_point(point) }
                    signed_ids = mesh_ids.each_with_index.map { |id,i| hidden[i] ? -id : id }
                    bucket.add_polygon(signed_ids)
                    polygon_count += 1
                  end
                end
              end
            end
          elsif e.is_a?(Sketchup::Group)
            walk.call(e.entities, tr * e.transformation, e.material || inherited_material)
          elsif e.is_a?(Sketchup::ComponentInstance)
            walk.call(Compat.definition(e).entities, tr * e.transformation, e.material || inherited_material)
          end
        end
      end
      if inst.is_a?(Sketchup::Group)
        walk.call(inst.entities, inst.transformation, inst.material)
      else
        walk.call(Compat.definition(inst).entities, inst.transformation, inst.material)
      end
      raise 'Cắt góc không tạo được mặt hoa văn.' if polygon_count == 0
      buckets.each do |materials, mesh|
        # A material bucket is created before clipping. Its whole surface may
        # lie outside this corner, while another (masked relief) bucket survives.
        # Do not try to fill an empty mesh or treat it as a failed face build.
        next if mesh.count_polygons==0
        target = buckets.length == 1 ? out.entities : out.entities.add_group.entities
        target.fill_from_mesh(mesh, true, 11, materials[0], materials[1])
        target.grep(Sketchup::Edge).each { |edge| edge.soft=true if edge.smooth? && edge.faces.length==2 }
        target.parent.set_attribute('LOFIHOME','geometry_role',materials[2]) if materials[2]
        target.grep(Sketchup::Face).each do |face|
          face.set_attribute('LOFIHOME','geometry_role',materials[2]) if materials[2]
          next unless @v31714_render_mask && materials[2]=='ornament'
          face.set_attribute('LOFIHOME','uncut_ornament',true)
          face.hidden=!!materials[3] || face.vertices.any? { |v| ((v.position.transform(out.transformation)-plane_point).dot(n)*keep_sign).to_f < -1.0e-7 }
        end
        if @v31714_render_mask && materials[2]=='ornament'
          target.grep(Sketchup::Edge).each { |edge| edge.hidden=true if !edge.faces.empty? && edge.faces.all?(&:hidden?) }
        end
        raise 'Không dựng được mặt cắt hoa văn.' if target.grep(Sketchup::Face).empty?
      end
      out.material = inst.material if inst.respond_to?(:material)
      out.layer = inst.layer if inst.respond_to?(:layer)
      inst.erase! if inst.valid?
      out
    rescue
      out.erase! if out && out.valid?
      raise
    end

    # Mặt phẳng miter đứng tại vertex: đường nằm theo phân giác 2 cạnh trong mặt phẳng XY.
    def self.v277_miter_plane(vertex, dir_in, dir_out)
      a=dir_in.clone; b=dir_out.clone
      return nil if a.length<=1.0e-9 || b.length<=1.0e-9
      a.normalize!; b.normalize!
      # Equal signed distance along the two rays; valid in any path plane.
      normal = a - b
      return nil if normal.length <= 1.0e-9 || a.cross(b).length <= 1.0e-9
      normal.normalize!
      [vertex,normal]
    end

    # Hide only square end-cap geometry in a private source variant.
    # The original definition and ornamental/profile edges stay untouched.
    def self.v314_seamless_source(source, axis_i)
      @v314_seamless ||= {}
      key = [source,axis_i]
      cached = @v314_seamless[key]
      return cached if cached && cached.valid?
      bounds = v31720_source_bounds(source)
      ends = [bounds.min.to_a[axis_i].to_f,bounds.max.to_a[axis_i].to_f]
      variant = Sketchup.active_model.definitions.add(source.name + ' - LOFI Seamless')
      variant.entities.add_instance(source,Geom::Transformation.new).explode
      visit = nil
      visit = lambda do |entities,tr|
        entities.to_a.each do |entity|
          next if entity.respond_to?(:hidden?) && entity.hidden?
          if entity.is_a?(Sketchup::Face)
            coords = entity.vertices.map { |v| v.position.transform(tr).to_a[axis_i].to_f }
            entity.hidden = true if ends.any? { |cut| coords.all? { |x| (x-cut).abs < (0.01 / 25.4) } }
          elsif entity.is_a?(Sketchup::Edge)
            coords = [entity.start.position,entity.end.position].map { |p| p.transform(tr).to_a[axis_i].to_f }
            if ends.any? { |cut| coords.all? { |x| (x-cut).abs < (0.01 / 25.4) } }
              entity.hidden = true
              entity.soft = true
              entity.smooth = true
            end
          elsif entity.is_a?(Sketchup::Group)
            entity.make_unique
            visit.call(entity.entities,tr * entity.transformation)
          elsif entity.is_a?(Sketchup::ComponentInstance)
            entity.make_unique
            visit.call(Compat.definition(entity).entities,tr * entity.transformation)
          end
        end
      end
      visit.call(variant.entities,Geom::Transformation.new)
      @v314_seamless[key] = variant
      variant
    end

    # A swept body has faces spanning the full source length. Relief meshes do not.
    def self.v31713_sync_smooth_edges(entities,seen={})
      changed=0
      entities.grep(Sketchup::Edge).each do |edge|
        next unless edge.valid? && edge.smooth? && !edge.soft? && edge.faces.length==2
        edge.soft=true
        changed+=1
      end
      entities.each do |item|
        next unless item.is_a?(Sketchup::Group) || item.is_a?(Sketchup::ComponentInstance)
        definition=Compat.definition(item)
        next if seen[definition]
        seen[definition]=true
        child=item.is_a?(Sketchup::Group) ? item.entities : definition.entities
        changed+=v31713_sync_smooth_edges(child,seen)
      end
      changed
    end

    def self.v31713_fix_frame_smooth
      model=Sketchup.active_model
      item=model.selection.to_a.find { |e| e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance) }
      unless item
        UI.messagebox('Chọn khung phào rồi bấm LÀM MƯỢT ĐỒNG ĐỀU.')
        return
      end
      return LibraryMouldingSeams.repair_selected if LibraryMouldingSeams.supported?(item)
      model.start_operation('Làm mượt cạnh phào đồng đều',true)
      entities=item.is_a?(Sketchup::Group) ? item.entities : Compat.definition(item).entities
      count=v31713_sync_smooth_edges(entities)
      model.commit_operation
      Sketchup.set_status_text("LOFIHOME: Đã đồng bộ Soft/Smooth #{count} cạnh; giữ nguyên biên dạng và góc 45°.")
    rescue => e
      model.abort_operation rescue nil
      UI.messagebox("Lỗi làm mượt phào: #{e.message}")
    end

    # Mark private source copies, never the original library definition.
    def self.v3179_mark_roles(source, axis, length)
      v31770_mark_source_roles(source, axis, length)
    end

    # Only the low-detail swept body is merged. Ornament definitions stay shared.
    # Rebuild continuous planar strips rather than retaining every module seam.
    # A convex patch is accepted only when its area equals the input surface area.
    # Disjoint/recessed/concave regions retain their original triangles.
    def self.v31711_body_patches(triangles)
      bins=[]
      ordered=triangles.sort_by { |tri,f,b| -(tri[1]-tri[0]).cross(tri[2]-tri[0]).length.to_f }
      ordered.each do |tri,front,back|
        n=(tri[1]-tri[0]).cross(tri[2]-tri[0])
        next if n.length.to_f<=1.0e-10
        area=n.length.to_f*0.5
        n.normalize!
        pivot=(0..2).max_by { |i| n.to_a[i].abs }
        n.reverse! if n.to_a[pivot]<0
        group=bins.find do |items|
          sample=items[0]
          sample[1]==front && sample[2]==back && sample[3].dot(n).abs>1.0-1.0e-8 && tri.all? { |p| (p-sample[0][0]).dot(sample[3]).to_f.abs<1.0e-4 }
        end
        unless group
          group=[];bins << group
        end
        group << [tri,front,back,n,area]
      end
      regions=[]
      bins.each do |items|
        roots=(0...items.length).to_a
        find=lambda do |id|
          id=roots[id] while roots[id]!=id
          id
        end
        vertices={}
        items.each_with_index do |item,index|
          item[0].each do |p|
            key=p.to_a.map { |value| value.to_f.round(3) }
            if vertices.key?(key)
              roots[find.call(index)]=find.call(vertices[key])
            else
              vertices[key]=index
            end
          end
        end
        connected={}
        items.each_with_index { |item,index| (connected[find.call(index)]||=[]) << item }
        regions.concat(connected.values)
      end
      result=[]
      regions.each do |items|
        items.sort_by! { |item| -item[4] }
        if items.length==1
          result << items[0][0,3]
          next
        end
        n=items[0][3];origin=items[0][0][0]
        u=items[0][0][1]-origin;u.normalize!
        v=n.cross(u);v.normalize!
        projected={}
        items.each do |item|
          item[0].each do |p|
            delta=p-origin
            xy=[delta.dot(u).to_f.round(7),delta.dot(v).to_f.round(7)]
            projected[xy]=p
          end
        end
        pts=projected.keys.sort
        cross=lambda { |a,b,c| (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]) }
        halves=[pts,pts.reverse].map do |sequence|
          hull=[]
          sequence.each do |p|
            hull.pop while hull.length>=2 && cross.call(hull[-2],hull[-1],p)<=1.0e-9
            hull << p
          end
          hull[0...-1]
        end
        hull=halves.flatten(1)
        # Remove redundant module-end vertices on otherwise straight boundaries.
        # This prevents endpoint ticks and segmented longitudinal profile edges.
        changed=true
        while changed && hull.length>3
          changed=false
          hull.length.times do |i|
            a=hull[(i-1)%hull.length];b=hull[(i+1)%hull.length];p=hull[i]
            length=Math.sqrt((b[0]-a[0])**2+(b[1]-a[1])**2)
            next if length<=1.0e-10
            if cross.call(a,b,p).abs/length<1.0e-4
              hull.delete_at(i);changed=true;break
            end
          end
        end
        area=hull.each_with_index.sum { |p,i| q=hull[(i+1)%hull.length];p[0]*q[1]-p[1]*q[0] }.abs*0.5
        original_area=items.sum { |item| item[4] }
        on_plane=items.all? { |item| item[0].all? { |p| ((p-origin).dot(n)).to_f.abs<1.0e-4 } }
        if hull.length>=3 && on_plane && (area-original_area).abs <= [1.0e-5,original_area*1.0e-6].max
          points=hull.map { |xy| origin.offset(u,xy[0]).offset(v,xy[1]) }
          # Keep the original face winding.
          ref=(items[0][0][1]-items[0][0][0]).cross(items[0][0][2]-items[0][0][0])
          points.reverse! if (points[1]-points[0]).cross(points[2]-points[0]).dot(ref)<0
          result << [points,items[0][1],items[0][2]]
        else
          items.each { |item| result << item[0,3] }
        end
      end
      result
    end

    # Remove shared coplanar body edges, including cut-piece / full-piece seams.
    # Relief is never passed to this method; miter boundaries have one face.
    def self.v31710_join_body_surfaces(entities)
      entities.grep(Sketchup::Edge).each do |edge|
        next unless edge.valid?
        faces=edge.faces
        next unless faces.length==2
        a,b=faces
        next unless a.material==b.material && a.back_material==b.back_material
        next unless a.normal.dot(b.normal).abs > 1.0-1.0e-8
        next unless b.vertices.all? { |v| v.position.distance_to_plane(a.plane).to_f.abs < 1.0e-5 }
        edge.erase!
      end
    end

    def self.v3179_split_frame(parent, body_only=false)
      model=Sketchup.active_model
      rows=JSON.parse(parent.get_attribute('LOFIHOME','path_data'))
      originals=parent.entities.to_a.select { |e| e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance) }
      body_rows=Array.new(rows.length) { [] }
      ornaments=[]
      collect=nil
      collect=lambda do |entities,tr,index,inherited,role|
        entities.each do |e|
          next if e.respond_to?(:hidden?) && e.hidden?
          next if e.respond_to?(:layer) && e.layer && !e.layer.visible?
          if e.is_a?(Sketchup::Face)
            kind=e.get_attribute('LOFIHOME','geometry_role',role)
            raise 'Mặt chưa được phân loại thân phào / hoa văn.' unless kind=='body'
            body_rows[index] << [e,tr,inherited]
          elsif e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)
            definition=Compat.definition(e)
            kind=e.get_attribute('LOFIHOME','geometry_role',definition.get_attribute('LOFIHOME','geometry_role',role))
            world=tr*e.transformation
            material=e.material || inherited
            if kind=='ornament'
              ornaments << [definition,world,material,e.layer,index,e]
            else
              child=e.is_a?(Sketchup::Group) ? e.entities : definition.entities
              collect.call(child,world,index,material,kind)
            end
          end
        end
      end
      originals.each do |part|
        index=part.get_attribute('LOFIHOME','edge_index')
        raise 'Thiếu thông tin cạnh phào.' unless index && body_rows[index]
        definition=Compat.definition(part)
        kind=part.get_attribute('LOFIHOME','geometry_role',definition.get_attribute('LOFIHOME','geometry_role'))
        if kind=='ornament'
          ornaments << [definition,part.transformation,part.material,part.layer,index,part]
        else
          child=part.is_a?(Sketchup::Group) ? part.entities : definition.entities
          collect.call(child,part.transformation,index,part.material,kind)
        end
      end
      raise 'Không có hoa văn riêng để gom.' if ornaments.empty? && !body_only
      components=[]
      rows.each_with_index do |row,index|
        raise "Không có thân phào cạnh #{index+1}." if body_rows[index].empty?
        Sketchup.set_status_text("LOFIHOME: Đang nối thân phào #{index+1}/#{rows.length}…")
        origin=Geom::Point3d.new(row[0])
        definition=model.definitions.add("LOFIHOME - Than phao #{index+1}")
        target=definition.entities
        local=Geom::Transformation.scaling(100.0)*Geom::Transformation.translation(Geom::Vector3d.new(origin.to_a).reverse)
        flags={}
        source_flags={}
        point_key=lambda { |p| p.to_a.map { |v| v.to_f.round(7) } }
        edge_key=lambda { |a,b| [point_key.call(a),point_key.call(b)].sort }
        triangles=[]
          body_rows[index].each do |face,tr,inherited|
            transform=local*tr
            mesh=face.mesh(0)
            mesh.polygons.each do |poly|
              points=poly.map { |id| mesh.point_at(id.abs).transform(transform) }
              (1...(points.length-1)).each do |i|
                tri=[points[0],points[i],points[i+1]]
                next if (tri[1]-tri[0]).cross(tri[2]-tri[0]).length.to_f<=1.0e-10
                triangles << [tri,face.material || inherited,face.back_material || inherited]
                3.times { |j| flags[edge_key.call(tri[j],tri[(j+1)%3])] ||= [true,true,false] }
              end
            end
            face.edges.each do |edge|
              key=edge_key.call(edge.start.position.transform(transform),edge.end.position.transform(transform))
              state=[edge.soft?,edge.smooth?,edge.hidden?]
              old=source_flags[key]
              flags[key]=old ? 3.times.map { |i| old[i] && state[i] } : state
              source_flags[key]=flags[key]
            end
          end
        patches=v31711_body_patches(triangles)
        # Restore profile edge styling when several short source edges become one.
        style_segments=source_flags.map do |pair,state|
          [Geom::Point3d.new(pair[0]),Geom::Point3d.new(pair[1]),state]
        end
        patches.each do |tri,front,back|
          tri.length.times do |j|
            a=tri[j];b=tri[(j+1)%tri.length];direction=b-a
            length2=direction.dot(direction).to_f
            next if length2<=1.0e-12
            matches=[]
            style_segments.each do |p,q,state|
              next unless (p-a).cross(direction).length.to_f/Math.sqrt(length2)<1.0e-4 && (q-a).cross(direction).length.to_f/Math.sqrt(length2)<1.0e-4
              t0=(p-a).dot(direction).to_f/length2;t1=(q-a).dot(direction).to_f/length2
              next if [t0,t1].max<-1.0e-7 || [t0,t1].min>1.0+1.0e-7
              matches << state
            end
            flags[edge_key.call(a,b)]=3.times.map { |k| matches.all? { |state| state[k] } } unless matches.empty?
          end
        end
        v31770_add_body_patches(target,patches)
        patches.each do |tri,front,back|
          tri.length.times { |j| flags[edge_key.call(tri[j],tri[(j+1)%tri.length])] ||= [true,true,false] }
        end
        target.grep(Sketchup::Edge).each do |edge|
          state=flags[edge_key.call(edge.start.position,edge.end.position)]
          next unless state
          edge.soft=state[0];edge.smooth=state[1];edge.hidden=state[2]
        end
        target.grep(Sketchup::Edge).each { |edge| edge.soft=true if edge.smooth? && edge.faces.length==2 }
        v31710_join_body_surfaces(target)
        world=Geom::Transformation.translation(origin.to_a)*Geom::Transformation.scaling(0.01)
        component=parent.entities.add_instance(definition,world)
        component.name="THAN PHAO #{index+1}"
        component.set_attribute('LOFIHOME','edge_index',index)
        component.set_attribute('LOFIHOME','geometry_role','body')
        components << component
      end
      unless body_only
      ornament_def=model.definitions.add('LOFIHOME - Hoa van rieng')
      converted={}
      ornaments.each do |definition,tr,material,layer,index,source_item|
        if source_item.is_a?(Sketchup::Group)
          saved=converted[definition]
          unless saved
            # Convert a temporary copy only; no explode or relief welding.
            temporary=source_item.copy
            temporary.make_unique
            temporary=temporary.to_component
            adjustment=source_item.transformation.inverse*temporary.transformation
            saved=[Compat.definition(temporary),adjustment]
            converted[definition]=saved
            temporary.erase!
          end
          definition=saved[0]
          tr=tr*saved[1]
        end
        copy=ornament_def.entities.add_instance(definition,tr)
        copy.material=material
        copy.layer=layer
        copy.set_attribute('LOFIHOME','edge_index',index)
      end
      ornament=parent.entities.add_instance(ornament_def,Geom::Transformation.new)
      ornament.name='HOA VAN RIENG - GIU NGUYEN CHI TIET'
      ornament.set_attribute('LOFIHOME','geometry_role','ornament')
      components << ornament
      end
      raise 'Sai số Component thân phào / hoa văn.' unless components.length==rows.length+(body_only ? 0 : 1)
      parent.entities.erase_entities(originals)
      parent.set_attribute('LOFIHOME','assembly','V317_9_BODY_RAILS_AND_ORNAMENT')
      parent.set_attribute('LOFIHOME','body_components',rows.length)
      parent.set_attribute('LOFIHOME','ornament_components',body_only ? 0 : 1)
      components
    end

    # Use prepared copies only while the original library file is unchanged.
    # Source paths stay original so calibration, rebuilding and thumbnails agree.
    def self.v31720_light_source(path)
      base=File.join(ENV['USERPROFILE'] || Dir.home,'Documents','ChatGPT','New project','THU_VIEN_MAU_NHE')
      manifest=File.join(base,'manifest.json')
      return path unless File.file?(manifest) && File.file?(path)
      stamp=[File.size(manifest),File.mtime(manifest).to_f]
      if !@v31720_manifest || @v31720_manifest[0]!=stamp
        @v31720_manifest=[stamp,JSON.parse(File.read(manifest,:encoding=>'UTF-8'))]
      end
      key=File.expand_path(path).tr('\\','/').downcase
      entry=@v31720_manifest[1][key]
      return path unless entry && !entry['kept_original'] && entry['source_bytes']==File.size(path) && entry['source_mtime']==File.mtime(path).to_i
      candidate=File.expand_path(entry['file'],base)
      return path unless File.dirname(candidate)==File.expand_path(base) && File.file?(candidate) && File.size(candidate)==entry['bytes']
      candidate
    rescue
      path
    end

    def self.v31720_source_bounds(definition)
      points=definition.get_attribute('LOFIHOME','library_original_bounds')
      return definition.bounds unless points.is_a?(Array) && points.length==2
      box=Geom::BoundingBox.new
      points.each { |p| box.add(Geom::Point3d.new(p)) }
      box
    end

    def self.v311_load_source(path, clean=true)
      @v311_sources ||= {}
      actual_path = v31720_light_source(path)
      stamp = [actual_path, File.size(actual_path), File.mtime(actual_path).to_f]
      cached = @v311_sources[path]
      if cached && cached[0] == Sketchup.active_model && cached[1] == stamp && cached[2].valid?
        if clean && !cached[3]
          clean_ornament_edges(cached[2].entities)
          cached[3]=true
        end
        return cached[2]
      end
      definition = Compat.load_definition(Sketchup.active_model.definitions,Compat.model_file(actual_path))
      clean_ornament_edges(definition.entities) if clean
      if actual_path!=path
        entry=@v31720_manifest[1][File.expand_path(path).tr('\\','/').downcase]
        definition.set_attribute('LOFIHOME','library_original_bounds',entry['bounds']) if entry && entry['bounds']
      end
      @v311_sources[path] = [Sketchup.active_model, stamp, definition, clean]
      definition
    end

    # V308: Repeat the complete selected source model, including ornament.
    # Extend both ends through each joint; clip crossing modules automatically.
    # Interior modules keep shared definitions to reduce model size.
    def self.run_external_full3d_on_selected_edges(path, options = {}, path_rows = nil, replace_group = nil)
      body_only=options['build_stage']=='body'
      operation_started=false
      @v31714_render_mask=!!options['render_mask']
      model = Sketchup.active_model
      @external_gallery.close rescue nil
      Sketchup.set_status_text(body_only ? 'LOFIHOME: Đang dựng thân phào…' : 'LOFIHOME: Đang xếp mẫu hoa văn theo Edge…')
      if path_rows
        chain = path_rows.map { |a,b| [nil,a,b] }
      else
        selected = model.selection.grep(Sketchup::Edge).select { |e| e.valid? && e.length > 1.0e-6 }
        if selected.empty?
          UI.messagebox('Hãy chọn Edge cần chạy trước.')
          return
        end
        chain = ordered_edge_chain(selected)
      end
      raise 'Không tìm thấy file SKP mẫu.' unless path && File.file?(path)
      raise 'Không tạo được chuỗi Edge liên tục.' if chain.empty?
      source_name = File.basename(path,File.extname(path))
      calibrated_104 = !!(source_name =~ /\ASU84[\s_-]*\(?\s*104\s*\)?\z/i)
      roll = v317146_library_roll(options,calibrated_104)
      anchor = LibraryFrameSettings.anchor(options)
      LibraryFrameSettings.flips(options)
      path_plan = LibraryEdgePath.plan(chain)
      chain = path_plan[:chain]

      # V308: Use the complete selected SKP, including its original body and relief.
      # A separate section extrusion can conceal ornament and duplicate the body.
      unless options['_surface_batch'] || options['_external_operation']
        model.start_operation(body_only ? 'LOFIHOME - Chạy thân phào' : 'LOFIHOME - Chạy phào và hoa văn', true)
        operation_started=true
      end
      definition = v311_load_source(path,!body_only)
      raise 'Không tải được model SKP mẫu.' unless definition
      anchor_source = definition
      bb = v31720_source_bounds(definition)
      dims = [bb.width.to_f, bb.height.to_f, bb.depth.to_f]
      axis_name = options.fetch('source_axis','auto').to_s.downcase
      axis_i = {'x'=>0,'y'=>1,'z'=>2}[axis_name] || dims.each_with_index.max[1]
      # SU84-(104): +90 turns the relief underneath; +270 exposes the relief.
      axis_i = 0 if calibrated_104 && axis_name == 'auto'
      src_len = dims[axis_i]
      src_len = dims[axis_i]
      raise 'Model mẫu không có chiều dài hợp lệ.' if src_len <= 1.0e-6

      parent = model.active_entities.add_group
      parent.name = (body_only ? 'THAN PHAO - ' : 'HOA VAN 3D AUTO MITER - ') + v31722_sample_name(path)
      ents = parent.entities
      # Shared seam-free copy: preserve original geometry and ornament scale.
      definition = v31786_body_source(definition,axis_i,src_len) if body_only
      definition = v314_seamless_source(definition,axis_i)
      split_body_and_ornament = body_only || v3179_mark_roles(definition,axis_i,src_len)

      # Hệ trục nguồn chỉ tính MỘT LẦN.
      case axis_i
      when 0
        local_x = Geom::Vector3d.new(1,0,0); local_y = Geom::Vector3d.new(0,1,0); local_z = Geom::Vector3d.new(0,0,1)
        min_long, min_y, min_z = bb.min.x, bb.min.y, bb.min.z
      when 1
        local_x = Geom::Vector3d.new(0,1,0); local_y = Geom::Vector3d.new(1,0,0); local_z = Geom::Vector3d.new(0,0,-1)
        min_long, min_y, min_z = bb.min.y, bb.min.x, -bb.max.z
      else
        local_x = Geom::Vector3d.new(0,0,1); local_y = Geom::Vector3d.new(1,0,0); local_z = Geom::Vector3d.new(0,1,0)
        min_long, min_y, min_z = bb.min.z, bb.min.x, bb.min.y
      end
      canon = Geom::Transformation.axes(ORIGIN, local_x, local_y, local_z).inverse
      move0 = Geom::Transformation.translation(Geom::Vector3d.new(-min_long, -min_y, -min_z))
      roll_tr = Geom::Transformation.rotation(ORIGIN, Geom::Vector3d.new(1,0,0), roll * Math::PI / 180.0)
      source_tr = LibraryFrameSettings.orient(roll_tr * move0 * canon,options)
      rotated = 8.times.map { |i| bb.corner(i).transform(source_tr) }
      cross_min_y = rotated.map(&:y).min
      cross_min_z = rotated.map(&:z).min
      cross_width = rotated.map(&:y).max - cross_min_y
      anchor_y,anchor_z,section_low,section_high = LibraryFrameSettings.alignment(anchor_source,source_tr,anchor,cross_min_y,cross_min_z,cross_width)
      source_tr = Geom::Transformation.translation(Geom::Vector3d.new(0,-anchor_y,-anchor_z)) * source_tr
      spatial_section = LibraryEdgePath.section_points(anchor_source,source_tr) if path_plan[:spatial]


      chain.each_with_index do |row, idx|
        _edge, a0, b0 = row
        vec = b0 - a0; edge_len = vec.length
        next if edge_len <= 1.0e-6
        xw, yw, zw = path_plan[:frames][idx]

        closed = chain[-1][2].distance(chain[0][1]).to_f < (0.001 / 25.4)
        start_plane = if idx > 0 || closed
          v277_miter_plane(a0, b0-a0, chain[(idx-1)%chain.length][1]-a0)
        end
        end_plane = if idx < chain.length-1 || closed
          v277_miter_plane(b0, a0-b0, chain[(idx+1)%chain.length][2]-b0)
        end
        width = cross_width
        allowance = lambda do |plane,at_start|
          next LibraryEdgePath.allowance(plane,at_start,path_plan[:frames][idx],spatial_section) if path_plan[:spatial]
          next 0.0 unless plane
          den = plane[1].dot(xw)
          raise 'Góc quá nhọn để cắt phào.' if den.abs < 1.0e-6
          ratio = plane[1].dot(yw)/den
          factor=at_start ? ratio : -ratio
          [0.0, section_low*factor, section_high*factor].max
        end
        # For an inward rectangular frame, no negative start offset is needed.
        # Lock the same unscaled ornament phase at all four outer vertices.
        start_extra = allowance.call(start_plane,true)
        end_extra = allowance.call(end_plane,false)
        usable = edge_len + start_extra + end_extra
        count = [(usable / src_len).ceil, 1].max
        count.times do |j|
          offset = -start_extra + j * src_len
          # Preserve the source relief scale; trim the full-length last module.
          seg = src_len
          scale_long = 1.0
          pos = a0.offset(xw, offset)
          world = Geom::Transformation.axes(pos, xw, yw, zw)
          # Scale after source normalization, so an off-origin SKP stays aligned.
          tr = world * Geom::Transformation.scaling(ORIGIN, scale_long, 1.0, 1.0) * source_tr
          inst = ents.add_instance(definition, tr)
          next unless inst
          inst.name = "Assembly Edge #{idx+1} - #{j+1}/#{count}"
          inst.set_attribute('LOFIHOME','engine','V306_AUTO_MITER')
          inst.set_attribute('LOFIHOME','edge_index',idx)
          inst.set_attribute('LOFIHOME','segment_length',seg.to_f)
        end
      end

      parent.set_attribute('LOFIHOME','engine','V306_AUTO_MITER_ASSEMBLY_LITE')
      parent.set_attribute('LOFIHOME','source_skp',File.expand_path(path))
      parent.set_attribute('LOFIHOME','roll',roll)
      LibraryFrameSettings.store(parent,options,roll,anchor,replace_group)
      parent.set_attribute('LOFIHOME','straight_seams','V317_3_HIDDEN_SOURCE_ENDS')
      parent.set_attribute('LOFIHOME','source_axis',axis_name)
      parent.set_attribute('LOFIHOME','edge_count',chain.length)
      parent.set_attribute('LOFIHOME','render_mask',@v31714_render_mask)
      parent.set_attribute('LOFIHOME','rule','FULL_3D_DECO_AUTO_BISECTOR_MITER')
      # Save the ordered path before automatic clipping.
      path_data = chain.map { |r| [r[1].to_a, r[2].to_a] }
      parent.set_attribute('LOFIHOME','path_data', path_data.to_json)
      Sketchup.set_status_text('LOFIHOME: Đang cắt các đầu góc 45°…')
      v306_cut_path_corners(parent)
      v3179_split_frame(parent,body_only) if split_body_and_ornament
      LibraryMouldingSeams.apply(parent) if split_body_and_ornament
      parent.set_attribute('LOFIHOME','separate_body',split_body_and_ornament)
      parent.set_attribute('LOFIHOME','build_stage',body_only ? 'body' : 'complete')
      parent.transformation=options['_surface_placement'] if options['_surface_placement']
      if options['_surface_batch'] || (replace_group && replace_group.get_attribute('LOFIHOME','surface_run',false))
        parent.set_attribute('LOFIHOME','surface_run',true)
      end
      if options['_preserve_placement'] && replace_group
        parent.transformation=replace_group.transformation
        parent.material=replace_group.material
        parent.layer=replace_group.layer
        parent.name=replace_group.name
      end
      options['_decorate_frame'].call(parent) if options['_decorate_frame']
      options['_before_replace'].call if options['_before_replace']
      replace_group.erase! if replace_group && replace_group.valid?
      unless options['_surface_batch'] || options['_external_operation']
        model.selection.clear; model.selection.add(parent)
        raise 'Không hoàn tất được cập nhật phào.' if model.commit_operation==false
        operation_started=false
        model.active_view.invalidate
      end
      @external_gallery.close rescue nil
      parent
    rescue => e
      model.abort_operation if operation_started
      raise if options['_surface_batch'] || options['_external_operation']
      UI.messagebox("Lỗi dựng khung phào V317.198:\n#{e.class}: #{e.message}")
      nil
    ensure
      @v31714_render_mask=false
      Sketchup.set_status_text('')
    end

    def self.rebuild_ornament_frame(render_mask=nil)
      model = Sketchup.active_model
      group = model.selection.grep(Sketchup::Group).find { |g| g.get_attribute('LOFIHOME','source_skp') && g.get_attribute('LOFIHOME','path_data') }
      unless group
        UI.messagebox('Chọn Group khung phào rồi bấm SỬA KHUNG PHÀO.')
        return
      end
      mask=render_mask.nil? ? group.get_attribute('LOFIHOME','render_mask',false) : render_mask
      if !mask && group.get_attribute('LOFIHOME','fast_ornament_stats') && group.get_attribute('LOFIHOME','build_stage')=='complete'
        return v31789_refresh_frame(group)
      end
      return LibraryFaceRun.rebuild(group,nil,mask) if group.get_attribute('LOFIHOME','surface_run',false)
      raw = JSON.parse(group.get_attribute('LOFIHOME','path_data'))
      rows = raw.map { |ab| ab.map { |p| Geom::Point3d.new(p).transform(group.transformation) } }
      path = group.get_attribute('LOFIHOME','source_skp')
      path = File.join(ROOT,'library','SU84_104.skp') unless File.file?(path)
      opts = {'build_stage'=>group.get_attribute('LOFIHOME','build_stage','complete'),
              'render_mask'=>render_mask.nil? ? group.get_attribute('LOFIHOME','render_mask',false) : render_mask,
              'profile_flip_y'=>group.get_attribute('LOFIHOME','profile_flip_y',false),
              'profile_flip_z'=>group.get_attribute('LOFIHOME','profile_flip_z',false),
              'profile_anchor'=>group.get_attribute('LOFIHOME','profile_anchor','legacy'),
              'roll'=>group.get_attribute('LOFIHOME','roll',270),
              'source_axis'=>group.get_attribute('LOFIHOME','source_axis','x')}
      run_external_full3d_on_selected_edges(path,opts,rows,group)
    rescue => e
      UI.messagebox("Lỗi sửa khung phào: #{e.class}: #{e.message}")
    end

    def self.rotate_ornament_frame
      model = Sketchup.active_model
      group = model.selection.grep(Sketchup::Group).find { |g| g.get_attribute('LOFIHOME','source_skp') && g.get_attribute('LOFIHOME','path_data') }
      unless group
        UI.messagebox('Chọn Group phào hoa văn rồi bấm XOAY MẶT PHÀO 90°.')
        return
      end
      return LibraryFaceRun.rebuild(group,(group.get_attribute('LOFIHOME','roll',0).to_f+90.0)%360.0) if group.get_attribute('LOFIHOME','surface_run',false)
      raw = JSON.parse(group.get_attribute('LOFIHOME','path_data'))
      rows = raw.map { |ab| ab.map { |p| Geom::Point3d.new(p).transform(group.transformation) } }
      opts = {'build_stage'=>group.get_attribute('LOFIHOME','build_stage','complete'),
              'render_mask'=>group.get_attribute('LOFIHOME','render_mask',false),
              'profile_flip_y'=>group.get_attribute('LOFIHOME','profile_flip_y',false),
              'profile_flip_z'=>group.get_attribute('LOFIHOME','profile_flip_z',false),
              'profile_anchor'=>group.get_attribute('LOFIHOME','profile_anchor','legacy'),
              'roll'=>(group.get_attribute('LOFIHOME','roll',0).to_f+90.0)%360.0,
              'source_axis'=>group.get_attribute('LOFIHOME','source_axis','auto')}
      run_external_full3d_on_selected_edges(group.get_attribute('LOFIHOME','source_skp'),opts,rows,group)
    rescue => e
      UI.messagebox("Lỗi xoay mặt phào: #{e.class}: #{e.message}")
    end

    # Clip every module crossing a joint, including both ends of a short edge.
    # Interior modules remain shared components; only cut modules become groups.
    # Each joint owns ONE plane, used for both adjacent rails with opposite sides.
    # This includes the joint between the last and first rows of a closed frame.
    def self.v317_joint_jobs(rows)
      closed=rows[-1][1].distance(rows[0][0]).to_f < (0.001 / 25.4)
      spatial=LibraryEdgePath.plan(rows.map { |a,b|[nil,a,b] })[:spatial]
      jobs=[]
      rows.each_with_index do |(a,b),i|
        if i > 0 || closed
          previous=(i-1)%rows.length
          vertex=a
          raise 'Path có khe hở tại góc.' if rows[previous][1].distance(vertex).to_f > (0.01 / 25.4)
          plane=v277_miter_plane(vertex,rows[previous][0]-vertex,b-vertex)
          plane||=[vertex,b-vertex] if spatial
          next unless plane
          jobs << [previous,plane,:end]
          jobs << [i,plane,:start]
        end
      end
      unless closed
        jobs << [0,[rows[0][0],rows[0][1]-rows[0][0]],:start]
        jobs << [rows.length-1,[rows[-1][1],rows[-1][1]-rows[-1][0]],:end]
      end
      jobs
    end

    def self.v317_verify_halfspace(part,point,normal,keep)
      n=normal.normalize
      sign=(keep-point).dot(n)>=0 ? 1.0 : -1.0
      # A bounding box encloses every nested vertex, including hidden relief.
      # Only descend into the detailed mesh when the box crosses the plane.
      box=part.bounds
      unless box.empty?
        inside=8.times.all? { |i| (box.corner(i)-point).dot(n)*sign >= 0.0 }
        return true if inside
      end
      checked=0
      visit=nil
      visit=lambda do |entities,tr|
        entities.each do |e|
          next if e.respond_to?(:hidden?) && e.hidden?
          if e.is_a?(Sketchup::Face)
            e.vertices.each do |v|
              checked+=1
              distance=(v.position.transform(tr)-point).dot(n)*sign
              raise 'Đỉnh còn vượt mặt cắt góc; đã hủy thao tác.' if distance < -0.01.mm
            end
          elsif e.is_a?(Sketchup::Group)
            visit.call(e.entities,tr*e.transformation)
          elsif e.is_a?(Sketchup::ComponentInstance)
            visit.call(Compat.definition(e).entities,tr*e.transformation)
          end
        end
      end
      entities=part.is_a?(Sketchup::Group) ? part.entities : Compat.definition(part).entities
      visit.call(entities,part.transformation)
      raise 'Không có đỉnh để kiểm tra đầu góc.' if checked==0 && !@v31714_render_mask
      true
    end

    def self.v306_cut_path_corners(parent, force = false)
      data=JSON.parse(parent.get_attribute('LOFIHOME','path_data').to_s)
      rows=data.map { |ab| [Geom::Point3d.new(ab[0]),Geom::Point3d.new(ab[1])] }
      raise 'Path không hợp lệ.' if rows.empty?
      done=0;cache={}
      v317_joint_jobs(rows).each do |edge_index,plane,role|
        a,b=rows[edge_index]
        direction=(b-a).normalize
        midpoint=Geom::Point3d.new((a.x+b.x)*0.5,(a.y+b.y)*0.5,(a.z+b.z)*0.5)
        point,normal=plane
        normal=normal.normalize
        sign=(midpoint-point).dot(normal)>=0 ? 1.0 : -1.0
        parts=parent.entities.to_a.select do |e|
          (e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)) &&
            e.valid? && e.get_attribute('LOFIHOME','edge_index')==edge_index
        end
        raise "Thiếu thanh phào cạnh #{edge_index+1}." if parts.empty?
        endpoint = role==:start ? parts.min_by { |e| (e.bounds.center-a).dot(direction) } :
                                  parts.max_by { |e| (e.bounds.center-a).dot(direction) }
        parts.each do |part|
          box=part.bounds
          distances=8.times.map { |i| (box.corner(i)-point).dot(normal)*sign }
          if distances.max < -1.0e-7 && !@v31714_render_mask
            part.erase!
            next
          end
          next if !part.equal?(endpoint) && distances.min >= -1.0e-7
          clipped=v277_clip_instance_to_plane(part,point,normal,midpoint,parent.entities,
                                              "45° Joint Edge #{edge_index+1} #{role}",cache)
          raise 'Không dựng được đầu thanh cắt góc.' unless clipped && clipped.valid?
          clipped.set_attribute('LOFIHOME','edge_index',edge_index)
          clipped.set_attribute('LOFIHOME','engine','V317_SHARED_PLANE_MITER')
          v317_verify_halfspace(clipped,point,normal,midpoint)
          done+=1
        end
      end
      # Length comparisons use tolerance. The planner converts distance to Float
      # so the last-to-first vertex belongs to a CLOSED path, not two square ends.
      jobs=v317_joint_jobs(rows)
      # Audit after ALL mutations; do not trust the old completed marker.
      jobs.each do |edge_index,plane,role|
        a,b=rows[edge_index]
        midpoint=Geom::Point3d.new((a.x+b.x)*0.5,(a.y+b.y)*0.5,(a.z+b.z)*0.5)
        parent.entities.to_a.each do |part|
          next unless (part.is_a?(Sketchup::Group) || part.is_a?(Sketchup::ComponentInstance)) &&
            part.valid? && part.get_attribute('LOFIHOME','edge_index')==edge_index
          v317_verify_halfspace(part,plane[0],plane[1],midpoint)
        end
      end
      parent.set_attribute('LOFIHOME','corners_cut','V317_2_CLOSED_FLOAT_VERIFIED')
      done
    end

    def self.v300_cut_4_corners
      model = Sketchup.active_model
      parent = model.selection.grep(Sketchup::Group).find do |g|
        g.valid? && g.get_attribute('LOFIHOME','path_data') &&
          g.get_attribute('LOFIHOME','engine').to_s.match(/ASSEMBLY_LITE|CORNER_LITE/)
      end
      unless parent
        UI.messagebox('Hãy chọn Group phào hoa văn vừa tạo.')
        return false
      end
      return rebuild_ornament_frame if parent.get_attribute('LOFIHOME','assembly')=='V317_9_BODY_RAILS_AND_ORNAMENT'
      model.start_operation('LOFIHOME - Cắt góc hoa văn tự động',true)
      done = v306_cut_path_corners(parent,true)
      model.commit_operation
      model.active_view.invalidate
      UI.messagebox("Đã kiểm tra lại các đầu thanh, kể cả góc khép vòng.\nCắt thêm #{done} lượt mặt phẳng 45°.")
      true
    rescue => e
      model.abort_operation rescue nil
      UI.messagebox("Lỗi cắt góc: #{e.class}: #{e.message}")
      false
    end

