    def self.profile_signature(p)
      pts = Array(p['points']).map { |xy| [xy[0].to_f.round(4), xy[1].to_f.round(4)] }
      [pts, p['actual_width'].to_f.round(2), p['actual_height'].to_f.round(2)].to_json
    end

    def self.load_user_profiles
      portable_initialize
      return [] unless File.exist?(USER_LIBRARY)
      data = JSON.parse(File.read(USER_LIBRARY, :encoding => 'UTF-8'))
      data = [] unless data.is_a?(Array)
      seen = {}
      data.select do |p|
        sig = p['id'].to_s.empty? ? profile_signature(p) : p['id']
        keep = !seen[sig]
        seen[sig] = true
        keep
      end
    rescue
      []
    end

