    def self.normalize_points(points)
      xs = points.map { |p| p[0].to_f }; ys = points.map { |p| p[1].to_f }
      minx,maxx=xs.minmax; miny,maxy=ys.minmax
      dx=maxx-minx; dy=maxy-miny
      raise 'Biên dạng không đủ kích thước.' if dx.abs < 1e-9 || dy.abs < 1e-9
      points.map { |p| [((p[0].to_f-minx)/dx).round(6), ((p[1].to_f-miny)/dy).round(6)] }
    end

    # V4.9: ADD biên dạng từ Face HOẶC Group/Component đã chọn.
    # Nếu chọn Group/Component, tự đi xuyên các cấp lồng nhau và tìm Face ở hai đầu thanh.
    def self.profile_data_from_face(face, transform, meta={})
      verts = face.outer_loop.vertices.map { |v| v.position.transform(transform) }
      raise 'Face không đủ 3 đỉnh.' if verts.length < 3
      origin = verts.first
      # Cạnh dài nhất sau transform làm trục X của mặt cắt.
      edge_pts = face.outer_loop.edges.map do |e|
        [e.start.position.transform(transform), e.end.position.transform(transform)]
      end
      a,b = edge_pts.max_by { |u,v| u.distance(v) }
      xaxis = (b-a).normalize
      # Tạo trục Y ngay trong mặt phẳng từ 3 điểm không thẳng hàng, tránh lỗi normal khi có scale/mirror.
      normal = nil
      verts.each_cons(2) do |u,v|
        n = xaxis * (v-origin)
        if n.length > 1e-8
          normal = n.normalize
          break
        end
      end
      normal ||= face.normal.transform(transform).normalize
      yaxis = normal * xaxis
      raw = verts.map { |pt| vv=pt-origin; [vv.dot(xaxis).to_f, vv.dot(yaxis).to_f] }
      xs=raw.map{|q|q[0]}; ys=raw.map{|q|q[1]}; minx,maxx=xs.minmax; miny,maxy=ys.minmax
      dx=maxx-minx; dy=maxy-miny
      raise 'Face không đủ kích thước.' if dx.abs < 1e-9 || dy.abs < 1e-9
      scale=[dx,dy].max
      pts=raw.map{|q| [((q[0]-minx)/scale).round(7), ((q[1]-miny)/scale).round(7)]}
      [pts, dx.to_mm.to_f, dy.to_mm.to_f, verts.length]
    end

    def self.save_face_profile(face, transform, meta={})
      pts, width_mm, height_mm, vertex_count = profile_data_from_face(face, transform, meta)
      id="U#{Time.now.to_i}#{rand(1000)}"
      name=meta['name'].to_s.strip
      name="Mẫu ngoài #{id}" if name.empty? || name=='Biên dạng ngoài'
      profile={'id'=>id,'name'=>name,'category'=>'Mẫu ngoài',
               'nominal_width'=>(meta['nominal_width'].to_f > 0 ? meta['nominal_width'].to_f : width_mm.round(2)),
               'actual_width'=>width_mm.round(3),'actual_height'=>height_mm.round(3),
               'points'=>pts,'user_added'=>true}
      profiles << profile; save_user_profiles; refresh_dialog_profiles
      UI.messagebox("Đã ADD biên dạng vào kho mẫu.\nKích thước: #{width_mm.round(2)} x #{height_mm.round(2)} mm\nSố đỉnh đường bao: #{vertex_count}")
      profile
    end

    def self.add_profile_from_selected_face(meta={})
      sel=Sketchup.active_model.selection.to_a
      # Chọn trực tiếp một Face vẫn hoạt động như trước.
      faces=sel.grep(Sketchup::Face)
      return save_face_profile(faces.first, Geom::Transformation.new, meta) if faces.length==1 && sel.length==1

      roots=sel.select{|e| e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance)}
      if roots.length != 1 || sel.length != 1
        UI.messagebox('Hãy chọn 1 Face hoặc 1 Group/Component lam/phào rồi bấm ADD biên dạng.')
        return
      end
      root=roots.first
      all=[]
      if root.is_a?(Sketchup::Group)
        collect_faces(root.entities, root.transformation, all)
      else
        collect_faces(Compat.definition(root).entities, root.transformation, all)
      end
      raise 'Không tìm thấy Face bên trong Group/Component.' if all.empty?

      # Bounding box thật của toàn bộ face; trục dài nhất được xem là chiều dài thanh.
      world_pts=all.flat_map{|f,tr| f.vertices.map{|v| v.position.transform(tr)}}
      mins=[world_pts.map(&:x).min,world_pts.map(&:y).min,world_pts.map(&:z).min]
      maxs=[world_pts.map(&:x).max,world_pts.map(&:y).max,world_pts.map(&:z).max]
      spans=3.times.map{|i| maxs[i]-mins[i]}
      long_i=spans.each_with_index.max[1]
      tol=[spans[long_i]*0.015, 0.5.mm].max

      candidates=[]
      all.each do |face,tr|
        pts=face.outer_loop.vertices.map{|v|v.position.transform(tr)}
        vals=pts.map{|p| [p.x,p.y,p.z][long_i]}
        face_span=vals.max-vals.min
        c=vals.sum/vals.length.to_f
        near_end=((c-mins[long_i]).abs <= tol*2.0 || (c-maxs[long_i]).abs <= tol*2.0)
        next unless face_span <= tol && near_end
        begin
          pdata=profile_data_from_face(face,tr,meta)
          # ưu tiên nhiều đỉnh (biên dạng chi tiết) rồi diện tích mặt lớn.
          candidates << [face,tr,pdata,pts.length,face.area.to_f]
        rescue
        end
      end
      # Nếu model không có mặt đúng ngay đầu, vẫn cho chọn trong các face gần vuông góc trục dài.
      if candidates.empty?
        all.each do |face,tr|
          pts=face.outer_loop.vertices.map{|v|v.position.transform(tr)}
          vals=pts.map{|p| [p.x,p.y,p.z][long_i]}
          next unless (vals.max-vals.min) <= tol
          begin
            pdata=profile_data_from_face(face,tr,meta)
            candidates << [face,tr,pdata,pts.length,face.area.to_f]
          rescue
          end
        end
      end
      raise 'Không tìm thấy Face mặt cắt phù hợp trong Group/Component.' if candidates.empty?
      candidates.sort_by!{|x| [-x[3],-x[4]]}
      candidates=candidates.first(20)
      chosen=candidates.first
      if candidates.length>1
        labels=candidates.each_with_index.map do |x,i|
          _f,_tr,pd,n,_a=x; "#{i+1}: #{pd[1].round(1)} x #{pd[2].round(1)} mm - #{n} đỉnh"
        end
        r=UI.inputbox(['Chọn mặt cắt cần lưu:'],[labels[0]],[labels.join('|')],'V4.9 - Chọn mặt cắt trong Group')
        return unless r
        idx=labels.index(r[0].to_s) || 0
        chosen=candidates[idx]
      end
      save_face_profile(chosen[0],chosen[1],meta)
    end

    # V5.9.4: lưu CHÍNH XÁC outer_loop của Face/Face đầu Group làm Lam sóng cố định.
    # Mẫu fixed_lam_profile không bị hàm lam_wave_points dựng lại thành sóng giả lập.
    def self.add_exact_lam_from_selection(meta={})
      p = add_profile_from_selected_face(meta.merge('name' => (meta['name'].to_s.strip.empty? ? 'Lam sóng TES 3 - biên dạng gốc' : meta['name'])))
      return nil unless p
      p['category'] = 'Lam sóng'
      p['fixed_lam_profile'] = true
      p['lam_count'] = (meta['lam_count'] || 1).to_i
      p['lam_depth'] = (p['actual_height'] || 10).to_f
      p['lam_height'] = 0.0
      p['source_type'] = 'EXACT_FACE_OUTER_LOOP'
      # V202 TEST: dùng trực tiếp contour đã gán của đúng file SKP, không save/reload qua thư viện chung.
      UI.messagebox("Đã lưu biên dạng Lam sóng 1:1 từ Face/Group đang chọn.\nKích thước: #{p['actual_width']} x #{p['actual_height']} mm\nSố đỉnh: #{p['detected_vertices'] || p['points'].length}")
      p
    end

    def self.profile_from_points(points, name, nominal_width = 0)
      pts = normalize_points(points)
      id = "U#{Time.now.to_i}#{rand(100000)}"
      {'id'=>id, 'name'=>name.to_s, 'category'=>'Mẫu ngoài',
       'nominal_width'=>nominal_width.to_f, 'points'=>pts, 'user_added'=>true}
    end

    def self.face_points_2d(face, transform = Geom::Transformation.new)
      verts = face.outer_loop.vertices.map { |v| v.position.transform(transform) }
      raise 'Face không đủ 3 điểm.' if verts.length < 3
      origin = verts.first
      normal = face.normal.transform(transform)
      xaxis = (verts[1] - origin).normalize
      yaxis = normal * xaxis
      verts.map { |pt| v = pt - origin; [v.dot(xaxis), v.dot(yaxis)] }
    end

    def self.collect_faces(entities, transform = Geom::Transformation.new, out = [])
      entities.each do |e|
        if e.is_a?(Sketchup::Face)
          out << [e, transform]
        elsif e.is_a?(Sketchup::Group)
          collect_faces(e.entities, transform * e.transformation, out)
        elsif e.is_a?(Sketchup::ComponentInstance)
          collect_faces(Compat.definition(e).entities, transform * e.transformation, out)
        end
      end
      out
    end

    def self.add_best_face_as_profile(faces, name)
      raise 'Không tìm thấy Face kín trong file.' if faces.empty?
      face, tr = faces.max_by { |f,t| f.area.to_f }
      profile = profile_from_points(face_points_2d(face, tr), name)
      # V202 TEST: không đưa profile tạm vào thư viện chung để tránh lookup nhầm biên dạng.
      profile
    end

    # Basic ASCII DXF reader. Handles LWPOLYLINE, classic POLYLINE/VERTEX and LINE.
    # For complex DXF/DWG, SketchUp's installed CAD importer is tried first.
    def self.parse_ascii_dxf(path)
      lines = File.readlines(path, :encoding => 'bom|utf-8', :invalid => :replace, :undef => :replace).map(&:strip)
      pairs = []
      (0...(lines.length-1)).step(2) { |i| pairs << [lines[i], lines[i+1]] }
      polylines = []
      line_segments = []
      i = 0
      while i < pairs.length
        code, val = pairs[i]
        if code == '0' && val == 'LWPOLYLINE'
          pts=[]; closed=false; i += 1
          while i < pairs.length && pairs[i][0] != '0'
            c,v=pairs[i]
            if c=='70'; closed=(v.to_i & 1)==1
            elsif c=='10'
              x=v.to_f; y=0.0
              if i+1 < pairs.length && pairs[i+1][0]=='20'; y=pairs[i+1][1].to_f; i+=1 end
              pts << [x,y]
            end
            i += 1
          end
          polylines << pts if pts.length >= 3 && closed
          next
        elsif code == '0' && val == 'POLYLINE'
          pts=[]; closed=false; i += 1
          while i < pairs.length
            c,v=pairs[i]
            if c=='70'; closed=(v.to_i & 1)==1
            elsif c=='0' && v=='VERTEX'
              x=y=nil; i+=1
              while i < pairs.length && pairs[i][0] != '0'
                cc,vv=pairs[i]; x=vv.to_f if cc=='10'; y=vv.to_f if cc=='20'; i+=1
              end
              pts << [x,y] if x && y
              next
            elsif c=='0' && v=='SEQEND'; i+=1; break
            end
            i+=1
          end
          polylines << pts if pts.length >= 3 && closed
          next
        elsif code == '0' && val == 'LINE'
          x1=y1=x2=y2=nil; i+=1
          while i < pairs.length && pairs[i][0] != '0'
            c,v=pairs[i]; x1=v.to_f if c=='10'; y1=v.to_f if c=='20'; x2=v.to_f if c=='11'; y2=v.to_f if c=='21'; i+=1
          end
          line_segments << [[x1,y1],[x2,y2]] if [x1,y1,x2,y2].all?
          next
        end
        i += 1
      end
      return polylines.max_by { |p| p.length } unless polylines.empty?
      # Join LINE entities into a closed chain, tolerant to tiny CAD rounding errors.
      return nil if line_segments.empty?
      tol=1e-5; segs=line_segments.dup; chain=[segs.shift[0], line_segments.first ? line_segments.first[0] : nil].compact
      # restart correctly from first segment
      first=line_segments.first
      segs=line_segments.dup
      a,b=segs.shift; chain=[a,b]
      while !segs.empty?
        last=chain[-1]
        idx=segs.index { |u,v| ((u[0]-last[0])**2+(u[1]-last[1])**2)**0.5 < tol || ((v[0]-last[0])**2+(v[1]-last[1])**2)**0.5 < tol }
        break unless idx
        u,v=segs.delete_at(idx)
        nxt=(((u[0]-last[0])**2+(u[1]-last[1])**2)**0.5 < tol) ? v : u
        chain << nxt
        break if chain.length>=3 && ((chain[-1][0]-chain[0][0])**2+(chain[-1][1]-chain[0][1])**2)**0.5 < tol
      end
      return nil unless chain.length>=4 && ((chain[-1][0]-chain[0][0])**2+(chain[-1][1]-chain[0][1])**2)**0.5 < tol
      chain[0...-1]
    end

    def self.import_cad_via_sketchup(path)
      model=Sketchup.active_model
      before=model.entities.to_a
      model.start_operation('ADD biên dạng CAD', true)
      ok=model.import(path, { :merge_coplanar_faces => true, :orient_faces => true })
      raise 'SketchUp không import được file này. Với DWG/DXF cần bản SketchUp có bộ nhập CAD.' unless ok
      added=model.entities.to_a - before
      faces=[]
      added.each do |e|
        if e.is_a?(Sketchup::Face); faces << [e, Geom::Transformation.new]
        elsif e.is_a?(Sketchup::Group); collect_faces(e.entities, e.transformation, faces)
        elsif e.is_a?(Sketchup::ComponentInstance); collect_faces(Compat.definition(e).entities, e.transformation, faces)
        end
      end
      profile=add_best_face_as_profile(faces, File.basename(path,'.*'))
      added.each { |e| e.erase! if e.valid? }
      model.commit_operation
      profile
    rescue => e
      model.abort_operation if model
      raise e
    end

    def self.point_key(p, tol = 0.001.mm)
      [(p.x / tol).round, (p.y / tol).round, (p.z / tol).round]
    end

    def self.stitch_boundary_loop(edge_pairs)
      return nil if edge_pairs.empty?
      adj = Hash.new { |h,k| h[k] = [] }
      pts = {}
      edge_pairs.each do |a,b|
        ka = point_key(a); kb = point_key(b)
        next if ka == kb
        pts[ka]=a; pts[kb]=b
        adj[ka] << kb unless adj[ka].include?(kb)
        adj[kb] << ka unless adj[kb].include?(ka)
      end
      starts = adj.keys.select { |k| adj[k].length == 2 }
      return nil if starts.empty?
      best=nil
      starts.each do |st|
        loop_keys=[st]; prev=nil; cur=st
        10000.times do
          nxts=adj[cur].reject{|x| x==prev}
          break if nxts.empty?
          nxt=nxts.first
          if nxt==st
            return loop_keys.map{|k| pts[k]} if loop_keys.length >= 3
            break
          end
          break if loop_keys.include?(nxt)
          loop_keys << nxt; prev=cur; cur=nxt
        end
        best=loop_keys if best.nil? || loop_keys.length>best.length
      end
      best && best.length>=3 ? best.map{|k|pts[k]} : nil
    end

    def self.project_axis_points(points, long_i)
      # Chiếu tiết diện lên 2 trục còn lại, giữ đúng hình học biên dạng.
      axes = [0,1,2] - [long_i]
      points.map do |p|
        xyz=[p.x,p.y,p.z]
        [xyz[axes[0]], xyz[axes[1]]]
      end
    end

    def self.section_segments_for_face(face, tr, axis_i, cut, eps)
      pts=[]
      face.loops.each do |lp|
        lp.edges.each do |e|
        a=e.start.position.transform(tr); b=e.end.position.transform(tr)
        av=[a.x,a.y,a.z][axis_i]-cut; bv=[b.x,b.y,b.z][axis_i]-cut
        if av.abs <= eps && bv.abs <= eps
          pts << a << b
        elsif av.abs <= eps
          pts << a
        elsif bv.abs <= eps
          pts << b
        elsif av*bv < 0.0
          t=av/(av-bv)
          pts << Geom::Point3d.new(a.x+(b.x-a.x)*t, a.y+(b.y-a.y)*t, a.z+(b.z-a.z)*t)
        end
        end
      end
      uniq=[]
      pts.each{|q| uniq << q unless uniq.any?{|u| u.distance(q) <= eps*5.0}}
      return [] if uniq.length < 2
      # Một face phẳng cắt bởi mặt phẳng cho một đoạn; lấy cặp xa nhất để tránh điểm trùng ở vertex.
      best=nil; dist=-1.0
      uniq.combination(2){|a,b| d=a.distance(b); if d>dist; dist=d; best=[a,b]; end}
      best ? [best] : []
    end

    def self.stitch_all_boundary_loops(edge_pairs)
      # V4.7: chỉ chấp nhận chu trình kín thật. Không biến chain hở thành profile.
      tol = 0.01.mm
      key_for = lambda { |p| point_key(p, tol) }
      pts = {}
      adj = Hash.new { |h,k| h[k] = [] }
      edges = {}
      edge_pairs.each do |a,b|
        ka=key_for.call(a); kb=key_for.call(b)
        next if ka==kb
        pts[ka]=a; pts[kb]=b
        ek=[ka,kb].sort
        next if edges.key?(ek)
        edges[ek]=true
        adj[ka] << kb
        adj[kb] << ka
      end

      # Tiết diện manifold chuẩn: mỗi đỉnh của một loop kín có degree=2.
      valid = adj.keys.select { |k| adj[k].length == 2 }
      valid_set = {}; valid.each{|k| valid_set[k]=true}
      visited_edges={}; loops=[]
      valid.each do |st|
        adj[st].each do |first|
          ek=[st,first].sort; next if visited_edges[ek]
          chain=[st]; prev=nil; cur=st; nxt=first; closed=false
          20000.times do
            ekey=[cur,nxt].sort; visited_edges[ekey]=true
            prev,cur=cur,nxt
            if cur==st
              closed=true; break
            end
            break unless valid_set[cur]
            chain << cur
            choices=adj[cur].reject{|k| k==prev}
            break unless choices.length==1
            nxt=choices[0]
          end
          if closed && chain.length>=3
            loops << chain.map{|k|pts[k]}
          end
        end
      end
      loops
    end

    def self.import_skp_profile(path)
      model=Sketchup.active_model
      definition=v311_load_source(path)
      faces=collect_faces(definition.entities)
      raise 'Không tìm thấy hình học Face trong file SKP.' if faces.empty?
      all_pts=[]
      faces.each{|face,tr| face.outer_loop.vertices.each{|v| all_pts << v.position.transform(tr)}}
      raise 'File SKP không có đủ hình học để nhận dạng.' if all_pts.length<3
      mins=[all_pts.map(&:x).min,all_pts.map(&:y).min,all_pts.map(&:z).min]
      maxs=[all_pts.map(&:x).max,all_pts.map(&:y).max,all_pts.map(&:z).max]
      spans=3.times.map{|i|maxs[i]-mins[i]}
      long_i=spans.each_with_index.max[1]
      eps=[spans[long_i]*1.0e-7,0.001.mm].max

      # V5.9.9.200: ƯU TIÊN lấy chính Face mặt đầu của thanh phào.
      # Đây là biên dạng thật người dùng nhìn thấy trong file SKP, tránh chọn nhầm
      # vòng cắt nội bộ / bounding rectangle ở giữa model.
      end_candidates=[]
      tol_end=[spans[long_i]*0.015, 0.5.mm].max
      faces.each do |face,tr|
        begin
          verts=face.outer_loop.vertices.map{|v| v.position.transform(tr)}
          vals=verts.map{|pt| [pt.x,pt.y,pt.z][long_i]}
          fspan=vals.max-vals.min
          center=vals.sum/vals.length.to_f
          near_end=((center-mins[long_i]).abs <= tol_end*2.0 || (center-maxs[long_i]).abs <= tol_end*2.0)
          # V181: mặt cắt thật bắt buộc phải vuông góc với trục dài của thanh.
          # Chỉ kiểm tra vị trí ở đầu thanh là chưa đủ vì các mặt hông xiên/bo cũng có thể nằm sát đầu.
          n = face.normal.transform(tr)
          n.normalize! rescue nil
          axis_comp = [n.x.abs, n.y.abs, n.z.abs][long_i]
          next unless fspan <= tol_end && near_end && axis_comp >= 0.985
          pts_raw=face.outer_loop.vertices.map{|v| v.position.transform(tr)}
          pts2=project_axis_points(pts_raw,long_i)
          xs=pts2.map{|q|q[0]}; ys=pts2.map{|q|q[1]}
          w=(xs.max-xs.min).abs; h=(ys.max-ys.min).abs
          next if w<=0.01.mm || h<=0.01.mm
          # Profile phào thường là mặt đầu chi tiết: ưu tiên nhiều đỉnh, sau đó diện tích.
          # Phạt mạnh mặt chữ nhật 4 đỉnh để tránh lấy mặt bao/đế đơn giản.
          score=pts2.length*1_000_000.0 + face.area.to_f - (pts2.length<=4 ? 100_000_000.0 : 0)
          end_candidates << [score,pts2,'Face mặt đầu']
        rescue
        end
      end
      unless end_candidates.empty?
        end_candidates.sort_by!{|x|-x[0]}
        best=end_candidates.first
        pts2=best[1]
        profile=profile_from_points(pts2,File.basename(path,'.*'))
        xs=pts2.map{|q|q[0]}; ys=pts2.map{|q|q[1]}
        profile['nominal_width']=[(xs.max-xs.min).abs,(ys.max-ys.min).abs].max.to_mm.round(2)
        profile['source_type']='SKP_EXACT_END_FACE_V181_NORMAL_LOCK'
        profile['source_file']=File.basename(path)
        profile['detected_vertices']=pts2.length
        # V202 TEST: không đưa profile tạm vào thư viện chung để tránh lookup nhầm biên dạng.
        return profile
      end

      # Fallback: nếu SKP không có Face đầu kín thì mới cắt model tại 25%, 50%, 75%.
      candidates=[]
      [0.25,0.50,0.75].each do |ratio|
        cut=mins[long_i]+spans[long_i]*ratio
        segs=[]
        faces.each do |face,tr|
          begin
            segs.concat(section_segments_for_face(face,tr,long_i,cut,eps))
          rescue
          end
        end
        # Khử các đoạn trùng do hình học lồng/face đồng vị trí.
        uniq={}
        segs.each do |a,b|
          ka=point_key(a,0.01.mm); kb=point_key(b,0.01.mm); key=[ka,kb].sort
          uniq[key]=[a,b]
        end
        stitch_all_boundary_loops(uniq.values).each do |loop3|
          next if loop3.length<3
          pts2=project_axis_points(loop3,long_i)
          xs=pts2.map{|q|q[0]}; ys=pts2.map{|q|q[1]}
          w=(xs.max-xs.min).abs; h=(ys.max-ys.min).abs
          next if w<=0.01.mm || h<=0.01.mm
          # Ưu tiên vòng kín chi tiết, tránh khung chữ nhật đơn giản.
          area_box=w*h
          score=pts2.length*1_000_000.0 + area_box.to_f - (pts2.length<=4 ? 100_000_000.0 : 0)
          candidates << [score,pts2,"Tiết diện cắt #{(ratio*100).round}%"]
        end
      end
      if candidates.empty?
        # V4.7 fallback: file SKP dạng surface/group hở không thể tạo section kín tự động.
        # Đưa model vào bản vẽ để người dùng chọn chính xác Face rồi dùng ADD Face làm biên dạng.
        inst = model.active_entities.add_instance(definition, Geom::Transformation.new)
        model.selection.clear
        model.selection.add(inst)
        model.active_view.zoom(inst) rescue nil
        UI.messagebox("File SKP này không tạo được vòng tiết diện kín tự động.\n\nV4.7 đã đưa model vào bản vẽ. Hãy mở Group/Component, chọn đúng Face mặt cắt cần dùng, rồi bấm nút '+ ADD Face làm biên dạng'.\n\nCách này dùng được cả model lam/phào không phải Solid.")
        return nil
      end
      # Bỏ ứng viên trùng hình học theo số đỉnh + kích thước.
      seen={}; candidates.sort_by!{|x|-x[0]}
      top=[]
      candidates.each do |row|
        pts=row[1]; xs=pts.map{|q|q[0]}; ys=pts.map{|q|q[1]}
        key=[pts.length,((xs.max-xs.min).to_mm*10).round,((ys.max-ys.min).to_mm*10).round]
        next if seen[key]; seen[key]=true; top << row; break if top.length>=8
      end
      labels=top.each_with_index.map do |row,i|
        pts=row[1]; xs=pts.map{|q|q[0]}; ys=pts.map{|q|q[1]}
        "#{i+1}: #{row[2]} — #{pts.length} đỉnh — #{(xs.max-xs.min).to_mm.round(1)} x #{(ys.max-ys.min).to_mm.round(1)} mm"
      end
      pick=0
      if top.length>1
        result=UI.inputbox(['Chọn tiết diện đúng:'],[labels[0]],[labels.join('|')],'V4.7 - Chọn vòng kín tiết diện SKP')
        return nil unless result
        pick=labels.index(result[0]) || 0
      end
      pts2=top[pick][1]
      profile=profile_from_points(pts2,File.basename(path,'.*'))
      xs=pts2.map{|q|q[0]}; ys=pts2.map{|q|q[1]}
      profile['nominal_width']=[(xs.max-xs.min).abs,(ys.max-ys.min).abs].max.to_mm.round(2)
      profile['source_type']='SKP_SECTION_V45_CLOSED_LOOP'
      profile['source_file']=File.basename(path)
      profile['detected_vertices']=pts2.length
      # V202 TEST: không đưa profile tạm vào thư viện chung để tránh lookup nhầm biên dạng.
      profile
    end

    # V5.9.5: nạp chính file TES3 người dùng cung cấp, không dùng biên dạng lam giả lập.
    def self.load_bundled_tes3_lam
      model = Sketchup.active_model
      path = File.join(File.dirname(__FILE__), 'library', 'tes3_lam_song.skp')
      unless File.exist?(path)
        UI.messagebox('Không tìm thấy thư viện TES3 đi kèm plugin.')
        return
      end
      definition = v311_load_source(path)
      inst = model.active_entities.add_instance(definition, Geom::Transformation.new)
      old_sel = model.selection.to_a
      model.selection.clear
      model.selection.add(inst)
      begin
        p = add_exact_lam_from_selection({'name'=>'Lam sóng TES3 - biên dạng gốc 1:1','lam_count'=>1})
        if p
          p['source_type']='BUNDLED_TES3_EXACT_SKP'
          p['source_file']='tes3_lam_song.skp'
          save_user_profiles
          refresh_dialog_profiles
        end
      ensure
        inst.erase! if inst && inst.valid?
        model.selection.clear
        old_sel.each { |e| model.selection.add(e) if e.respond_to?(:valid?) && e.valid? }
      end
    rescue => e
      UI.messagebox("Không nạp được Lam TES3 1:1:\n#{e.class}: #{e.message}")
    end

    def self.import_profile_file
      path=UI.openpanel('Chọn file biên dạng', '', 'Biên dạng|*.skp;*.dwg;*.dxf;*.json;*.csv;*.txt||')
      return unless path
      ext=File.extname(path).downcase; added=[]
      if ext=='.skp'
        p = import_skp_profile(path); added << p if p
      elsif ['.dwg','.dxf'].include?(ext)
        begin
          added << import_cad_via_sketchup(path)
        rescue => cad_error
          if ext=='.dxf'
            pts=parse_ascii_dxf(path)
            raise cad_error unless pts && pts.length>=3
            profile=profile_from_points(pts, File.basename(path,'.*'))
            # V202 TEST: không đưa profile tạm vào thư viện chung để tránh lookup nhầm biên dạng.
            added << profile
          else
            raise cad_error
          end
        end
      elsif ext=='.json'
        data=JSON.parse(File.read(path, :encoding => 'UTF-8')); data=[data] if data.is_a?(Hash)
        data.each do |p|
          pts=p['points'] || p[:points]; next unless pts.is_a?(Array) && pts.length>=3
          profile=profile_from_points(pts, (p['name'] || File.basename(path,'.*')).to_s, (p['nominal_width'] || 0))
          profile['category']=(p['category'] || 'Mẫu ngoài').to_s
          profiles << profile; added << profile
        end
      elsif ['.csv','.txt'].include?(ext)
        rows=CSV.read(path).map { |r| [r[0].to_f,r[1].to_f] }
        raise 'CSV/TXT cần tối thiểu 3 dòng tọa độ X,Y.' if rows.length<3
        profile=profile_from_points(rows, File.basename(path,'.*'))
        profiles << profile; added << profile
      else
        raise 'Định dạng chưa hỗ trợ.'
      end
      save_user_profiles; refresh_dialog_profiles
      UI.messagebox("Đã thêm #{added.compact.length} biên dạng vào thư viện Mẫu ngoài.")
    rescue => e
      UI.messagebox("Không thêm được biên dạng:\n#{e.class}: #{e.message}")
    end

    def self.delete_user_profile(id)
      p = profiles.find { |x| x['id'].to_s == id.to_s && x['user_added'] }
      return UI.messagebox('Chỉ có thể xóa mẫu ngoài do người dùng thêm.') unless p
      profiles.delete(p)
      # V202 TEST: dùng trực tiếp contour đã gán của đúng file SKP, không save/reload qua thư viện chung.
    end

    def self.clear_user_profiles
      users = profiles.select { |x| x['user_added'] }
      return UI.messagebox('Kho Mẫu ngoài đang trống.') if users.empty?
      result = UI.messagebox("Xóa toàn bộ #{users.length} mẫu ngoài?", MB_YESNO)
      return unless result == IDYES
      profiles.delete_if { |x| x['user_added'] }
      # V202 TEST: dùng trực tiếp contour đã gán của đúng file SKP, không save/reload qua thư viện chung.
    end

    # V5.9.9.200: Nối bề mặt có MAP / bỏ line / giữ nguyên tỉ lệ texture.
    # Sau khi explode, các Group kề nhau thường tạo HAI cạnh trùng nhau, mỗi cạnh chỉ có
    # một Face. Vì vậy chỉ kiểm tra edge.faces.length == 2 sẽ không bao giờ thấy đường nối.
    def self.merge_coplanar_surfaces
      model = Sketchup.active_model
      sel = model.selection
      plane_tol  = 0.5.mm
      point_tol  = 0.25.mm
      normal_tol = 1.0e-4

      same_plane_faces = lambda do |f1, f2|
        next false unless f1 && f2 && f1.valid? && f2.valid?
        n1 = f1.normal.clone; n2 = f2.normal.clone
        next false if n1.length == 0 || n2.length == 0
        n1.normalize!; n2.normalize!
        next false unless (1.0 - n1.dot(n2).abs) <= normal_tol
        p1 = f1.plane
        f2.vertices.all? { |v| v.position.distance_to_plane(p1).abs <= plane_tol }
      end

      coplanar_edge = lambda do |edge|
        next false unless edge && edge.valid? && edge.faces.length == 2
        same_plane_faces.call(edge.faces[0], edge.faces[1])
      end

      containers = sel.to_a.select { |o| o.is_a?(Sketchup::Group) || o.is_a?(Sketchup::ComponentInstance) }

      if containers.length >= 2
        model.start_operation('LOFIHOME - Bỏ Line GIỮ NGUYÊN MAP', true)
        begin
          # Component có thể dùng chung definition. Make unique trước khi ẩn cạnh để
          # không làm thay đổi các instance khác không được chọn.
          containers.each do |obj|
            obj.make_unique if obj.is_a?(Sketchup::ComponentInstance) && obj.respond_to?(:make_unique)
          end

          edge_rows = []
          containers.each do |obj|
            next unless obj.valid?
            tr = obj.transformation
            ents0 = obj.is_a?(Sketchup::Group) ? obj.entities : Compat.definition(obj).entities
            ents0.grep(Sketchup::Edge).each do |e|
              next unless e.valid? && e.faces.length == 1
              a = e.start.position.transform(tr)
              b = e.end.position.transform(tr)
              next if a.distance(b) <= point_tol
              edge_rows << [e, e.faces[0], tr, obj, a, b]
            end
          end

          world_coplanar = lambda do |f1, tr1, f2, tr2|
            p1 = f1.vertices[0].position.transform(tr1)
            p2 = f2.vertices[0].position.transform(tr2)
            n1 = f1.normal.transform(tr1); n2 = f2.normal.transform(tr2)
            next false if n1.length == 0 || n2.length == 0
            n1.normalize!; n2.normalize!
            next false unless (1.0 - n1.dot(n2).abs) <= normal_tol
            (p2 - p1).dot(n1).abs <= plane_tol
          end

          # Hai cạnh không cần có đúng cùng hai đầu mút. Chỉ cần cùng một đường thẳng
          # và có đoạn chồng nhau. Điều này xử lý trường hợp một Group chia cạnh thành
          # nhiều đoạn nhỏ còn Group kia có một cạnh dài.
          overlap_collinear = lambda do |a1, b1, a2, b2|
            d1 = b1 - a1; d2 = b2 - a2
            l1 = d1.length; l2 = d2.length
            next false if l1 <= point_tol || l2 <= point_tol
            u1 = d1.clone; u2 = d2.clone; u1.normalize!; u2.normalize!
            next false unless (1.0 - u1.dot(u2).abs) <= normal_tol
            next false if a2.distance_to_line([a1, d1]) > point_tol
            next false if b2.distance_to_line([a1, d1]) > point_tol
            t2a = (a2 - a1).dot(u1); t2b = (b2 - a1).dot(u1)
            lo = [0.0, [t2a,t2b].min].max
            hi = [l1,  [t2a,t2b].max].min
            (hi - lo) > point_tol
          end

          touched = {}
          pairs = 0
          edge_rows.each_with_index do |r1, i|
            e1,f1,tr1,o1,a1,b1 = r1
            ((i+1)...edge_rows.length).each do |j|
              e2,f2,tr2,o2,a2,b2 = edge_rows[j]
              next if o1.equal?(o2)
              next unless world_coplanar.call(f1,tr1,f2,tr2)
              next unless overlap_collinear.call(a1,b1,a2,b2)
              pairs += 1
              [e1,e2].each do |e|
                next if touched[e.object_id] || !e.valid?
                e.hidden = true
                e.soft = true if e.respond_to?(:soft=)
                e.smooth = true if e.respond_to?(:smooth=)
                touched[e.object_id] = true
              end
            end
          end

          # TUYỆT ĐỐI KHÔNG CAN THIỆP MAP/UV.
          # Chỉ ẩn/soften/smooth các cạnh tiếp giáp giữa các Group/Component.
          # Không explode, không tạo lại Face, không position_material, không đổi material.
          # Vì vậy texture của từng tấm trước và sau thao tác được giữ nguyên.
          aligned = 0

          model.commit_operation
          model.active_view.invalidate
          if touched.length > 0
            UI.messagebox("Đã bỏ đường Line tiếp giáp giữa #{containers.length} Group/Component.\n\nGIỮ NGUYÊN MAP/UV tuyệt đối; không căn pha, không scale/rotate, không Explode, không tạo lại Face.")
          else
            UI.messagebox("Chưa tìm thấy cạnh tiếp giáp để bỏ.\n\nV5.9.9.200 kiểm tra cạnh biên đồng phẳng và chồng nhau giữa các Group/Component đã chọn; MAP/UV không bị can thiệp.")
          end
          return
        rescue => e
          model.abort_operation
          UI.messagebox("Lỗi nối nhiều Group \n#{e.class}: #{e.message}")
          return
        end
      end

      jobs = []
      faces = sel.grep(Sketchup::Face)
      direct_edges = sel.grep(Sketchup::Edge)
      candidates = direct_edges.dup
      faces.each { |f| candidates.concat(f.edges) }
      candidates.uniq!
      current = candidates.select do |e|
        next false unless coplanar_edge.call(e)
        faces.any? && !direct_edges.include?(e) ? e.faces.all? { |f| faces.include?(f) } : true
      end
      jobs << [model.active_entities, current] unless current.empty?

      seen_defs = {}
      containers.each do |obj|
        ents0 = obj.is_a?(Sketchup::Group) ? obj.entities : Compat.definition(obj).entities
        key = obj.is_a?(Sketchup::Group) ? obj.object_id : Compat.definition(obj).object_id
        next unless ents0 && !seen_defs[key]
        seen_defs[key] = true
        edges = ents0.grep(Sketchup::Edge).select { |e| coplanar_edge.call(e) }
        jobs << [ents0, edges] unless edges.empty?
      end

      total = jobs.inject(0) { |sum, pair| sum + pair[1].length }
      if total == 0
        UI.messagebox("Không tìm thấy Line có thể bỏ.\n\n\n• Chọn Line giữa 2 mặt; hoặc\n• Chọn các Face; hoặc\n• Giữ Ctrl chọn từ 2 Group/Component trở lên.")
        return
      end

      model.start_operation('LOFIHOME - Nối bề mặt giữ MAP', true)
      begin
        count = 0
        jobs.each do |_ents, edges|
          edges.each do |edge|
            next unless edge.valid? && coplanar_edge.call(edge)
            # KHÔNG erase cạnh đồng phẳng. erase! làm SketchUp
            # gộp/tạo lại Face và có thể tính lại UV, khiến MAP bị nhảy.
            # Chỉ ẩn + soften/smooth cạnh để đường Line biến mất nhưng Face/UV
            # gốc vẫn tồn tại nguyên vẹn.
            edge.hidden = true
            edge.soft = true if edge.respond_to?(:soft=)
            edge.smooth = true if edge.respond_to?(:smooth=)
            count += 1
          end
        end
        model.commit_operation
        model.active_view.invalidate
        UI.messagebox("Đã ẩn #{count} đường Line đồng phẳng và GIỮ NGUYÊN MAP/UV.\n\nkhông erase Face/Edge, không tạo lại Face.")
      rescue => e
        model.abort_operation
        UI.messagebox("Lỗi nối bề mặt \n#{e.class}: #{e.message}")
      end
    end


    # Explode Group/Component nhưng khóa texture theo UV trước khi explode.
    # Mỗi Face lưu 3 cặp điểm hình học + UVQ; sau explode áp lại mapping lên Face tương ứng.
    def self.explode_keep_map
      model = Sketchup.active_model
      sel = model.selection
      objs = sel.to_a.select { |o| o.is_a?(Sketchup::Group) || o.is_a?(Sketchup::ComponentInstance) }
      if objs.empty?
        UI.messagebox("Hãy chọn ít nhất 1 Group/Component rồi bấm EXPLODE GIỮ MAP.")
        return
      end

      model.start_operation('LOFIHOME - Explode GIỮ MAP', true)
      begin
        restored = 0
        exploded = 0
        objs.each do |obj|
          next unless obj.valid?
          obj.make_unique if obj.is_a?(Sketchup::ComponentInstance) && obj.respond_to?(:make_unique)
          tr = obj.transformation
          ents0 = obj.is_a?(Sketchup::Group) ? obj.entities : Compat.definition(obj).entities
          snapshots = []

          ents0.grep(Sketchup::Face).each do |face|
            next unless face.valid?
            verts = face.outer_loop.vertices.map(&:position)
            next if verts.length < 3

            # Chọn 3 đỉnh không thẳng hàng để khóa đầy đủ scale / rotation / offset của texture.
            ids = nil
            (1...(verts.length-1)).each do |i|
              v1 = verts[i] - verts[0]
              ((i+1)...verts.length).each do |j|
                v2 = verts[j] - verts[0]
                if v1.cross(v2).length > 1.0e-8
                  ids = [0, i, j]
                  break
                end
              end
              break if ids
            end
            next unless ids

            front_mat = face.material || obj.material
            back_mat  = face.back_material
            uv_front = nil
            uv_back  = nil

            if front_mat && front_mat.texture && face.material
              tw = Sketchup.create_texture_writer
              helper = face.get_UVHelper(true, false, tw)
              uv_front = ids.map do |i|
                q = helper.get_front_UVQ(verts[i])
                Geom::Point3d.new(q.x / q.z, q.y / q.z, 1.0)
              end
            end
            if back_mat && back_mat.texture
              tw = Sketchup.create_texture_writer
              helper = face.get_UVHelper(false, true, tw)
              uv_back = ids.map do |i|
                q = helper.get_back_UVQ(verts[i])
                Geom::Point3d.new(q.x / q.z, q.y / q.z, 1.0)
              end
            end

            wpts = ids.map { |i| verts[i].transform(tr) }
            all_world = verts.map { |pt| pt.transform(tr) }
            center = Geom::Point3d.new(
              all_world.inject(0.0){|a,p|a+p.x}/all_world.length,
              all_world.inject(0.0){|a,p|a+p.y}/all_world.length,
              all_world.inject(0.0){|a,p|a+p.z}/all_world.length
            )
            snapshots << {
              :center => center,
              :area => face.area(tr),
              :front_mat => front_mat,
              :back_mat => back_mat,
              :wpts => wpts,
              :uv_front => uv_front,
              :uv_back => uv_back
            }
          end

          created = obj.explode
          exploded += 1
          new_faces = Array(created).grep(Sketchup::Face).select(&:valid?)

          snapshots.each do |snap|
            # Tìm Face sau explode theo tâm + diện tích. Đây là phép ghép ổn định với Group phẳng.
            target = new_faces.min_by do |f|
              vs = f.outer_loop.vertices.map(&:position)
              c = Geom::Point3d.new(
                vs.inject(0.0){|a,p|a+p.x}/vs.length,
                vs.inject(0.0){|a,p|a+p.y}/vs.length,
                vs.inject(0.0){|a,p|a+p.z}/vs.length
              )
              c.distance(snap[:center]) + (f.area - snap[:area]).abs * 0.001
            end
            next unless target && target.valid?

            if snap[:front_mat]
              target.material = snap[:front_mat]
              if snap[:uv_front] && snap[:front_mat].texture
                pairs = []
                3.times { |i| pairs << snap[:wpts][i] << snap[:uv_front][i] }
                target.position_material(snap[:front_mat], pairs, true)
              end
            end
            if snap[:back_mat]
              target.back_material = snap[:back_mat]
              if snap[:uv_back] && snap[:back_mat].texture
                pairs = []
                3.times { |i| pairs << snap[:wpts][i] << snap[:uv_back][i] }
                target.position_material(snap[:back_mat], pairs, false)
              end
            end
            restored += 1
          end
        end
        model.commit_operation
        model.active_view.invalidate
        UI.messagebox("Đã Explode #{exploded} Group/Component và phục hồi MAP/UV cho #{restored} Face.\n\nDùng nút EXPLODE GIỮ MAP thay cho lệnh Explode mặc định khi cần giữ nguyên hoa văn.")
      rescue => e
        model.abort_operation
        UI.messagebox("Lỗi EXPLODE GIỮ MAP \n#{e.class}: #{e.message}")
      end
    end

    def self.show_cnc_dialog(custom_outline=false)
      @cnc_custom_pending = true if custom_outline
      if @cnc_window && @cnc_window.visible?
        @cnc_window.bring_to_front
        @cnc_window.execute_script('window.LofiCNCWindow && window.LofiCNCWindow.fit(false);')
        if @cnc_custom_pending && @cnc_panel_ready
          cnc_reply({'type'=>'open_custom_outline'})
          @cnc_custom_pending = false
        end
        return
      end
      dialog = Compat.dialog(
        :dialog_title => 'Vách CNC LOFIHOME',
        :preferences_key => 'lofihome_cnc_independent',
        :scrollable => true,
        :resizable => true,
        :width => 1160,
        :height => 850,
        :min_width => 240,
        :min_height => 180,
        :style => 0
      )
      @cnc_panel_ready = false
      cnc_register_callbacks(dialog)
      cnc_register_window_fit(dialog)
      dialog.set_file(File.join(File.dirname(__FILE__), 'html', 'cnc', 'index.html'))
      dialog.set_on_closed { @cnc_window = nil if @cnc_window.equal?(dialog) }
      @cnc_window = dialog
      dialog.show
    rescue StandardError, LoadError => error
      dialog.close if dialog rescue nil
      @cnc_window = nil if @cnc_window.equal?(dialog)
      UI.messagebox("Không mở được Vách CNC:\n#{error.message}")
    end

    def self.show_dialog(open_saved_library = false)
      @dialog_library_ready = false
      @dialog = Compat.dialog(
        :dialog_title => 'LOFIHOME ĐT 0398 228 229',
        :preferences_key => 'lvn_phao_chi_v31717_compact',
        :scrollable => true,
        :resizable => true,
        :width => 680,
        :height => 640,
        :style => 0
      )
      shown_dialog = @dialog
      @dialog.set_file(HTML_FILE)
      register_saved_model_callbacks(@dialog)
      @dialog.add_action_callback('dc_library_folder') { |_, _| dc_choose_folder }
      @dialog.add_action_callback('dc_library_thumbnails') { |_, payload| dc_thumbnails(payload) }
      @dialog.add_action_callback('dc_library_browser') { |_, _| dc_show_library }
      @dialog.add_action_callback('clean_selected_ornament') { |_, _| clean_selected_ornament }
      @dialog.add_action_callback('paint_uniform_selection') { |_, _| paint_uniform_selection }
      @dialog.add_action_callback('dc_library_refresh') do |_, _|
        load File.join(File.dirname(__FILE__),'dynamic_component_library.rb')
        dc_reply('Đã tải lại thư viện từ ổ đĩa.')
      end
