      @dialog.add_action_callback('import_profile_file') { |d, _payload| import_profile_file }
      @dialog.add_action_callback('import_external_model') { |d, _payload| import_external_model_to_library }
      @dialog.add_action_callback('import_external_folder') { |d, _payload| import_external_folder_to_library }
      @dialog.add_action_callback('insert_external_model') { |d, _payload| insert_external_model_from_library }
      @dialog.add_action_callback('load_bundled_tes3_lam') { |d, _| load_bundled_tes3_lam }
      @dialog.add_action_callback('delete_user_profile') { |d, id| delete_user_profile(id) }
      @dialog.add_action_callback('clear_user_profiles') { |d, _| clear_user_profiles }
