          if updated.is_a?(Sketchup::Group) && (updated.get_attribute('PhaoChiEdit','lam_face_capture',nil) || updated.get_attribute('PhaoChiEdit','tes3_control_capture',nil))
            lam_control_dialog.execute_script("applyFinishedLam(#{JSON.generate(updated.get_attribute('PhaoChiEdit','tes3_control_capture',nil) ? Tes3Controls.read(updated) : LamMeasure.read(updated))})")
          end
        rescue => e
