      @dialog.add_action_callback('measure_map_two_points') { |d, _payload| start_map_2pt_calibration }
      @dialog.add_action_callback('apply_map_keep_scale') { |d, _payload| apply_map_keep_scale }
      @dialog.add_action_callback('diagnose_map_scale') { |d, _payload| diagnose_map_scale }
      @dialog.add_action_callback('rotate_map') { |d, payload| rotate_map_selected(payload.to_s) }
      @dialog.add_action_callback('align_map_to_lam_direction') { |_, _| align_map_to_lam_direction }
      @dialog.add_action_callback('align_map_miter_45') { |d, _payload| align_map_miter_45 }
      @dialog.add_action_callback('library_ready') do |d, _payload|
        next unless @dialog.equal?(shown_dialog)
        next if @dialog_library_ready
        @dialog_library_ready = true
        begin
          refresh_dialog_profiles
          @dialog.execute_script("document.getElementById('cat').value='Lam sóng'; render(); selectProfile('LAM_VIEN_TES3');")
          if open_saved_library
            open_saved_library = false
            show_external_model_gallery
          end
        rescue => e
          UI.messagebox("Lỗi nạp thư viện Lam TES3:\n#{e.class}: #{e.message}")
        end
      end
      @dialog.show
    end


    # V5.9: phủ lam theo đúng kích thước Face đã chọn (ưu tiên Face 4 cạnh hình chữ nhật).
    # Không thay đổi kích thước Face; chỉ lấy chính các cạnh Face làm giới hạn tấm lam.
    # V5.9.9: nếu Face là một vành có cạnh ngoài + cạnh trong, tự lấy đúng bề rộng
    # của vành rồi tạo lam vuông góc theo từng cạnh. Đây là kiểu TES3 người dùng yêu cầu.
    def self.run_face_lam_fit(face, options)
      return run_tes3_surface(face,options) if Tes3Surface.eligible?(face,options)
      inner_loops = face.loops.reject(&:outer?)
      if inner_loops.any?
        outer = face.outer_loop
        ov = outer.vertices.map(&:position)
        # Khoảng cách nhỏ nhất từ đỉnh loop trong tới các đường cạnh ngoài = bề rộng vành.
        widths = []
        inner_loops.each do |lp|
          lp.vertices.each do |vv|
            p = vv.position
            outer.edges.each do |e|
              a = e.start.position
              d = e.end.position - a
              next if d.length < 1e-9
              widths << p.distance_to_line([a, d])
            end
          end
        end
        w = widths.select { |x| x > 0.01.mm }.min
        if w && w > 0.1.mm
          opts = options.dup
          opts['width'] = w.to_mm
          return run_face_lam_auto(face, outer, opts)
        end
      end
      # V5.9.9: Face đặc KHÔNG được phủ lam tự do trong lòng.
      # Chỉ tạo một dải lam bám theo viền của chính Face đã chọn.
      # Bề rộng dải lấy từ ô Rộng; các nan luôn vuông góc từng cạnh và miter 45° ở góc.
      run_face_lam_auto(face, face.outer_loop, options)
    end

    # Phủ lam cho Face đặc 4 cạnh (giữ tương thích chức năng cũ).
    def self.run_face_lam_fill(face, options)
      return run_lam_face_fill([face],options) if options['id'].to_s=='LAM001'
      return run_round_lam_fill(face,options) if LamRound.enabled?(options)
      model = Sketchup.active_model
      verts = face.outer_loop.vertices.map(&:position)
      return run_face_lam_auto(face, face.outer_loop, options) unless verts.length == 4
      normal = face.normal.clone; normal.normalize!
      base_h = [options['lam_depth'].to_f, 0.5].max.mm
      rib_h  = [options['lam_height'].to_f, 0.5].max.mm
      count  = [[options['lam_count'].to_i, 1].max, 200].min
      edges = 4.times.map { |i| [i, verts[i].distance(verts[(i+1)%4])] }
      i0 = edges.max_by{|x| x[1]}[0]
      o = verts[i0]; u = verts[(i0+1)%4] - o; ulen=u.length; u.normalize!
      v = normal.cross(u); v.normalize!
      mid=o.offset(u, ulen*0.5); inside=[Sketchup::Face::PointInside,Sketchup::Face::PointOnFace,Sketchup::Face::PointOnEdge]
      v.reverse! unless inside.include?(face.classify_point(mid.offset(v,1.mm)))
      proj=verts.map{|pt| (pt-o).dot(v)}; vlen=(proj.max-proj.min).abs
      model.start_operation('Lam phủ kín Face', true)
      begin
        group=model.active_entities.add_group; group.name='Lam phủ kín Face - chỉnh sửa được'
        group.set_attribute('PhaoChiEdit','kind','face_fit'); group.set_attribute('PhaoChiEdit','options',JSON.generate(options)); group.set_attribute('PhaoChiEdit','face_pid',Compat.entity_id(face))
        ents=group.entities; bf=ents.add_face(verts); if bf; bf.reverse! if bf.normal.dot(normal)<0; bf.pushpull(base_h); end
        pitch=vlen/count.to_f; rib_t=pitch*0.58
        count.times do |j|
          lo=[(j+0.5)*pitch-rib_t*0.5,0].max; hi=[(j+0.5)*pitch+rib_t*0.5,vlen].min
          a=o.offset(v,lo); b=o.offset(v,hi); c=b.offset(u,ulen); d=a.offset(u,ulen)
          rf=ents.add_face(a,b,c,d); next unless rf; rf.reverse! if rf.normal.dot(normal)<0; rf.pushpull(base_h+rib_h)
        end
        apply_lam_edge_display(ents,[u],options)
        model.commit_operation
      rescue => e
        model.abort_operation; UI.messagebox("Lỗi tạo lam phủ Face:\n#{e.class}: #{e.message}")
      end
    end

    # V5.9: Lam tự xoay theo từng cạnh + đế nối miter tại các góc.
    # Đường biên ngoài giữ nguyên tại vertex của loop; đường biên trong được tạo
    # bằng giao điểm của hai đường offset kế cận. Với góc 90°, cạnh đầu đế là 45°.
    def self.run_face_lam_auto(face, loop, options)
      model = Sketchup.active_model
      return run_tes3_surface(face,options) if loop.outer? && Tes3Surface.eligible?(face,options)
      if Tes3Fit.enabled?(options) && loop.outer?
        plan=Tes3Fit.plan(loop.vertices.map { |v|v.position.to_a.map { |n|n*25.4 } },
          face.normal.to_a,[options['width'].to_f,1.0].max,[[options['lam_count'].to_i,1].max,200].min)
        return run_tes3_rect_fit(face,loop,options,plan) if plan
      end
      width = [options['width'].to_f, 1.0].max.mm
      base_h = [options['lam_depth'].to_f, 0.5].max.mm
      rib_h = [options['lam_height'].to_f, 0.5].max.mm
      count = [[options['lam_count'].to_i, 1].max, 200].min
      normal = face.normal.clone
      normal.normalize!
      pitch = width / count.to_f
      rib_t = pitch * 0.58

      verts = loop.vertices.map(&:position)
      if verts.length < 3
        UI.messagebox('Đường viền không đủ đỉnh để tạo lam.')
        return
      end

      # Tính hướng cạnh và hướng vào trong cho từng cạnh theo đúng thứ tự loop.
      dirs = []
      inwards = []
      nverts = verts.length
      inside_vals = [Sketchup::Face::PointInside, Sketchup::Face::PointOnFace, Sketchup::Face::PointOnEdge]
      nverts.times do |i|
        a = verts[i]
        b = verts[(i + 1) % nverts]
        d = b - a
        next if d.length < 0.001.mm
        d.normalize!
        inn = normal.cross(d)
        inn.normalize!
        mid = Geom.linear_combination(0.5, a, 0.5, b)
        test = mid.offset(inn, [width * 0.25, 1.mm].max)
        inn.reverse! unless inside_vals.include?(face.classify_point(test))
        dirs[i] = d
        inwards[i] = inn
      end

      # Giao điểm hai đường offset tại mỗi góc = điểm miter phía trong.
      inner_corner = Array.new(nverts)
      nverts.times do |i|
        prev = (i - 1) % nverts
        cur = i
        v = verts[i]
        if dirs[prev] && dirs[cur] && inwards[prev] && inwards[cur]
          l1 = [v.offset(inwards[prev], width), dirs[prev]]
          l2 = [v.offset(inwards[cur], width), dirs[cur]]
          ip = Geom.intersect_line_line(l1, l2)
          # Góc lõm hoặc gần song song có thể cho giao điểm quá xa; fallback offset trung bình.
          if ip.nil? || ip.distance(v) > width * 20.0
            avg = inwards[prev] + inwards[cur]
            if avg.length > 1e-9
              avg.normalize!
              denom = [avg.dot(inwards[cur]).abs, 0.15].max
              ip = v.offset(avg, width / denom)
            else
              ip = v.offset(inwards[cur], width)
            end
          end
          inner_corner[i] = ip
        else
          inner_corner[i] = v
        end
      end

      own_operation=!options['_lam_outer_operation']
      model.start_operation('Lam tự xoay theo viền - góc miter', true) if own_operation
      begin
        group = model.active_entities.add_group
        group.name = 'Lam tự xoay theo viền - chỉnh sửa được'
        group.set_attribute('PhaoChiEdit','kind','face_auto')
        group.set_attribute('PhaoChiEdit','options',JSON.generate(options.reject { |k,_|k=='_lam_outer_operation' }))
        group.set_attribute('PhaoChiEdit','face_pid',Compat.entity_id(face))
        group.set_attribute('PhaoChiEdit','loop_outer',loop.outer? ? 1 : 0)
        ents = group.entities

        nverts.times do |i|
          a = verts[i]
          b = verts[(i + 1) % nverts]
          dir = dirs[i]
          inward = inwards[i]
          next unless dir && inward
          len = a.distance(b)
          next if len < 0.1.mm

          # V5.9.9.200: TES3 được tách thành từng KHỐI CẠNH độc lập.
          # Với khung 4 cạnh, Group cha chứa đúng 4 Group con theo 4 đường miter 45°.
          # Mỗi khối con chứa toàn bộ đế + nan của chính cạnh đó; không chồng hình học
          # sang cạnh kế bên. Nhờ vậy có thể chọn/map/xử lý từng cạnh độc lập.
          if options['id'].to_s=='LAM_VIEN_TES3'
            side_grp,base_part,rib_part=Tes3Parts.side(ents,i)
            base_parent=base_part.entities
            side_ents=rib_part.entities
          else
            side_grp = ents.add_group
            side_grp.name = "TES3_SIDE_#{i + 1}"
            base_parent=side_grp.entities
            side_ents=side_grp.entities
          end
          side_grp.set_attribute('PhaoChiTES3','side_index',i)
          side_grp.set_attribute('PhaoChiTES3','miter_split',45)

          # Đế từng cạnh dùng chính hai điểm miter trong ở hai đầu.
          # Ở góc 90° cạnh nối outer->inner là đường chéo 45° và hai đế khít nhau.
          p1 = a
          p2 = b
          p3 = inner_corner[(i + 1) % nverts]
          p4 = inner_corner[i]
          # V5.9.9.200: dựng ĐẾ TES3 thành lăng trụ kín 6 mặt ngay từ đầu.
          # Không dùng pushpull chung topo giữa các cạnh vì tại miter SketchUp có thể
          # nhập/xóa mặt đứng và sinh khe hở hoặc tam giác thừa. Mỗi cạnh là một solid
          # con độc lập; hai solid chỉ tiếp xúc đúng trên mặt miter 45°.
          base_grp = base_parent.add_group
          base_grp.name = 'TES3_BASE_SOLID'
          be = base_grp.entities
          zvec = normal.clone
          zvec.length = base_h
          q1 = p1.offset(zvec); q2 = p2.offset(zvec)
          q3 = p3.offset(zvec); q4 = p4.offset(zvec)
          faces6 = [
            [p1,p2,p3,p4], [q4,q3,q2,q1],
            [p1,q1,q2,p2], [p2,q2,q3,p3],
            [p3,q3,q4,p4], [p4,q4,q1,p1]
          ]
          faces6.each do |fp|
            begin
              f = be.add_face(fp)
              next unless f
              # Hướng mặt không ảnh hưởng độ kín; orient_consistently sẽ xử lý sau.
            rescue
            end
          end
          begin
            fs = be.grep(Sketchup::Face)
            fs.first.orient_faces if fs.first
          rescue
          end

          # V5.9.9: nan được CẮT theo chính polygon miter của đế.
          # Nhờ vậy tại góc 90°, nan cuối có đầu chéo 45° giống TES3, không chồng và không thiếu sóng.
          to_xy = lambda { |pt| [(pt-a).dot(dir), (pt-a).dot(inward)] }
          from_xy = lambda { |xy| a.offset(dir,xy[0]).offset(inward,xy[1]) }
          clip_poly = [p1,p2,p3,p4].map { |pt| to_xy.call(pt) }
          # đảm bảo polygon clip ngược chiều kim đồng hồ
          area = 0.0
          clip_poly.each_with_index { |p,k| q=clip_poly[(k+1)%clip_poly.length]; area += p[0]*q[1]-q[0]*p[1] }
          clip_poly.reverse! if area < 0

          clip_one = lambda do |subject, cp1, cp2|
            out=[]
            inside_fn=lambda{|p| (cp2[0]-cp1[0])*(p[1]-cp1[1])-(cp2[1]-cp1[1])*(p[0]-cp1[0]) >= -1e-7 }
            inter_fn=lambda do |s0,e0|
              x1,y1=s0; x2,y2=e0; x3,y3=cp1; x4,y4=cp2
              den=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4)
              next e0 if den.abs < 1e-12
              t=((x1-x3)*(y3-y4)-(y1-y3)*(x3-x4))/den.to_f
              [x1+t*(x2-x1), y1+t*(y2-y1)]
            end
            prev=subject[-1]; prev_in=inside_fn.call(prev)
            subject.each do |cur|
              cur_in=inside_fn.call(cur)
              if cur_in
                out << inter_fn.call(prev,cur) unless prev_in
                out << cur
              elsif prev_in
                out << inter_fn.call(prev,cur)
              end
              prev=cur; prev_in=cur_in
            end
            out
          end

          # Giữ bước nan đều theo cạnh như ảnh mẫu; count là số lam tham chiếu theo bề rộng.
          # Pitch dọc cạnh lấy theo bề rộng nan/rãnh để hình nhìn đồng đều trên cả 4 cạnh.
          # V5.9.9 FIX GÓC: KHÔNG co giãn bước nan riêng cho từng cạnh.
          # Dùng một pitch cố định cho toàn bộ khung, rồi căn giữa phần dư trên mỗi cạnh.
          # Nhờ đó hai đầu cạnh có phần dư bằng nhau; các nan bị miter cắt ở 4 góc
          # có cùng nhịp/kích thước, không còn góc phải bị nan nhỏ hoặc lệch bước.
          # FIX8: lam của hai cạnh đấu trực tiếp tại đường miter. Không tạo thanh chéo,
          # không chừa tam giác trống ở góc. Nhịp nan giữ cố định và chạy tới sát góc;
          # chính polygon miter sẽ cắt ngắn dần các nan cuối.
          edge_pitch = [pitch, 3.mm].max
          rib_long = [edge_pitch * 0.42, 1.mm].max

          # V5.9.9.146 TES3 FIX GÓC:
          # Khóa pha nan tại CHÍNH vertex góc (cx = 0, pitch, 2*pitch...).
          # Hai cạnh gặp nhau vì vậy luôn có cùng một nửa nan tại đường miter,
          # tạo đầu đấu góc đều nhau như TES3 bản đã duyệt. Không căn pha riêng
          # theo chiều dài từng cạnh vì cách đó làm hai cạnh lệch nhịp ở góc.
          # V5.9.9.200 FIX GÓC 45°: khóa nan ở CẢ HAI đầu cạnh.
          # Mỗi cạnh chia thành số khoảng gần pitch chuẩn nhất, nhưng điểm đầu = 0
          # và điểm cuối = len luôn là tâm nan. Vì vậy tại một vertex chung, hai
          # cạnh kề đều có đúng một nửa nan bị cùng đường miter 45° cắt, hai nửa
          # trùng nhau thay vì lệch pha/bậc thang.
          # V5.9.9.200 SCALE FIX: sau khi Scale, KHÔNG kéo giãn pitch riêng từng cạnh.
          # Dùng cùng edge_pitch tính từ TES3 cho cả 4 cạnh và khóa pha từ CẢ HAI góc.
          # Phần dư kích thước sau Scale được dồn về giữa cạnh, vì vậy vùng miter 45°
          # ở hai đầu luôn có cùng nhịp nan với cạnh kề.
          if options['tes3_scale_corner_lock']
            centers = []
            half = len * 0.5
            x = 0.0
            while x <= half + 1e-7
              centers << x
              x += edge_pitch
            end
            x = len
            right = []
            while x > half + 1e-7
              right << x
              x -= edge_pitch
            end
            centers.concat(right.reverse)
            # bỏ tâm trùng do sai số số thực
            centers = centers.sort.each_with_object([]) { |v,arr| arr << v if arr.empty? || (v-arr[-1]).abs > 0.01.mm }
          else
            intervals = [(len / edge_pitch).round, 1].max
            actual_pitch = len / intervals.to_f
            centers = (0..intervals).map { |j| j * actual_pitch }
          end
          centers.each do |cx|
            subject=[[cx-rib_long*0.5,0.0],[cx+rib_long*0.5,0.0],[cx+rib_long*0.5,width],[cx-rib_long*0.5,width]]
            clipped=subject
            clip_poly.each_with_index do |cp1,k|
              cp2=clip_poly[(k+1)%clip_poly.length]
              clipped=clip_one.call(clipped,cp1,cp2)
              break if clipped.length < 3
            end
            next if clipped.length < 3
            if LamRound.enabled?(options)
              mesh=LamRound.rib_mesh((cx-rib_long*0.5)*25.4,(cx+rib_long*0.5)*25.4,base_h.to_f*25.4,(base_h+rib_h)*25.4,clip_poly.map { |xy|xy.map { |v|v*25.4 } })
              LamRound.build(side_ents,mesh,a,dir,inward,normal,'TES3_RIB_R1') unless mesh.empty?
              next
            end
            pts3=clipped.map{|xy| from_xy.call(xy)}
            rf=side_ents.add_face(pts3)
            next unless rf
            rf.reverse! if rf.normal.dot(normal) < 0
            rf.pushpull(base_h + rib_h)
          end
          apply_lam_edge_display(be,[dir],options)
          apply_lam_edge_display(side_ents,[inward],options)
        end

        # V5.9.9.200: không vá mặt miter sau khi dựng nữa.
        # Đế đã là solid kín 6 mặt theo từng cạnh, tránh tam giác thừa/khe hở.

        model.commit_operation if own_operation
        group
      rescue => e
        raise unless own_operation
        model.abort_operation if own_operation
        UI.messagebox("Lỗi tạo lam tự xoay theo viền / miter:\n#{e.class}: #{e.message}")
        nil
      end
    end

    def self.run_face_profile(options)
      return run_tes3_control(options) if defined?(Tes3Controls) && Tes3Controls.enabled?(options)
      model = Sketchup.active_model
      faces = model.selection.grep(Sketchup::Face)
      if faces.empty?
        UI.messagebox('Hãy chọn ít nhất 1 bề mặt (Face) trước.')
        return
      end
      original = model.selection.to_a
      return run_lam_face_fill(faces,options) if options['id'].to_s=='LAM001'
      mode = (options['face_boundary'] || 'outer').to_s
      loops_to_run = []
      faces.each do |face|
        case mode
        when 'inner'
          loops_to_run.concat(face.loops.reject(&:outer?))
        when 'all'
          loops_to_run.concat(face.loops)
        else
          loops_to_run << face.outer_loop
        end
      end
      if loops_to_run.empty?
        UI.messagebox('Bề mặt đã chọn không có đường viền phù hợp.')
        return
      end
      # V202: mẫu ngoài chạy Edge phải dùng đúng contour vừa đọc từ external_profiles.json.
      # Không lookup lại theo id trong thư viện vì có thể nhận nhầm/biến dạng profile.
      profile = options['_profile_override'] || profiles.find { |p| p['id'] == options['id'] }
      # FIX7: TES3 là hệ lam viền chuyên dụng, không phải profile Follow-Me.
      # Luôn bám Face/viền, tự đổi hướng theo cạnh và miter 45 độ.
      if profile && ['LAM_VIEN_TES3','LAM_VIEN_TES3_R1'].include?(profile['id'].to_s)
        options = options.dup
        options['lam_fit_face'] = true
        options['lam_auto_edge'] = true
        options['lam_depth'] = 3.0 if options['lam_depth'].to_f <= 0
        options['lam_height'] = 3.0 if options['lam_height'].to_f <= 0
        options['lam_count'] = 6 if options['lam_count'].to_i <= 0
      end
      # V5.9.9.200: LAM001 (cơ chế V5.9.2) khi chọn BỀ MẶT phải PHỦ ĐỀU TOÀN FACE
      # theo MỘT hướng. Không chạy quanh viền như TES3.
      # Số lam lấy trực tiếp từ ô Số lam; Ngang/Dọc/Góc vẫn do options điều khiển ở bước chỉnh sau.
      if profile && ['LAM001','LAM001_R1'].include?(profile['id'].to_s) && options['lam_fit_face']
        options = options.dup
        options['lam_count'] = [[options['lam_count'].to_i, 1].max, 500].min
        faces.each { |face| run_face_lam_fill(face, options) }
        return
      elsif profile && profile['category'].to_s == 'Lam sóng' && options['lam_fit_face']
        faces.each { |face| run_face_lam_fit(face, options) }
        return
      elsif profile && profile['category'].to_s == 'Lam sóng' && options['lam_auto_edge']
        loops_to_run.each { |loop| run_face_lam_auto(loop.face, loop, options) }
        return
      end
      corner_mode = (options['corner_mode'] || 'miter').to_s
      loops_to_run.each do |loop|
        if corner_mode == 'straight'
          # Nối thẳng: chạy từng cạnh độc lập, không ép FollowMe qua góc.
          loop.edges.each do |edge|
            model.selection.clear
            model.selection.add(edge)
            run_profile(options)
          end
        else
          # Miter: FollowMe trên toàn bộ loop để SketchUp tự xử lý góc liên tục.
          model.selection.clear
          loop.edges.each { |e| model.selection.add(e) }
          run_profile(options)
        end
      end
    ensure
      if model
        model.selection.clear
        original.each { |e| model.selection.add(e) if e.respond_to?(:valid?) ? e.valid? : true } if original
      end
    end

    # V4.9: làm sạch đường bao trước khi add_face để tránh
    # ArgumentError: Duplicate points in array.
    # V5.0: làm sạch điểm nhưng KHÔNG xóa các điểm trùng không-liên-tiếp,
    # vì chúng có thể là chi tiết rãnh/gờ hợp lệ của biên dạng lam.
    def self.clean_face_points(points, tolerance = 0.001.mm)
      cleaned = []
      points.each do |pt|
        next if !cleaned.empty? && cleaned.last.distance(pt) <= tolerance
        cleaned << pt
      end
      cleaned.pop if cleaned.length > 2 && cleaned.first.distance(cleaned.last) <= tolerance

      changed = true
      while changed && cleaned.length > 3
        changed = false
        out = []
        n = cleaned.length
        cleaned.each_with_index do |b, i|
          a = cleaned[(i - 1) % n]
          c = cleaned[(i + 1) % n]
          ab = b - a
          bc = c - b
          if ab.length <= tolerance || bc.length <= tolerance
            changed = true
            next
          end
          cross = ab * bc
          # Chỉ bỏ điểm thẳng hàng khi cùng hướng; không phá góc quay ngược/rãnh nhỏ.
          if cross.length <= tolerance * [ab.length, bc.length].max && ab.dot(bc) > 0
            changed = true
            next
          end
          out << b
        end
        cleaned = out if out.length >= 3
      end
      cleaned
    end

    def self.lam_wave_points(count, depth_mm, height_mm)
      count = [[count.to_i, 1].max, 200].min
      h = [height_mm.to_f, 1.0].max
      d = [[depth_mm.to_f, 0.1].max, h - 0.1].min
      y = d / h
      gap = 0.40 / (count + 1).to_f
      rib = 0.60 / count.to_f
      pts = [[0.0,0.0],[1.0,0.0],[1.0,y]]
      x = 1.0 - gap
      pts << [x,y]
      count.times do |i|
        pts << [x,1.0]
        x -= rib
        pts << [x,1.0]
        pts << [x,y]
        if i < count - 1
          x -= gap
          pts << [x,y]
        end
      end
      pts << [0.0,y]
      pts
    end

    # V194: Sắp xếp các Edge đã chọn thành một chuỗi liên tục trước khi FollowMe.
    # SketchUp selection không đảm bảo thứ tự Edge; nếu dùng trực tiếp, mặt cắt có thể
    # chỉ nằm ở đầu đường mà FollowMe không chạy hết chuỗi.
    # V214: xếp Edge thành đúng MỘT chuỗi liên tục, hỗ trợ cả đường hở và vòng kín.
    # Không phụ thuộc thứ tự Selection của SketchUp. Nếu có nhánh/rời thì báo lỗi thay vì
    # âm thầm chạy thiếu cạnh — đây là điều rất quan trọng với phào khung/miter.
    def self.ordered_edge_chain(edges)
      return [] if edges.nil? || edges.empty?
      uniq = edges.select { |e| e && e.valid? }.uniq
      by_vertex = Hash.new { |h,k| h[k] = [] }
      uniq.each do |e|
        by_vertex[e.start] << e
        by_vertex[e.end] << e
      end
      degrees = by_vertex.transform_values(&:length)
      bad = degrees.select { |_v,d| d > 2 }
      raise 'Các Edge có nhánh giao nhau. Hãy chỉ chọn một đường chạy liên tục.' unless bad.empty?
      ends = degrees.keys.select { |vertex| degrees[vertex] == 1 }
      unless ends.length == 0 || ends.length == 2
        raise 'Các Edge chưa tạo thành một chuỗi hở hoặc vòng kín hợp lệ.'
      end
      start_v = ends.first || uniq.first.start
      ordered=[]; used={}; cur_v=start_v
      loop do
        e = by_vertex[cur_v].find { |x| !used[x.object_id] }
        break unless e
        used[e.object_id]=true
        nxt = e.start.equal?(cur_v) ? e.end : e.start
        ordered << [e, cur_v.position, nxt.position]
        cur_v=nxt
        break if used.length == uniq.length
      end
      raise "Selection có #{uniq.length} Edge nhưng chỉ nối được #{used.length} Edge. Hãy kiểm tra cạnh rời/khe hở." if used.length != uniq.length
      if ends.empty? && !cur_v.equal?(start_v)
        raise 'Vòng Edge chưa khép kín hoàn toàn.'
      end
      ordered
    end

    def self.run_profile(options)
      return run_tes3_control(options) if defined?(Tes3Controls) && Tes3Controls.enabled?(options)
      model = Sketchup.active_model
      if options['id'].to_s=='LAM001' && model.selection.grep(Sketchup::Face).any?
        return run_lam_face_fill(model.selection.grep(Sketchup::Face),options)
      end
      if options['id'].to_s=='LAM001' && !options['lam_rib_width'].nil?
        count=LamFaceFill.number(options,'lam_count',3,1,200)
        raise 'Số lam phải là số nguyên.' unless count==count.to_i
        rib=LamFaceFill.number(options,'lam_rib_width',0,0.1,100000)
        options=options.merge('width'=>count*rib/0.60)
      end
      edges = model.selection.grep(Sketchup::Edge)
      if edges.empty?
        UI.messagebox('Hãy chọn ít nhất 1 Edge trước.')
        return
      end

      # V202: mẫu ngoài chạy Edge phải dùng đúng contour vừa đọc từ external_profiles.json.
      # Không lookup lại theo id trong thư viện vì có thể nhận nhầm/biến dạng profile.
      profile = options['_profile_override'] || profiles.find { |p| p['id'] == options['id'] }
      unless profile
        UI.messagebox('Không tìm thấy biên dạng.')
        return
      end

      if profile['source_type'].to_s == 'SKP_AUTO_END_FACE_EXACT'
        width = [profile['actual_width'].to_f, 0.1].max.mm
        height = [profile['actual_height'].to_f, 0.1].max.mm
      else
        minimum_width = options['id'].to_s=='LAM001' && !options['lam_rib_width'].nil? ? 0.1 : 1.0
        width = [options['width'].to_f, minimum_width].max.mm
        height = [options['height'].to_f, 1.0].max.mm
      end
      orientation = options['orientation'].to_s
      reverse_path = options['reverse_path'] ? true : false
      offset_side = options['offset_side'].to_f.mm
      offset_vertical = options['offset_vertical'].to_f.mm

      # 8 profile orientations: 4 flips plus 4 rotated/mirrored states.
      side_sign = 1.0
      vertical_sign = 1.0
      swap_axes = false
      case orientation
      when 'right_up'
        side_sign, vertical_sign = 1.0, 1.0
      when 'left_up'
        side_sign, vertical_sign = -1.0, 1.0
      when 'right_down'
        side_sign, vertical_sign = 1.0, -1.0
      when 'left_down'
        side_sign, vertical_sign = -1.0, -1.0
      when 'up_right'
        swap_axes = true
        side_sign, vertical_sign = 1.0, 1.0
      when 'up_left'
        swap_axes = true
        side_sign, vertical_sign = -1.0, 1.0
      when 'down_right'
        swap_axes = true
        side_sign, vertical_sign = 1.0, -1.0
      when 'down_left'
        swap_axes = true
        side_sign, vertical_sign = -1.0, -1.0
      end
      chain = ordered_edge_chain(edges)
      raise 'Các Edge đã chọn không tạo được chuỗi liên tục.' if chain.empty?
      if reverse_path
        chain = chain.reverse.map { |row| [row[0], row[2], row[1]] }
      end
      origin = chain.first[1]
      direction = chain.first[2] - origin
      raise 'Edge đầu tiên có chiều dài bằng 0.' if direction.length < 1.0e-9
      direction.normalize!

      zaxis = Geom::Vector3d.new(0, 0, 1)
      side = zaxis.cross(direction)
      if side.length < 0.001
        side = Geom::Vector3d.new(1, 0, 0).cross(direction)
      end
      side.normalize!
      vertical = direction.cross(side)
      vertical.normalize!
      side.length = (swap_axes ? height : width) * side_sign
      vertical.length = (swap_axes ? width : height) * vertical_sign

      origin = Geom::Point3d.new(
        origin.x + side.normalize.x * offset_side + vertical.normalize.x * offset_vertical,
        origin.y + side.normalize.y * offset_side + vertical.normalize.y * offset_vertical,
        origin.z + side.normalize.z * offset_side + vertical.normalize.z * offset_vertical
      )

      own_operation=!(LamRound.enabled?(options) && options['_lam_outer_operation'])
      model.start_operation('Tạo phào chỉ', true) if own_operation
      begin
        group = model.active_entities.add_group
        ents = group.entities

        source_points = if ['LAM001','LAM001_R1'].include?(profile['id'].to_s)
          # V5.9.9.200: LAM001 sau khi vẽ PHẢI lấy trực tiếp số lam hiện tại từ ô CHỈNH LAM.
          # Không dùng lại 3 gờ cố định của thumbnail/profile gốc.
          live_count = [[options['lam_count'].to_i, 1].max, LamRound.enabled?(options) ? 200 : 500].min
          options['lam_count'] = live_count
          lam_wave_points(live_count, options['lam_depth'] || 4, (options['lam_depth'] || 4).to_f + (options['lam_height'] || 6).to_f)
        elsif profile['category'].to_s == 'Lam sóng' && !profile['fixed_lam_profile']
          lam_wave_points(options['lam_count'] || 3, options['lam_depth'] || 4, (options['lam_depth'] || 4).to_f + (options['lam_height'] || 6).to_f)
        else
          profile['points']
        end
        # V5.1: các mẫu ngoài cũ có thể được chuẩn hóa theo cạnh lớn nhất.
        # Chuẩn hóa lại độc lập X/Y trước khi áp Rộng/Cao để giữ đúng tỷ lệ kích thước đã chọn.
        if profile['user_added'] && !profile['preserve_aspect'] && source_points && source_points.length >= 3
          us = source_points.map { |q| q[0].to_f }; vs = source_points.map { |q| q[1].to_f }
          umin, umax = us.minmax; vmin, vmax = vs.minmax
          du = umax - umin; dv = vmax - vmin
          if du.abs > 1e-9 && dv.abs > 1e-9
            source_points = source_points.map { |q| [(q[0].to_f-umin)/du, (q[1].to_f-vmin)/dv] }
          end
        end
        source_points = LamRound.normalized(source_points,width.to_f*25.4,height.to_f*25.4) if LamRound.enabled?(options)
        lam_rotation = profile['category'].to_s == 'Lam sóng' ? (options['lam_rotation'] || 0).to_f : 0.0
        if profile['category'].to_s == 'Lam sóng' && lam_rotation.abs > 0.0001
          # Xoay biên dạng giống xoay map vật liệu: xoay tự do trong mặt phẳng tiết diện, quanh tâm mẫu.
          side_dir = side.normalize
          vertical_dir = vertical.normalize
          phys_w = swap_axes ? height : width
          phys_h = swap_axes ? width : height
          sx = side_sign
          sy = vertical_sign
          a = lam_rotation.degrees
          ca = Math.cos(a); sa = Math.sin(a)
          cx = phys_w * 0.5; cy = phys_h * 0.5
          pts = source_points.map { |uv|
            u0 = swap_axes ? uv[1].to_f : uv[0].to_f
            v0 = swap_axes ? uv[0].to_f : uv[1].to_f
            x = u0 * phys_w - cx; y = v0 * phys_h - cy
            xr = x * ca - y * sa + cx
            yr = x * sa + y * ca + cy
            Geom::Point3d.new(origin.x + side_dir.x * xr * sx + vertical_dir.x * yr * sy, origin.y + side_dir.y * xr * sx + vertical_dir.y * yr * sy, origin.z + side_dir.z * xr * sx + vertical_dir.z * yr * sy)
          }
        else
          pts = source_points.map { |uv|
            u = swap_axes ? uv[1] : uv[0]
            v = swap_axes ? uv[0] : uv[1]
            Geom::Point3d.new(origin.x + side.x * u + vertical.x * v, origin.y + side.y * u + vertical.y * v, origin.z + side.z * u + vertical.z * v)
          }
        end

        # V209: clean_face_points chỉ được phép xóa điểm trùng liền kề/thẳng hàng;
        # thứ tự contour phải giữ nguyên 100% từ outer_loop của Profile.
        pts = clean_face_points(pts)
        raise 'Biên dạng sau khi làm sạch còn dưới 3 điểm hợp lệ.' if pts.length < 3

        # V220 ENGINE: dùng Follow Me chuẩn của SketchUp trên TOÀN BỘ path liên tục.
        # Không tự loft ring/miter nữa. Profile đã nằm trong mặt phẳng vuông góc Edge đầu.
        # Tạo Face thật từ contour, copy path vào cùng group rồi để SketchUp xử lý góc/loop.
        path_points = [chain.first[1]] + chain.map { |row| row[2] }
        raise 'Đường chạy cần ít nhất 2 điểm.' if path_points.length < 2

        profile_face = ents.add_face(pts)
        raise 'Không tạo được Face Profile tự động từ mẫu SKP.' unless profile_face && profile_face.valid?
        profile_face.reverse! if profile_face.normal.dot(direction) > 0

        path_edges = []
        chain.each do |row|
          a = row[1]; b = row[2]
          pe = ents.add_line(a, b)
          path_edges << pe if pe && pe.valid?
        end
        raise "Đường chạy có #{chain.length} Edge nhưng chỉ tạo được #{path_edges.length} Edge tạm." if path_edges.length != chain.length

        before_faces = ents.grep(Sketchup::Face).length
        ok = profile_face.followme(path_edges)
        after_faces = ents.grep(Sketchup::Face).length
        raise 'SketchUp Follow Me không tạo được thân phào theo chuỗi Edge đã chọn.' if ok == false || after_faces <= before_faces

        # Xóa path tạm nếu chúng còn tồn tại và không còn là cạnh của thân phào.
        # Không xóa edge đang được Face kết quả sử dụng.
        path_edges.each do |e|
          begin
            e.erase! if e.valid? && e.faces.empty?
          rescue
          end
        end
        if LamRound.enabled?(options)
          raise 'Lam bo R1 chưa tạo thành khối kín. Hãy kiểm tra lại đường chạy.' unless ents.grep(Sketchup::Edge).all? { |e|e.faces.length==2 }
        end
        group.name = 'Phào ' + profile['name']
        MouldingEdgeDisplay.soften(ents,chain,pts) unless profile['category'].to_s == 'Lam sóng'
        apply_lam_edge_display(ents,chain.map { |row|row[2]-row[1] },options)
        LamRound.smooth(ents) if LamRound.enabled?(options)
        group.set_attribute('LOFIHOME','engine','V274_NATIVE_FOLLOWME_PLUS_FULL3D_HYBRID')
        group.set_attribute('LOFIHOME','edge_count',edges.length)
        group.set_attribute('LOFIHOME','profile_source',profile['source_type'].to_s)
        if profile['category'].to_s == 'Lam sóng'
          group.name = 'Lam sóng - chỉnh sửa được'
          group.set_attribute('PhaoChiEdit', 'kind', 'edge')
          group.set_attribute('PhaoChiEdit', 'options', JSON.generate(options.reject { |k,_|k=='_lam_outer_operation' }))
          group.set_attribute('PhaoChiEdit', 'profile_id', options['id'].to_s)
          group.set_attribute('PhaoChiEdit', 'legacy_v592', 1) if options['id'].to_s == 'LAM001'
          group.set_attribute('PhaoChiEdit', 'edge_pids', JSON.generate(edges.map { |e| Compat.entity_id(e) }))
        end
        operation_result=model.commit_operation if own_operation
        LamRound.enabled?(options) ? group : operation_result
      rescue => e
        model.abort_operation if own_operation
        raise e
      end
    end


    def self.selected_editable_lam
      Sketchup.active_model.selection.grep(Sketchup::Group).find { |g| g.get_attribute('PhaoChiEdit','kind') }
    end

    def self.load_finished_lam
      g = selected_editable_lam
      unless g
        UI.messagebox("Hãy chọn 1 Group lam được tạo bằng V5.9.2 rồi bấm 'Lấy thông số'.")
        return nil
      end
      return Tes3Controls.read(g) if g.get_attribute('PhaoChiEdit','tes3_control_capture',nil)
      return LamMeasure.read(g) if g.get_attribute('PhaoChiEdit','lam_face_capture',nil)
      opts = JSON.parse(g.get_attribute('PhaoChiEdit','options','{}')) rescue {}
      opts['kind'] = g.get_attribute('PhaoChiEdit','kind')
      opts
    end

    # FIX8.3: cập nhật số lam SAU KHI SCALE nhưng khóa nguyên đường bao đã Scale.
    # Không quay về Face gốc. Nếu Group có scaled_outline, dựng lại trên đúng đường bao này;
    # chỉ thay đổi mật độ/bề rộng nan bên trong dải viền, kích thước ngoài + trong không đổi.
    def self.update_finished_lam(new_opts)
      model = Sketchup.active_model
      g = selected_editable_lam
      unless g
        UI.messagebox("Hãy chọn 1 Group lam được tạo bằng plugin.")
        return
      end
      old_opts = JSON.parse(g.get_attribute('PhaoChiEdit','options','{}')) rescue {}
      return update_tes3_control(g,new_opts) if g.get_attribute('PhaoChiEdit','tes3_control_capture',nil)
      return update_lam_face_fill(g,new_opts) if g.get_attribute('PhaoChiEdit','lam_face_capture',nil)
      return update_round_lam(g,new_opts) if LamRound.enabled?(old_opts)
      return update_tes3_fit(g,new_opts) if Tes3Fit.enabled?(old_opts) && ['face_auto','face_fit'].include?(g.get_attribute('PhaoChiEdit','kind').to_s)
      opts = old_opts.merge(new_opts)
      # V5.9.9.200: lấy Số lam từ payload chỉnh sửa, không giữ count cũ trong Group.
      if new_opts.key?('lam_count') || new_opts.key?(:lam_count)
        requested_count = (new_opts['lam_count'] || new_opts[:lam_count]).to_i
        opts['lam_count'] = [[requested_count, 1].max, 500].min
      end
      # V5.9.9.200: nhận diện chắc chắn LAM001 V5.9.2 kể cả Group cũ thiếu id.
      stored_pid = g.get_attribute('PhaoChiEdit','profile_id','').to_s
      if stored_pid == 'LAM001' || old_opts['id'].to_s == 'LAM001' || g.name.to_s.include?('Lam sóng')
        opts['id'] = 'LAM001' if stored_pid == 'LAM001' || old_opts['id'].to_s == 'LAM001'
      end
      kind = g.get_attribute('PhaoChiEdit','kind').to_s
      scaled_json = g.get_attribute('PhaoChiEdit','scaled_outline', nil)

      # Nếu đã Scale: khóa tuyệt đối kích thước ngoài. Bề rộng dải (width) cũng khóa theo
      # thông số lúc Scale để cạnh trong không đổi khi tăng/giảm số lam.
      if scaled_json && !scaled_json.to_s.empty? && ['face_auto','face_fit'].include?(kind)
        begin
          raw = JSON.parse(scaled_json)
          scaled_pts = raw.map { |a| Geom::Point3d.new(a[0].to_f, a[1].to_f, a[2].to_f) }
          raise 'Đường bao Scale không hợp lệ.' if scaled_pts.length < 3
          locked_width = old_opts['width'].to_f
          opts['width'] = locked_width if locked_width > 0
          opts['lam_fit_face'] = true
          opts['lam_auto_edge'] = true

          pid = g.get_attribute('PhaoChiEdit','face_pid').to_i
          face = Compat.find_entity(model,pid) rescue nil
          normal = if face && face.is_a?(Sketchup::Face) && face.valid?
                     face.normal.clone
                   else
                     # fallback normal từ 3 điểm của outline
                     (scaled_pts[1] - scaled_pts[0]).cross(scaled_pts[2] - scaled_pts[0])
                   end
          normal.normalize!

          model.start_operation('Cập nhật lam - khóa kích thước Scale', true)
          eps = 0.05.mm
          tmp_pts = scaled_pts.map { |pt| pt.offset(normal, eps) }
          tmp = model.active_entities.add_face(tmp_pts)
          raise 'Không tạo được mặt tạm theo kích thước Scale.' unless tmp
          tmp.reverse! if tmp.normal.dot(normal) < 0
          new_group = run_face_lam_auto(tmp, tmp.outer_loop, opts)
          raise 'Không dựng lại được lam.' unless new_group && new_group.valid?
          new_group.transform!(Geom::Transformation.translation(normal.reverse * eps))
          new_group.set_attribute('PhaoChiEdit','face_pid',pid) if pid > 0
          new_group.set_attribute('PhaoChiEdit','scaled_outline',scaled_json)
          new_group.set_attribute('PhaoChiEdit','scale_locked',1)
          tmp.erase! if tmp.valid?
          g.erase! if g.valid?
          model.selection.clear
          model.selection.add(new_group)
          model.commit_operation
          return new_group
        rescue => e
          model.abort_operation rescue nil
          UI.messagebox("Lỗi cập nhật lam sau Scale:\n#{e.class}: #{e.message}")
          return nil
        end
      end

      # Chưa Scale: giữ hành vi cũ, dựng lại từ Edge/Face nguồn.
      model.start_operation('Cập nhật lam đã vẽ', true)
      begin
        if kind == 'edge'
          pids = JSON.parse(g.get_attribute('PhaoChiEdit','edge_pids','[]')) rescue []
          edges = pids.map { |pid| Compat.find_entity(model,pid.to_i) rescue nil }.compact.select { |e| e.is_a?(Sketchup::Edge) && e.valid? }
          raise 'Không còn tìm thấy Edge gốc.' if edges.empty?
          g.erase!
          model.selection.clear
          edges.each { |e| model.selection.add(e) }
          model.commit_operation
          run_profile(opts)
        else
          pid = g.get_attribute('PhaoChiEdit','face_pid').to_i
          face = Compat.find_entity(model,pid) rescue nil
          raise 'Không còn tìm thấy Face gốc.' unless face && face.is_a?(Sketchup::Face) && face.valid?
          g.erase!
          model.selection.clear
          model.selection.add(face)
          model.commit_operation
          run_face_profile(opts)
        end
      rescue => e
        model.abort_operation rescue nil
        raise e
      end
    end

    # Scale theo kích thước đích nhưng DỰNG LẠI lam, không non-uniform scale Group.
    # Vì vậy các đường miter ở góc vẫn là giao của hai offset thật và giữ đúng 45° với khung chữ nhật.
    def self.scale_finished_lam_45(payload)
      model = Sketchup.active_model
      g = selected_editable_lam
      unless g
        UI.messagebox("Hãy chọn 1 Group lam TES3 đã vẽ trước khi Scale.")
        return
      end
      kind = g.get_attribute('PhaoChiEdit','kind').to_s
      return update_tes3_control(g,{},payload) if g.get_attribute('PhaoChiEdit','tes3_control_capture',nil)
      return update_lam_face_fill(g,{},payload) if g.get_attribute('PhaoChiEdit','lam_face_capture',nil)
      return update_tes3_surface(g,{},payload) if g.get_attribute('PhaoChiEdit','surface_capture',nil)
      unless ['face_auto','face_fit'].include?(kind)
        UI.messagebox("Scale giữ góc 45° hiện áp dụng cho lam chạy theo Bề mặt (Face).")
        return
      end
      pid = g.get_attribute('PhaoChiEdit','face_pid').to_i
      face = Compat.find_entity(model,pid) rescue nil
      unless face && face.is_a?(Sketchup::Face) && face.valid?
        UI.messagebox("Không còn tìm thấy Face gốc để dựng lại lam.")
        return
      end
      verts = face.outer_loop.vertices.map(&:position)
      unless verts.length == 4
        UI.messagebox("Scale giữ góc 45° hiện tối ưu cho Face khung 4 cạnh.")
        return
      end
      normal = face.normal.clone; normal.normalize!
      # Trục X lấy theo cạnh dài nhất; Y nằm trong mặt phẳng và vuông góc X.
      edges = 4.times.map { |i| [verts[i], verts[(i+1)%4], verts[i].distance(verts[(i+1)%4])] }
      ea, eb, _ = edges.max_by { |x| x[2] }
      ux = eb - ea; ux.normalize!
      uy = normal.cross(ux); uy.normalize!
      center = Geom::Point3d.new(
        verts.map(&:x).sum / 4.0, verts.map(&:y).sum / 4.0, verts.map(&:z).sum / 4.0
      )
      coords = verts.map { |pt| v=pt-center; [v.dot(ux), v.dot(uy)] }
      cur_w = coords.map(&:first).max - coords.map(&:first).min
      cur_h = coords.map(&:last).max - coords.map(&:last).min
      mode = (payload['mode'] || 'xy').to_s
      tw = [payload['target_w'].to_f, 1.0].max.mm
      th = [payload['target_h'].to_f, 1.0].max.mm
      sx = mode.include?('x') ? tw / cur_w : 1.0
      sy = mode.include?('y') ? th / cur_h : 1.0
      new_pts = coords.map { |x,y| center.offset(ux, x*sx).offset(uy, y*sy) }
      opts = JSON.parse(g.get_attribute('PhaoChiEdit','options','{}')) rescue {}
      opts['lam_fit_face'] = true; opts['lam_auto_edge'] = true
      # V5.9.9.200: khóa nhịp góc sau Scale; không stretch pitch theo từng cạnh.
      opts['tes3_scale_corner_lock'] = true

      return update_round_lam(g,opts,new_pts.map(&:to_a)) if LamRound.enabled?(opts)
      return update_tes3_fit(g,opts,new_pts.map(&:to_a)) if Tes3Fit.enabled?(opts)

      model.start_operation('Scale lam giữ góc 45°', true)
      begin
        # Tạo Face tạm lệch rất nhỏ để không cắt dính Face gốc.
        eps = 0.05.mm
        tmp_pts = new_pts.map { |pt| pt.offset(normal, eps) }
        tmp = model.active_entities.add_face(tmp_pts)
        raise 'Không tạo được mặt tạm để dựng lại lam.' unless tmp
        tmp.reverse! if tmp.normal.dot(normal) < 0
        new_group = run_face_lam_auto(tmp, tmp.outer_loop, opts)
        raise 'Không dựng lại được lam.' unless new_group && new_group.valid?
        new_group.transform!(Geom::Transformation.translation(normal.reverse * eps))
        # Lưu đường bao ảo để biết đây là bản đã Scale; Face gốc vẫn được giữ để tham chiếu mặt phẳng.
        new_group.set_attribute('PhaoChiEdit','face_pid',Compat.entity_id(face))
        new_group.set_attribute('PhaoChiEdit','scaled_outline',JSON.generate(new_pts.map { |pt| [pt.x,pt.y,pt.z] }))
        tmp.erase! if tmp.valid?
        g.erase! if g.valid?
        model.selection.clear; model.selection.add(new_group)
        model.commit_operation
      rescue => e
        model.abort_operation rescue nil
        raise e
      end
    end

    def self.selected_phao_group
      items=Sketchup.active_model.selection.to_a
      return nil unless items.length==1
      item=items.first
      return nil unless item.is_a?(Sketchup::Group) || item.is_a?(Sketchup::ComponentInstance)
      return nil unless item.valid? && !item.locked?
      item
    end

    # Xác định trục dọc của thanh phào theo kích thước local lớn nhất.
    # Nhờ vậy phào ngang, đứng hoặc chéo đều xoay quanh chính đường chạy của nó.
    def self.phao_long_axis(group)
      lb = Compat.definition(group).bounds
      dims = [lb.width, lb.height, lb.depth]
      local_axis = [Geom::Vector3d.new(1,0,0), Geom::Vector3d.new(0,1,0), Geom::Vector3d.new(0,0,1)][dims.each_with_index.max[1]]
      world_axis = local_axis.transform(group.transformation)
      world_axis.normalize!
      world_axis
    end

    def self.rotation_axis(group, axis_mode)
      case axis_mode.to_s
      when 'x' then Geom::Vector3d.new(1, 0, 0)
      when 'y' then Geom::Vector3d.new(0, 1, 0)
      when 'z' then Geom::Vector3d.new(0, 0, 1)
      else phao_long_axis(group)
      end
    end

    def self.rotation_about_axis(group, angle_deg, axis_mode = 'phao')
      Geom::Transformation.rotation(group.bounds.center, rotation_axis(group, axis_mode), angle_deg.degrees)
    end

    def self.rotation_about_phao_axis(group, angle_deg)
      rotation_about_axis(group, angle_deg, 'phao')
    end

    def self.remember_original_transform(group)
      key = 'original_transform_v37'
      saved = group.get_attribute('LVN_PhaoChi_V37', key)
      group.set_attribute('LVN_PhaoChi_V37', key, group.transformation.to_a) unless saved.is_a?(Array) && saved.length == 16
    end

    def self.reset_finished_to_origin
      model = Sketchup.active_model
      group = selected_phao_group
      unless group
        UI.messagebox('Chọn đúng một Component Dynamic hoặc Group chưa khóa trong bản vẽ.')
        return
      end
      saved = group.get_attribute('LVN_PhaoChi_V37', 'original_transform_v37')
      unless saved.is_a?(Array) && saved.length == 16
        UI.messagebox('Đối tượng chưa có trạng thái gốc. Hãy xoay hoặc lật bằng các nút trong bảng này trước.')
        return
      end
      model.start_operation('Trở về gốc phào', true)
      begin
        group.transformation = Geom::Transformation.new(saved)
        model.commit_operation
      rescue => e
        model.abort_operation
        raise e
      end
    end

    def self.rotate_finished_angle(angle_deg, axis_mode = 'phao')
      model = Sketchup.active_model
      group = selected_phao_group
      unless group
        UI.messagebox('Chọn đúng một Component Dynamic hoặc Group chưa khóa trong bản vẽ.')
        return
      end
      return if angle_deg.abs < 0.0001
      model.start_operation('Xoay Component / Group', true)
      begin
        remember_original_transform(group)
        group.transform!(rotation_about_axis(group, angle_deg, axis_mode))
        model.commit_operation
      rescue => e
        model.abort_operation
        raise e
      end
    end

    def self.transform_finished(kind)
      model = Sketchup.active_model
      group = selected_phao_group
      unless group
        UI.messagebox('Chọn đúng một Component Dynamic hoặc Group chưa khóa trong bản vẽ.')
        return
      end

      if kind == 'reset_origin'
        reset_finished_to_origin
        return
      end

      bb = group.bounds
      center = bb.center
      tr = nil

      case kind
      when 'left_right'
        tr = Geom::Transformation.scaling(center, -1.0, 1.0, 1.0)
      when 'up_down'
        tr = Geom::Transformation.scaling(center, 1.0, 1.0, -1.0)
      when 'rotate_180'
        tr = rotation_about_phao_axis(group, 180.0)
      when 'rotate_90'
        tr = rotation_about_phao_axis(group, 90.0)
      when 'reverse_axis'
        axis = bb.width >= bb.depth ? Geom::Vector3d.new(0,1,0) : Geom::Vector3d.new(1,0,0)
        tr = Geom::Transformation.rotation(center, axis, 180.degrees)
      when 'rotate_minus_90'
        tr = rotation_about_phao_axis(group, -90.0)
      end

      return unless tr
      model.start_operation('Lật Component / Group', true)
      begin
        remember_original_transform(group)
        group.transform!(tr)
        model.commit_operation
      rescue => e
        model.abort_operation
        UI.messagebox("Không đảo được hướng phào:\n#{e.message}")
      end
    end


    # Đổ MAP giữ nguyên tỷ lệ từ Face/Group mẫu sang Face/Group đích.
    # V5.9.9.200: PHYSICAL UV ASPECT LOCK (U=Texture Width, V=Texture Height).
    # Đọc mapping THỰC đang hiển thị trên Face mẫu, dựng hàm UV theo tọa độ World,
    # rồi tính UV cho chính các điểm của Face đích. Không dùng Texture#width/height,
    # không scale theo kích thước Face đích, không copy tile theo local-space.
    # V5.9.9.200: đặt Face mẫu MAP rõ ràng, không tự đoán theo diện tích/PID.
    # Chọn đúng 1 Face có texture rồi bấm "ĐẶT FACE MẪU MAP".
    class MapTwoPointTool
      def initialize(owner)
        @owner = owner
        @points = []
        @ips = Sketchup::InputPoint.new
      end
      def activate
        Sketchup.set_status_text('V136: Bấm TÂM họa tiết thứ nhất, rồi bấm TÂM họa tiết giống hệt kế tiếp (ưu tiên theo phương ngang).', SB_PROMPT)
      end
      def onMouseMove(flags, x, y, view)
        @ips.pick(view, x, y)
        view.tooltip = @ips.tooltip if @ips.valid?
        view.invalidate
      end
      def draw(view)
        @ips.draw(view) if @ips.valid?
        if @points.length == 1 && @ips.valid?
          view.set_color_from_line(@points[0], @ips.position)
          view.draw(GL_LINES, @points[0], @ips.position)
        end
      end
      def onLButtonDown(flags, x, y, view)
        @ips.pick(view, x, y)
        return UI.beep unless @ips.valid?
        @points << @ips.position.clone
        if @points.length == 1
          Sketchup.set_status_text('V136: Bấm TÂM họa tiết giống hệt kế tiếp.', SB_PROMPT)
        else
          dist = @points[0].distance(@points[1])
          if dist < 1.mm
            UI.messagebox('V136: Hai điểm quá gần nhau. Hãy đo lại.')
          else
            @owner.finish_map_2pt_calibration(@points[0], @points[1])
          end
          Sketchup.active_model.select_tool(nil)
        end
      end
      def onCancel(reason, view)
        Sketchup.active_model.select_tool(nil)
      end
    end

    def self.start_map_2pt_calibration
      source = @map_source_face
      unless source && source.valid? && source.material && source.material.texture
        UI.messagebox("V5.9.9.200: Trước tiên chọn Face mẫu và bấm ĐẶT FACE MẪU MAP.")
        return
      end
      Sketchup.active_model.select_tool(MapTwoPointTool.new(self))
    end

    def self.finish_map_2pt_calibration(p1, p2)
      source = @map_source_face
      tw = Sketchup.create_texture_writer
      helper = source.get_UVHelper(true, false, tw)
      # InputPoint đang ở đúng editing context của Face mẫu, nên dùng điểm model trực tiếp.
      q1 = helper.get_front_UVQ(p1)
      q2 = helper.get_front_UVQ(p2)
      q1z = q1.z.to_f.abs < 1.0e-12 ? 1.0 : q1.z.to_f
      q2z = q2.z.to_f.abs < 1.0e-12 ? 1.0 : q2.z.to_f
      du = q2.x.to_f/q2z - q1.x.to_f/q1z
      dv = q2.y.to_f/q2z - q1.y.to_f/q1z
      uv_len = Math.sqrt(du*du + dv*dv)
      if uv_len < 1.0e-9
        UI.messagebox('V136: Hai điểm cho UV gần như bằng nhau. Hãy chọn 2 họa tiết giống nhau liên tiếp.')
        return
      end
      @map_calibration_world_period = p1.distance(p2)
      @map_calibration_uv_period = uv_len
      @map_calibration_du = du
      @map_calibration_dv = dv
      # V136: lưu trực tiếp hệ số UV/mm đo thật từ Face mẫu.
      # Đây là chuẩn duy nhất cho hướng 2 điểm, không suy lại từ texture.width/height.
      @map_calibration_uv_per_world = uv_len / @map_calibration_world_period.to_f
      UI.messagebox("V5.9.9.200: ĐÃ ĐO 2 ĐIỂM MAP MẪU.\nKhoảng cách thực = #{(@map_calibration_world_period.to_mm).round(3)} mm\nΔU=#{du.round(6)}  ΔV=#{dv.round(6)}\n\nBây giờ chọn Face/Group đích và bấm ĐỔ MAP GIỮ TỶ LỆ.")
    rescue => e
      UI.messagebox("Lỗi ĐO 2 ĐIỂM MAP V5.9.9.200\n#{e.class}: #{e.message}")
    end

    # V5.9.9.200: Lưu nguyên Material/Texture của Face đang chọn thành file SKM.
    # Không resize, không crop, không đổi UV hay kích thước texture.
    def self.save_map_sample
      model = Sketchup.active_model
      face = model.selection.grep(Sketchup::Face).find { |f| f.valid? && f.material && f.material.texture }
      face ||= (@map_source_face if @map_source_face && @map_source_face.valid? && @map_source_face.material && @map_source_face.material.texture)
      unless face
        UI.messagebox("V5.9.9.200: Hãy chọn trực tiếp 1 Face có MAP rồi bấm LƯU MẪU MAP.")
        return
      end
      mat = face.material
      unless mat.respond_to?(:save_as)
        UI.messagebox('Ban SketchUp nay chua co lenh luu SKM qua plugin. Hay luu vat lieu trong bang Materials cua SketchUp.')
        return
      end
      base = (mat.display_name rescue mat.name).to_s.strip
      base = 'LOFIHOME_MAP' if base.empty?
      base = base.gsub(/[\\\/:*?\"<>|]/, '_')
      path = UI.savepanel('LƯU MẪU MAP SKM', nil, "#{base}.skm")
      return unless path
      path += '.skm' unless File.extname(path).downcase == '.skm'
      ok = mat.save_as(path)
      if ok
        tex = mat.texture
        UI.messagebox("V5.9.9.200: ĐÃ LƯU MẪU MAP.\n\n#{path}\n\nGiữ nguyên ảnh texture và kích thước Material: #{tex.width.to_mm.round(3)} x #{tex.height.to_mm.round(3)} mm.")
      else
        UI.messagebox('V5.9.9.200: SketchUp không lưu được file SKM.')
      end
    rescue => e
      UI.messagebox("Lỗi LƯU MẪU MAP V5.9.9.200\n#{e.class}: #{e.message}")
    end

    def self.set_map_source
      model = Sketchup.active_model
      sel = model.selection.to_a.select(&:valid?)
      face = sel.find { |e| e.is_a?(Sketchup::Face) && e.material && e.material.texture }
      unless face
        UI.messagebox("V5.9.9.200: Hãy mở đúng context (nếu cần), chọn trực tiếp 1 FACE MẪU đang có MAP rồi bấm ĐẶT FACE MẪU MAP.")
        return
      end
      @map_source_face = face
      @map_source_tr = Geom::Transformation.new
      @map_source_pid = Compat.entity_id(face)
      mat = face.material
      UI.messagebox("V5.9.9.200: Đã đặt FACE MẪU MAP.\nPID=#{Compat.entity_id(face)}\nMaterial=#{mat.display_name rescue mat.name}\n\nBây giờ chọn Face/Group ĐÍCH rồi bấm ĐỔ MAP GIỮ TỶ LỆ.")
    rescue => e
      UI.messagebox("Lỗi ĐẶT FACE MẪU MAP V5.9.9.200\n#{e.class}: #{e.message}")
    end

    def self.apply_map_keep_scale
      model = Sketchup.active_model
      selected = model.selection.to_a.select(&:valid?)

      source = @map_source_face
      unless source && source.valid? && source.material && source.material.texture
        UI.messagebox("V5.9.9.200: Chưa có FACE MẪU MAP.\n\n1. Chọn trực tiếp Face mẫu có MAP.\n2. Bấm ĐẶT FACE MẪU MAP.\n3. Chọn Face/Group đích.\n4. Bấm ĐỔ MAP GIỮ TỶ LỆ.")
        return
      end

      # V136: COPY THEO HỆ TRỤC RIÊNG CỦA TỪNG FACE.
      # Không chiếu Face đích vào mặt phẳng WORLD của Face mẫu nữa.
      # Đây là điểm sửa chính cho trường hợp Face mẫu và Face đích khác góc xoay.
      items = []
      walk = nil
      walk = lambda do |entity, tr|
        case entity
        when Sketchup::Face
          items << [entity, tr]
        when Sketchup::Group
          ntr = tr * entity.transformation
          entity.entities.each { |e| walk.call(e, ntr) }
        when Sketchup::ComponentInstance
          ntr = tr * entity.transformation
          Compat.definition(entity).entities.each { |e| walk.call(e, ntr) }
        end
      end
      id = Geom::Transformation.new
      selected.each { |e| walk.call(e, id) if e.is_a?(Sketchup::Face) || e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance) }
      items.uniq! { |f,tr| [Compat.entity_id(f), tr.to_a.map { |v| v.round(9) }] }
      targets = items.reject { |f,tr| f == source }
      if targets.empty?
        UI.messagebox("V5.9.9.200: Hãy chọn ít nhất 1 Face/Group ĐÍCH.")
        return
      end

      mat = source.material
      tw = Sketchup.create_texture_writer
      helper = source.get_UVHelper(true, false, tw)
      verts = source.outer_loop.vertices.map(&:position)
      if verts.length < 3
        UI.messagebox('V136: Face mẫu không đủ 3 điểm.')
        return
      end

      # Tạo hệ 2D LOCAL trên Face mẫu.
      s0 = verts[0]
      s1 = verts[1]
      s2 = verts.find { |p| (s1-s0).cross(p-s0).length > 1.0e-8 }
      unless s2
        UI.messagebox('V136: Face mẫu suy biến.')
        return
      end
      sex = s1 - s0; sex.normalize!
      sn = (s1-s0).cross(s2-s0); sn.normalize!
      sey = sn.cross(sex); sey.normalize!

      src_pts = [s0,s1,s2]
      src_xy = src_pts.map { |p| d=p-s0; [d.dot(sex), d.dot(sey)] }
      src_uv = src_pts.map do |p|
        q=helper.get_front_UVQ(p); qq=q.z.to_f.abs < 1e-12 ? 1.0 : q.z.to_f
        [q.x.to_f/qq, q.y.to_f/qq]
      end
      x0,y0=src_xy[0]; x1,y1=src_xy[1]; x2,y2=src_xy[2]
      det=(x1-x0)*(y2-y0)-(x2-x0)*(y1-y0)
      if det.abs < 1e-12
        UI.messagebox('V136: Không giải được mapping Face mẫu.')
        return
      end
      solve=lambda do |vals|
        f0,f1,f2=vals
        a=((f1-f0)*(y2-y0)-(f2-f0)*(y1-y0))/det
        b=((x1-x0)*(f2-f0)-(x2-x0)*(f1-f0))/det
        c=f0-a*x0-b*y0
        [a,b,c]
      end
      au,bu,cu=solve.call(src_uv.map(&:first))
      av,bv,cv=solve.call(src_uv.map(&:last))

      # Dữ liệu 2 điểm chỉ dùng để kiểm tra chu kỳ nguồn, KHÔNG nhân scale mù.
      measured = nil
      if @map_calibration_world_period && @map_calibration_uv_period && @map_calibration_uv_period.to_f > 1e-9
        measured = @map_calibration_world_period.to_f / @map_calibration_uv_period.to_f
      end

      model.start_operation('LOFIHOME - SOURCE AXIS LOCK V136', true)
      count=0; skipped=0
      begin
        targets.each do |face,tr|
          tv=face.outer_loop.vertices.map(&:position)
          if tv.length < 3
            skipped+=1; next
          end
          t0=tv[0]; t1=tv[1]
          t2=tv.find { |p| (t1-t0).cross(p-t0).length > 1.0e-8 }
          unless t2
            skipped+=1; next
          end
          tn=(t1-t0).cross(t2-t0); tn.normalize!

          # V136: GIỮ NGUYÊN HƯỚNG U/V CỦA FACE MẪU.
          # Không lấy cạnh đầu tiên của Face đích làm trục U (đó là lỗi V136 làm MAP xoay 90°).
          # Chuyển trục U/V mẫu sang local-space của instance đích, rồi chiếu lên mặt phẳng Face đích.
          inv_tr = tr.inverse rescue Geom::Transformation.new
          ex_hint = sex.transform(inv_tr)
          ey_hint = sey.transform(inv_tr)
          # project vector to target face plane
          tex = ex_hint - tn.clone.tap { |n| n.length = ex_hint.dot(tn) }
          if tex.length < 1.0e-8
            tex = ey_hint.cross(tn)
          end
          tex.normalize!
          tey = tn.cross(tex); tey.normalize!
          # Giữ dấu V giống Face mẫu, tránh mirror/đảo hướng.
          tey.reverse! if tey.dot(ey_hint) < 0.0
          tex.reverse! if tex.dot(ex_hint) < 0.0

          picks=[t0,t1,t2]
          mapping=[]
          picks.each do |lp|
            d=lp-t0
            x=d.dot(tex); y=d.dot(tey)
            u=au*x+bu*y+cu
            v=av*x+bv*y+cv
            mapping << lp << Geom::Point3d.new(u,v,1.0)
          end
          face.material=mat
          face.back_material=mat
          if face.position_material(mat,mapping,true)
            count+=1
          else
            skipped+=1
          end
        end
        model.commit_operation
        model.active_view.invalidate
        msg="V5.9.9.200: Đã đổ MAP lên #{count} Face.\nGIỮ NGUYÊN TRỤC U/V CỦA FACE MẪU — không hoán đổi U/V, không lấy cạnh Face đích làm hướng MAP, không scale theo kích thước Face đích."
        msg += "\nChu kỳ 2 điểm nguồn: #{(measured.to_mm).round(3)} mm / 1UV" if measured
        msg += "\nBỏ qua #{skipped} Face." if skipped>0
        UI.messagebox(msg)
      rescue => e
        model.abort_operation
        UI.messagebox("Lỗi ĐỔ MAP V5.9.9.200\n#{e.class}: #{e.message}")
      end
    end


    # V5.9.9.200: Chẩn đoán MAP - chỉ đọc, KHÔNG thay đổi model.
    # Báo kích thước texture, scale instance và kích thước UV tile Local/World.
    def self.diagnose_map_scale
      model = Sketchup.active_model
      selected = model.selection.to_a.select(&:valid?)
      items = []
      walk = nil
      walk = lambda do |entity, tr, path|
        case entity
        when Sketchup::Face
          items << [entity, tr, path]
        when Sketchup::Group
          ntr = tr * entity.transformation
          entity.entities.each { |e| walk.call(e, ntr, path + [entity]) }
        when Sketchup::ComponentInstance
          ntr = tr * entity.transformation
          Compat.definition(entity).entities.each { |e| walk.call(e, ntr, path + [entity]) }
        end
      end
      id = Geom::Transformation.new
      selected.each { |e| walk.call(e, id, []) if e.is_a?(Sketchup::Face) || e.is_a?(Sketchup::Group) || e.is_a?(Sketchup::ComponentInstance) }
      textured = items.select { |face, _tr, _path| face.material && face.material.texture }
      if textured.empty?
        UI.messagebox("V5.9.9.200 CHẨN ĐOÁN MAP:\nHãy chọn Face/Group có MAP rồi chạy lại.")
        return
      end

      fmt_len = lambda { |x| (x.to_f * 25.4).round(3) }
      fmt_num = lambda { |x| x.to_f.round(6) }
      lines = ["V5.9.9.200 — CHẨN ĐOÁN MAP (chỉ đọc, không sửa model)"]
      textured.first(6).each_with_index do |(face, tr, path), idx|
        mat = face.material
        tex = mat.texture
        xa = tr.xaxis; ya = tr.yaxis; za = tr.zaxis
        sx = xa.length; sy = ya.length; sz = za.length
        anchor = face.outer_loop.vertices.first.position
        tile = face.uv_tile_at(anchor, true) rescue nil
        lines << ""
        lines << "FACE #{idx+1}  PID=#{Compat.entity_id(face)}  depth=#{path.length}"
        lines << "Material: #{mat.display_name rescue mat.name}"
        lines << "Texture physical: #{fmt_len.call(tex.width)} x #{fmt_len.call(tex.height)} mm"
        lines << "Transform scale axes: X=#{fmt_num.call(sx)}  Y=#{fmt_num.call(sy)}  Z=#{fmt_num.call(sz)}"
        if tile && tile.length == 8
          pairs = tile.each_slice(2).to_a
          lines << "RAW UVQ (4 điểm từ Face#uv_tile_at):"
          pairs.each_with_index do |pair, pi|
            mp, uvq = pair
            qraw = uvq.z.to_f
            qsafe = qraw.abs < 1.0e-12 ? 1.0 : qraw
            un = uvq.x.to_f / qsafe
            vn = uvq.y.to_f / qsafe
            mw = mp.transform(tr)
            lines << " P#{pi+1}: UVQ=(#{fmt_num.call(uvq.x)}, #{fmt_num.call(uvq.y)}, #{fmt_num.call(qraw)})  UV=(#{fmt_num.call(un)}, #{fmt_num.call(vn)})"
            lines << "     World=(#{fmt_len.call(mw.x)}, #{fmt_len.call(mw.y)}, #{fmt_len.call(mw.z)}) mm"
          end
          qs = pairs.map { |pair| pair[1].z.to_f }
          qmin = qs.min; qmax = qs.max
          lines << " Q range: #{fmt_num.call(qmin)} .. #{fmt_num.call(qmax)}  delta=#{fmt_num.call(qmax-qmin)}"
          # Tìm các cặp điểm có chênh UV lớn nhất theo U và V để đo chu kỳ thực tế.
          best_u = nil; best_v = nil
          pairs.combination(2) do |a,b|
            mp1,uv1=a; mp2,uv2=b
            q1 = uv1.z.to_f.abs < 1e-12 ? 1.0 : uv1.z.to_f
            q2 = uv2.z.to_f.abs < 1e-12 ? 1.0 : uv2.z.to_f
            u1=uv1.x.to_f/q1; v1=uv1.y.to_f/q1; u2=uv2.x.to_f/q2; v2=uv2.y.to_f/q2
            du=(u2-u1).abs; dv=(v2-v1).abs
            rec=[mp1,mp2,du,dv]
            best_u=rec if best_u.nil? || (du-dv).abs > (best_u[2]-best_u[3]).abs
            best_v=rec if best_v.nil? || (dv-du).abs > (best_v[3]-best_v[2]).abs
          end
          [[:U,best_u],[:V,best_v]].each do |label,rec|
            next unless rec
            p1,p2,du,dv=rec
            dl=p1.distance(p2)
            dw=p1.transform(tr).distance(p2.transform(tr))
            lines << "Tile #{label}: local=#{fmt_len.call(dl)} mm  world=#{fmt_len.call(dw)} mm  dU=#{fmt_num.call(du)} dV=#{fmt_num.call(dv)}"
          end
        else
          lines << "UV tile: KHÔNG ĐỌC ĐƯỢC"
        end
      end
      lines << ""
      lines << "So sánh RAW UVQ, UV=(U/Q,V/Q) và Tile world giữa Face mẫu/đích. Nếu Q khác 1 hoặc thay đổi theo điểm, mapping có thành phần projective/perspective."
      lines << "Chụp nguyên hộp này gửi lại. V136 chỉ chẩn đoán RAW UVQ, không sửa model."
      UI.messagebox(lines.join("\n"))
    rescue => e
      UI.messagebox("Lỗi CHẨN ĐOÁN MAP V5.9.9.200\n#{e.class}: #{e.message}")
    end

    # V5.9.9.200: Xoay/lật MAP đã đổ nhưng GIỮ NGUYÊN tỷ lệ UV.
    # Chỉ thay đổi hệ UV của Face, tuyệt đối không xoay/scale hình học.
    # V5.9.9.200: Thu thap Face trong Face/Group/Component, ke ca material duoc gan o container.
    # Neu Face dang ke thua material tu Group/Component, bake material xuong Face truoc khi sua UV.
    # V5.9.9.200: tìm vật liệu kế thừa của đúng Group/Component đang chọn.
    # TES3 có 4 Group cạnh con. Khi vật liệu được sơn ở Group khung cha, SketchUp
    # vẫn hiển thị texture trên Group cạnh con dù bản thân Face/Group con không có material.
    # Hàm này lần ngược cấu trúc model bằng cách duyệt từ active_entities để lấy đúng
    # material của tổ tiên, nhờ đó có thể xoay MAP RIÊNG từng khối cạnh.
    def self.inherited_material_for_selected(target)
      model = Sketchup.active_model
      # Khi đang edit sâu vào TES3, target nằm trong active_entities chứ không thể
      # tìm trực tiếp từ model.entities. Lấy material hiệu dụng từ active_path trước.
      if model.respond_to?(:active_path) && model.active_path
        model.active_path.reverse_each do |inst|
          if inst.respond_to?(:material) && inst.material && inst.material.texture
            return inst.material
          end
        end
      end
      found = nil
      walk = nil
      walk = lambda do |entities, inherited_material|
        entities.each do |entity|
          next unless entity.valid?
          current_material = if entity.respond_to?(:material) && entity.material
                               entity.material
                             else
                               inherited_material
                             end
          if entity == target
            found = current_material
            return true
          end
          case entity
          when Sketchup::Group
            return true if walk.call(entity.entities, current_material)
          when Sketchup::ComponentInstance
            return true if walk.call(Compat.definition(entity).entities, current_material)
          end
        end
        false
      end
      walk.call(model.entities, nil)
      found
    rescue
      nil
    end

    def self.collect_mapped_faces_from_selection(selected)
      items = []
      walk = nil
      walk = lambda do |entity, inherited_material|
        case entity
        when Sketchup::Face
          # Ưu tiên material mặt trước; nếu không có thì dùng mặt sau hoặc material kế thừa.
          mat = entity.material || entity.back_material || inherited_material
          items << [entity, mat] if mat && mat.texture
        when Sketchup::Group
          mat = entity.material || inherited_material
          entity.entities.each { |e| walk.call(e, mat) }
        when Sketchup::ComponentInstance
          mat = entity.material || inherited_material
          Compat.definition(entity).entities.each { |e| walk.call(e, mat) }
        end
      end
      selected.each do |e|
        next unless e.valid?
        inherited = inherited_material_for_selected(e)
        walk.call(e, inherited)
      end
      seen = {}
      items.select do |face, mat|
        key = Compat.entity_id(face)
        next false if seen[key]
        seen[key] = true
        face.valid? && mat && mat.texture
      end
    end

    def self.rotate_map_selected(mode)
      model = Sketchup.active_model
      selected = model.selection.to_a.select(&:valid?)
      face_items = collect_mapped_faces_from_selection(selected)
      if face_items.empty?
        UI.messagebox('V5.9.9.200: Hãy chọn Face/Group TES3 có MAP rồi bấm XOAY MAP.')
        return
      end

      # V5.9.9.200: Xoay UV từ CHÍNH mapping hiện tại của từng Face.
      # Không suy hướng từ cạnh dài nữa. Cách này xử lý đồng thời nền và các nan
      # nằm sâu trong Group/Component con, kể cả khi chúng có trục local khác nhau.
      # UV được đổi sang kích thước vật lý của texture trước khi xoay để giữ tỷ lệ.
      model.start_operation("LOFIHOME - XOAY MAP #{mode}", true)
      count = 0
      begin
        tw = Sketchup.create_texture_writer
        face_items.each do |face, inherited_mat|
          next unless face && face.valid?
          mat = face.material || face.back_material || inherited_mat
          next unless mat && mat.texture

          # Bake material hiệu dụng xuống cả 2 phía để không còn phụ thuộc Group cha.
          face.material = mat unless face.material
          face.back_material = mat unless face.back_material

          verts = face.outer_loop.vertices.map(&:position)
          next if verts.length < 3
          # Chọn 3 điểm không thẳng hàng.
          p0 = verts[0]
          p1 = nil; p2 = nil
          verts[1..-1].each do |p|
            next if p.distance(p0) < 1.0e-8
            if p1.nil?
              p1 = p
            elsif ((p1-p0).cross(p-p0)).length > 1.0e-8
              p2 = p; break
            end
          end
          next unless p1 && p2

          helper = face.get_UVHelper(true, true, tw)
          tex_w = [mat.texture.width.to_f, 1.0e-9].max
          tex_h = [mat.texture.height.to_f, 1.0e-9].max

          rotate_uv = lambda do |uvs|
            u0,v0 = uvs[0]
            uvs.map do |u,v|
              # Làm việc trong không gian vật lý của texture để +90/-90 không làm đổi scale.
              x = (u-u0) * tex_w
              y = (v-v0) * tex_h
              xr, yr = case mode
                       when 'ccw90' then [-y, x]
                       when 'rot180' then [-x, -y]
                       when 'flip_h' then [-x, y]
                       when 'flip_v' then [x, -y]
                       else [y, -x] # cw90
                       end
              [u0 + xr/tex_w, v0 + yr/tex_h]
            end
          end

          get_uv = lambda do |front|
            [p0,p1,p2].map do |p|
              q = front ? helper.get_front_UVQ(p) : helper.get_back_UVQ(p)
              qq = q.z.to_f.abs < 1.0e-12 ? 1.0 : q.z.to_f
              [q.x.to_f/qq, q.y.to_f/qq]
            end
          end
          apply_side = lambda do |front|
            uvs = rotate_uv.call(get_uv.call(front))
            mapping = [p0, Geom::Point3d.new(uvs[0][0],uvs[0][1],1),
                       p1, Geom::Point3d.new(uvs[1][0],uvs[1][1],1),
                       p2, Geom::Point3d.new(uvs[2][0],uvs[2][1],1)]
            face.position_material(mat, mapping, front) rescue false
          end
          ok_front = apply_side.call(true)
          ok_back  = apply_side.call(false)
          count += 1 if ok_front || ok_back
        end
        model.commit_operation
        UI.messagebox("V5.9.9.200: Đã xoay/lật MAP trên #{count} Face (nan + nền) của khối đang chọn.\nGiữ nguyên hình học và tỷ lệ texture.")
      rescue => e
        model.abort_operation rescue nil
        UI.messagebox("Lỗi XOAY MAP V5.9.9.200\n#{e.class}: #{e.message}")
      end
    end

    # V5.9.9.200: Tự căn MAP theo hướng dài của từng lam/Face.
    # Trục V của texture được đặt song song cạnh dài nhất của Face; tỷ lệ UV hiện tại được giữ lại.
    def self.align_map_to_lam_direction
      model = Sketchup.active_model
      selected = model.selection.to_a.select(&:valid?)
      face_items = collect_mapped_faces_from_selection(selected)
      faces = face_items.map(&:first)
      material_for = {}; face_items.each { |f,m| material_for[Compat.entity_id(f)] = m }
      if faces.empty?
        UI.messagebox('V5.9.9.200: Hãy chọn Face/Group lam đã có MAP rồi bấm MAP THEO HƯỚNG LAM.')
        return
      end

      model.start_operation('LOFIHOME - MAP THEO HUONG LAM', true)
      count = 0
      begin
        tw = Sketchup.create_texture_writer
        faces.each do |face|
          mat = face.material || material_for[Compat.entity_id(face)]
          next unless mat && mat.texture
          face.material = mat unless face.material
          edges = face.outer_loop.edges.select { |e| e.valid? && e.length > 1.0e-6 }
          next if edges.empty?
          edge = edges.max_by(&:length)
          p0 = edge.start.position
          p1 = edge.end.position
          dir = p1 - p0
          len = dir.length
          next if len < 1.0e-6
          dir.normalize!

          helper = face.get_UVHelper(true, false, tw)
          q0 = helper.get_front_UVQ(p0); q1 = helper.get_front_UVQ(p1)
          z0 = q0.z.to_f.abs < 1.0e-12 ? 1.0 : q0.z.to_f
          z1 = q1.z.to_f.abs < 1.0e-12 ? 1.0 : q1.z.to_f
          du = q1.x.to_f/z1 - q0.x.to_f/z0
          dv = q1.y.to_f/z1 - q0.y.to_f/z0
          uv_len = Math.sqrt(du*du + dv*dv)
          # Nếu cạnh dài tình cờ nằm đúng đường đồng UV, lấy scale từ texture Material.
          if uv_len < 1.0e-8
            tex = face.material.texture
            world_per_uv = [tex.width.to_f, tex.height.to_f].select { |x| x > 1.0e-8 }.min
          else
            world_per_uv = len / uv_len
          end
          next unless world_per_uv && world_per_uv > 1.0e-8

          normal = face.normal
          side = normal.cross(dir)
          next if side.length < 1.0e-8
          side.normalize!
          p2 = p0.offset(side, world_per_uv)
          # V chạy dọc lam; U chạy ngang lam. Dùng 1 UV tile làm chuẩn nên không đổi tỷ lệ.
          vspan = len / world_per_uv
          mapping = [
            p0, Geom::Point3d.new(0.0, 0.0, 1.0),
            p1, Geom::Point3d.new(0.0, vspan, 1.0),
            p2, Geom::Point3d.new(1.0, 0.0, 1.0)
          ]
          count += 1 if face.position_material(face.material, mapping, true)
        end
        model.commit_operation
        UI.messagebox("V5.9.9.200: Đã căn MAP theo hướng lam cho #{count} Face.\nVân MAP chạy theo cạnh dài của lam và giữ nguyên tỷ lệ.")
      rescue => e
        model.abort_operation rescue nil
        UI.messagebox("Lỗi MAP THEO HƯỚNG LAM V5.9.9.200\n#{e.class}: #{e.message}")
      end
    end


    # V5.9.9.200: Đồng bộ pha UV ở các lam gần góc miter 45°.
    # Giữ nguyên material, tỷ lệ texture và hình học; chỉ đặt lại gốc UV theo một mốc chung.
    def self.align_map_miter_45
      model = Sketchup.active_model
      selected = model.selection.to_a.select(&:valid?)
      face_items = collect_mapped_faces_from_selection(selected)
      faces = face_items.map(&:first)
      material_for = {}; face_items.each { |f,m| material_for[Compat.entity_id(f)] = m }
      if faces.empty?
        UI.messagebox('V5.9.9.200: Hãy chọn Face/Group lam đã có MAP rồi bấm MAP LIỀN GÓC 45°.')
        return
      end
      pts = faces.flat_map { |f| f.outer_loop.vertices.map(&:position) }
      center = Geom::Point3d.new(pts.sum(&:x)/pts.length.to_f, pts.sum(&:y)/pts.length.to_f, pts.sum(&:z)/pts.length.to_f)
      model.start_operation('LOFIHOME - MAP LIEN GOC 45', true)
      count = 0
      begin
        tw = Sketchup.create_texture_writer
        faces.each do |face|
          mat = face.material || material_for[Compat.entity_id(face)]
          next unless mat && mat.texture
          face.material = mat unless face.material
          edges = face.outer_loop.edges.select { |e| e.valid? && e.length > 1.0e-6 }
          next if edges.empty?
          edge = edges.max_by(&:length)
          a = edge.start.position; b = edge.end.position
          # Đầu gần tâm khung làm mốc pha chung; giúp hai cạnh gặp nhau tại miter không lệch pha.
          p0, p1 = (a.distance(center) <= b.distance(center)) ? [a,b] : [b,a]
          dir = p1 - p0; len = dir.length; next if len < 1.0e-6; dir.normalize!
          helper = face.get_UVHelper(true, false, tw)
          q0 = helper.get_front_UVQ(p0); q1 = helper.get_front_UVQ(p1)
          z0 = q0.z.to_f.abs < 1.0e-12 ? 1.0 : q0.z.to_f; z1 = q1.z.to_f.abs < 1.0e-12 ? 1.0 : q1.z.to_f
          du = q1.x.to_f/z1 - q0.x.to_f/z0; dv = q1.y.to_f/z1 - q0.y.to_f/z0
          uv_len = Math.sqrt(du*du + dv*dv)
          if uv_len < 1.0e-8
            tex = face.material.texture; world_per_uv = [tex.width.to_f, tex.height.to_f].select{|x|x>1.0e-8}.min
          else
            world_per_uv = len / uv_len
          end
          next unless world_per_uv && world_per_uv > 1.0e-8
          side = face.normal.cross(dir); next if side.length < 1.0e-8; side.normalize!
          p2 = p0.offset(side, world_per_uv)
          vspan = len / world_per_uv
          mapping = [p0, Geom::Point3d.new(0,0,1), p1, Geom::Point3d.new(0,vspan,1), p2, Geom::Point3d.new(1,0,1)]
          count += 1 if face.position_material(face.material, mapping, true)
        end
        model.commit_operation
        UI.messagebox("V5.9.9.200: Đã đồng bộ MAP liền góc 45° cho #{count} Face.\nGiữ nguyên tỷ lệ MAP và hình học.")
      rescue => e
        model.abort_operation rescue nil
        UI.messagebox("Lỗi MAP LIỀN GÓC 45° V5.9.9.200\n#{e.class}: #{e.message}")
      end
    end
    # FIX3: use a unique Ruby constant instead of file_loaded? so older Phào Chỉ
    # versions cannot suppress this menu registration. Add a direct Extensions
    # command as well as a uniquely named toolbar for easy verification.
    unless const_defined?(:LOFIHOME_V215_TEST_UI_INSTALLED)
