# Guard interactive tools that can outlive their originating dialog or trial.
[LVN::PhaoChiV305CornerLite::ExternalProfilePickTool, LVN::PhaoChiV305CornerLite::MapTwoPointTool,
 LVN::PhaoChiV305CornerLite::DynamicLibraryPlacement, LVN::PhaoChiV305CornerLite::CNCInsertPlacement,
 LVN::PhaoChiV305CornerLite::SplitPlate::Tool].each { |klass| LVN::PhaoChiV305CornerLite::Licensing.guard_tool(klass) }

# Offer the group invitation once after opening a primary tool, never on install alone.
LVN::PhaoChiV305CornerLite.singleton_class.prepend(LVN::PhaoChiV305CornerLite::ZaloCommunity::EntryHooks) unless LVN::PhaoChiV305CornerLite.singleton_class.ancestors.include?(LVN::PhaoChiV305CornerLite::ZaloCommunity::EntryHooks)
